function divRoundingUp(uint256 x, uint256 y) internal pure returns (uint256 z) {
        assembly ("memory-safe") {
            z := add(div(x, y), gt(mod(x, y), 0))
        }
    }

function simpleMulDiv(uint256 a, uint256 b, uint256 denominator) internal pure returns (uint256 result) {
        assembly ("memory-safe") {
            result := div(mul(a, b), denominator)
        }
    }

function getLiquidityForAmount0(uint160 sqrtPriceAX96, uint160 sqrtPriceBX96, uint256 amount0)
        internal
        pure
        returns (uint128 liquidity)
    {
        unchecked {
            if (sqrtPriceAX96 > sqrtPriceBX96) (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);
            uint256 intermediate = FullMath.mulDiv(sqrtPriceAX96, sqrtPriceBX96, FixedPoint96.Q96);
            return FullMath.mulDiv(amount0, intermediate, sqrtPriceBX96 - sqrtPriceAX96).toUint128();
        }
    }

function getLiquidityForAmount1(uint160 sqrtPriceAX96, uint160 sqrtPriceBX96, uint256 amount1)
        internal
        pure
        returns (uint128 liquidity)
    {
        unchecked {
            if (sqrtPriceAX96 > sqrtPriceBX96) (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);
            return FullMath.mulDiv(amount1, FixedPoint96.Q96, sqrtPriceBX96 - sqrtPriceAX96).toUint128();
        }
    }

function getLiquidityForAmounts(
        uint160 sqrtPriceX96,
        uint160 sqrtPriceAX96,
        uint160 sqrtPriceBX96,
        uint256 amount0,
        uint256 amount1
    ) internal pure returns (uint128 liquidity) {
        if (sqrtPriceAX96 > sqrtPriceBX96) (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);

        if (sqrtPriceX96 <= sqrtPriceAX96) {
            liquidity = getLiquidityForAmount0(sqrtPriceAX96, sqrtPriceBX96, amount0);
        } else if (sqrtPriceX96 < sqrtPriceBX96) {
            uint128 liquidity0 = getLiquidityForAmount0(sqrtPriceX96, sqrtPriceBX96, amount0);
            uint128 liquidity1 = getLiquidityForAmount1(sqrtPriceAX96, sqrtPriceX96, amount1);

            liquidity = liquidity0 < liquidity1 ? liquidity0 : liquidity1;
        } else {
            liquidity = getLiquidityForAmount1(sqrtPriceAX96, sqrtPriceBX96, amount1);
        }
    }

constructor(address initialGovernance, address initialKeeper, address initialGuardian) {
        if (initialGovernance == address(0) || initialGovernance == address(this) ||
            initialKeeper == address(0) || initialGuardian == address(0)) revert InvalidConfiguration();
        governance = initialGovernance;
        bootstrap = msg.sender;
        royaltyFactory = address(new ZZZRoyaltyFactory());
        activationAssetsFactory = address(new ZZZActivationAssetsFactory());
        keepers[initialKeeper] = true;
        emit KeeperChanged(initialKeeper, true);
        guardians[initialGuardian] = true;
        emit GuardianChanged(initialGuardian, true);
    }

function canConfigure(address account) public view returns (bool) {
        return !preparationActive && ((isSealed && canonicalState == 0 && account == governance) ||
            (!isSealed && account == bootstrap));
    }

function proposeGovernance(address candidate) external {
        if (msg.sender != governance || canonicalState != 0 || preparationActive) revert Unauthorized();
        if (candidate == address(this) || candidate == governance) revert InvalidConfiguration();
        pendingGovernance = candidate;
        emit GovernanceProposed(governance,candidate);
    }

function acceptGovernance() external {
        if (msg.sender != pendingGovernance || msg.sender == address(0) ||
            canonicalState != 0 || preparationActive) revert Unauthorized();
        address previous=governance;governance=msg.sender;pendingGovernance=address(0);
        emit GovernanceAccepted(previous,msg.sender);
    }

function moduleAuthorized(bytes32 id, address caller) external view returns (bool) {
        return isSealed && canonicalState == 0 && caller != address(0) && caller == module[id];
    }

function keeperAuthorized(address caller) external view returns (bool) {
        return isSealed && canonicalState == 0 && keepers[caller];
    }

function startLPExit() external {
        if (msg.sender != module[Ids.VAULT] || !isSealed || !paused || lpExitStarted ||
            preparationActive || canonicalState != 0) revert Unauthorized();
        lpExitStarted = true;
        emit LPExitStarted();
    }

function canonicalTransition(uint8 state, bool settling, bool clearPreparation) external {
        if (lpExitStarted || msg.sender != canonicalHandoff() || msg.sender == address(0) || state > 4 || (settling && state != 1)) revert Unauthorized();
        // States 3/4 are terminal; any impossible higher state also fails closed.
        if (canonicalState > 2) revert InvalidConfiguration();
        canonicalState = state;
        canonicalSettling = settling;
        if (clearPreparation) preparationActive = false;
    }

function startPreparation(PreparationNotice calldata notice) external {
        if (msg.sender != governance || !isSealed || preparationActive || lpExitStarted || canonicalState != 0) revert Unauthorized();
        if (IZZZVault(module[Ids.VAULT]).canonicalChainId() != block.chainid ||
            notice.destinationChain != block.chainid || notice.successorController == address(0) ||
            (notice.destinationChain == block.chainid && notice.successorController == address(this)) ||
            notice.deploymentCommitment == bytes32(0) || notice.reviewHash == bytes32(0)) revert InvalidConfiguration();
        preparationReadyDestination = false;
        if (notice.destinationChain == block.chainid && notice.successorController.code.length != 0) {
            IZZZAccess destination = IZZZAccess(notice.successorController);
            // Freeze cannot authenticate a configuration that bootstrap changed
            // after the notice was reviewed. A usable local importer is already
            // sealed, inert and bound to this source when announcement executes.
            if (!destination.isSealed() || destination.canonicalState() != 2) revert InvalidConfiguration();
            ZZZCanonicalHandoff handoff = ZZZCanonicalHandoff(destination.canonicalHandoff());
            if (handoff.incomingSource() != address(this) ||
                handoff.deploymentCommitment() != notice.deploymentCommitment) revert InvalidConfiguration();
            preparationReadyDestination = true;
        }
        uint256 nonce = ++preparationNonce;
        bytes32 noticeHash = keccak256(abi.encode("ZZZ_CANONICAL_PREPARATION_V1", block.chainid, address(this),
            module[Ids.VAULT], module[Ids.NFT], nonce, notice));
        preparationNotice = notice;
        preparationHash = noticeHash;
        preparationStartedAt = block.timestamp;
        preparationActive = true;
        emit PreparationStarted(noticeHash, nonce, notice.destinationChain, notice.successorController,
            notice.deploymentCommitment, notice.reviewHash);
    }

function cancelPreparation(bytes32 noticeHash) external {
        if (msg.sender != governance || !preparationActive || canonicalState != 0) revert Unauthorized();
        if (noticeHash != preparationHash) revert InvalidConfiguration();
        preparationActive = false;
        emit PreparationCancelled(noticeHash);
    }

function bind(bytes32 id, address implementation) external {
        if (msg.sender != bootstrap || isSealed) revert Unauthorized();
        bytes32[16] memory supported=_moduleIds();bool known;
        for(uint256 i;i<supported.length;++i)if(id==supported[i]){known=true;break;}
        if(!known)revert InvalidConfiguration();
        if (implementation.code.length == 0 || module[id] != address(0) ||
            address(IZZZBound(implementation).access()) != address(this)) revert InvalidConfiguration();
        module[id] = implementation;
        emit ModuleBound(id, implementation);
    }

function seal() external {
        if (msg.sender != bootstrap || isSealed) revert Unauthorized();
        bytes32[16] memory required = _moduleIds();
        for (uint256 i; i < required.length; ++i) {
            if (module[required[i]].code.length == 0) revert InvalidConfiguration();
            for (uint256 j; j < i; ++j) {
                if (module[required[i]] == module[required[j]]) revert InvalidConfiguration();
            }
        }
        if (ICanonicalOwnerBinding(module[Ids.NFT_CANONICAL]).nft() != module[Ids.NFT] ||
            ICanonicalOwnerBinding(module[Ids.VAULT_CANONICAL]).vault() != module[Ids.VAULT] ||
            ICanonicalOwnerBinding(module[Ids.FEES_CANONICAL]).fees() != module[Ids.FEES]) revert InvalidConfiguration();

        // The source identity is bootstrap-only. Never seal an unset token and
        // leave a deployment unable to accept its intended ZZZ contributions.
        address sourceZZZ = IContributionRegistry(module[Ids.POOLS]).activationAssets().zzz();
        if (sourceZZZ == address(0) || IExitIdentity(module[Ids.MIGRATION]).currentZZZ() != sourceZZZ) revert InvalidConfiguration();

        // NFT randomness is configured only before sealing. Do not irreversibly
        // lock the canonical collection while its mint configuration is absent.
        if (IZZZVault(module[Ids.VAULT]).canonicalChainId() == block.chainid &&
            !IZZZNFT(module[Ids.NFT]).randomnessConfigured()) revert InvalidConfiguration();
        isSealed = true;
        bootstrap = address(0);
        emit SystemSealed();
    }

function setKeeper(address who, bool enabled) external {
        if (!canConfigure(msg.sender) || who == address(0)) revert Unauthorized();
        keepers[who] = enabled;
        emit KeeperChanged(who, enabled);
    }

function setGuardian(address who, bool enabled) external {
        if (!canConfigure(msg.sender) || who == address(0)) revert Unauthorized();
        guardians[who] = enabled;
        emit GuardianChanged(who, enabled);
    }

function setPaused(bool state) external {
        // Pause control remains available to drain incoming custody and park it.
        // Unpausing never bypasses the separate preparation guards.
        if (msg.sender != governance && !(!isSealed && msg.sender == bootstrap) &&
            !(state && guardians[msg.sender])) revert Unauthorized();
        paused = state;
        emit PauseChanged(state);
    }

function _moduleIds() private pure returns(bytes32[16] memory) {
        return [Ids.VAULT,Ids.NFT,Ids.LIQUIDITY,Ids.REWARDS,Ids.MEMBERSHIP,
            Ids.FEES,Ids.STRATEGY,Ids.COMPOUNDER,Ids.BUYBACK,Ids.MIGRATION,
            Ids.ORACLE,Ids.POOLS,Ids.CANONICAL,Ids.NFT_CANONICAL,Ids.VAULT_CANONICAL,Ids.FEES_CANONICAL];
    }

constructor(address controller, address poolRegistry) ZZZModule(controller) {
        if (poolRegistry == address(0) || msg.sender != access.activationAssetsFactory() ||
            IActivationAssetsFactoryIdentity(msg.sender).access() != controller) revert InvalidConfiguration();
        registry = poolRegistry;
    }

function isContributionAsset(address token) public view returns (bool) {
        return token == address(0) || (zzz != address(0) && token == zzz);
    }

function configureZZZ(address token, bytes32 expectedCodeHash, bytes32 reviewHash)
        external onlyGovernance returns (bytes32 id) {
        if (zzz != address(0) || access.isSealed() || token == address(0) || reviewHash == bytes32(0)) revert InvalidConfiguration();
        uint8 decimals = _validate(token, expectedCodeHash);
        zzz = token;
        id = _record(Policy(token, true, expectedCodeHash, reviewHash, decimals, false));
        emit ZZZIdentityConfigured(token, expectedCodeHash, reviewHash);
    }

function setAsset(address token, bool enabled, bytes32 expectedCodeHash, bytes32 reviewHash)
        external onlyGovernance returns (bytes32 id) {
        if (reviewHash == bytes32(0)) revert InvalidConfiguration();
        bytes32 previous = activePolicy[token];
        uint8 decimals = previous == bytes32(0) ? 0 : policies[previous].decimals;
        if (enabled) {
            if (!isContributionAsset(token)) revert InvalidConfiguration();
            decimals = _validate(token, expectedCodeHash);
        }
        return _record(Policy(token, enabled, expectedCodeHash, reviewHash, decimals, false));
    }

function admitPoolAsset(address token) external returns (bytes32 id) {
        if (msg.sender != registry) revert Unauthorized();
        id = activePolicy[token];
        if (id != bytes32(0)) return id;
        bytes32 codeHash = token == address(0) ? NATIVE_ASSET_CODE_HASH : token.codehash;
        uint8 decimals = _validate(token, codeHash);
        // This binds the authenticated pool-configuration admission, not an
        // independent audit. Explicit reviews use governance's supplied hash.
        bytes32 admissionReference = keccak256(abi.encode("ZZZ_POOL_ASSET_ADMISSION_V1", registry, token, codeHash, decimals));
        // A target pair may use another accounting currency (for example WETH).
        // Pool admission must not make that currency an externally supplied asset.
        return _record(Policy(token, isContributionAsset(token), codeHash, admissionReference, decimals, true));
    }

function _record(Policy memory policy) private returns (bytes32 id) {
        bytes32 previous = activePolicy[policy.token];
        // Ordinal is part of identity: previous records can never be overwritten
        // even when governance later returns to identical policy parameters.
        id = keccak256(abi.encode(address(this), history.length, policy));
        policies[id] = policy;
        history.push(id);
        activePolicy[policy.token] = id;
        emit AssetPolicyRecorded(id, policy.token, policy.enabled, policy.expectedCodeHash,
            policy.reviewHash, policy.decimals, policy.poolAdmission);
        emit AssetPolicyActivated(policy.token, previous, id);
    }

function _validate(address token, bytes32 expectedCodeHash) private view returns (uint8 decimals) {
        if (token == address(0)) {
            if (expectedCodeHash != NATIVE_ASSET_CODE_HASH) revert InvalidConfiguration();
            decimals = 18;
        } else {
            if (expectedCodeHash == bytes32(0) || token.code.length == 0 || token.codehash != expectedCodeHash) {
                revert InvalidConfiguration();
            }
            decimals = IERC20Metadata(token).decimals();
        }
        if (decimals > 18) revert InvalidConfiguration();
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        if (oracle.tokenDecimals(token) != decimals || oracle.price(token) == 0) revert InvalidConfiguration();
    }

function value(address token, uint256 amount) external view returns (uint256) {
        if (amount == 0) return 0;
        if (!isContributionAsset(token)) revert InvalidConfiguration();
        Policy memory policy = policies[activePolicy[token]];
        if (!policy.enabled || (token == address(0) ?
            policy.expectedCodeHash != NATIVE_ASSET_CODE_HASH || policy.decimals != 18 :
            policy.expectedCodeHash == bytes32(0) || token.code.length == 0 || token.codehash != policy.expectedCodeHash)) {
            revert InvalidConfiguration();
        }
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        if (oracle.tokenDecimals(token) != policy.decimals) revert InvalidConfiguration();
        return oracle.value(token, amount);
    }

function create() external returns(address child) {
        if (assetsOf[msg.sender]!=address(0)) revert AlreadyCreated();
        child=address(new ZZZActivationAssets(access,msg.sender));
        assetsOf[msg.sender]=child;
    }

constructor(address controller, address poolRegistry, address assets) ZZZModule(controller) {
        if (poolRegistry == address(0) || msg.sender != poolRegistry || assets.code.length == 0 ||
            ZZZActivationAssets(assets).registry() != poolRegistry ||
            address(ZZZActivationAssets(assets).access()) != controller) revert InvalidConfiguration();
        registry = poolRegistry;
        activationAssets = ZZZActivationAssets(assets);
        v4Executor = new ZZZV4RouteExecutor();
    }

receive() external payable {
        if (nativeSender == address(0) || msg.sender != nativeSender) revert Unauthorized();
        nativeReceived += msg.value;
    }

function addRoute(RoutePolicy calldata policy) external onlyGovernance operating nonReentrant returns (bytes32 id) {
        _checkRoute(policy);
        id = keccak256(abi.encode(policy));
        if (routeExists(id)) revert InvalidConfiguration();
        routes[id] = policy;
        v3RouteExists[id] = true;
        v3RouteEnabled[id] = true;
        emit RouteRecorded(id, policy.source, policy.output, policy.router, policy.pool, policy.fee, policy.reviewHash);
        emit RouteEnabled(id, true);
    }

function route(bytes32 id) external view returns (RoutePolicy memory) {
        if (!v3RouteExists[id]) revert InvalidConfiguration();
        return routes[id];
    }

function routeKind(bytes32 id) public view returns (uint8) {
        if (v3RouteExists[id]) return 1;
        return v4Executor.routeExists(id) ? 2 : 0;
    }

function routeEnabled(bytes32 id) public view returns (bool) {
        return v3RouteExists[id] ? v3RouteEnabled[id] : v4Executor.routeEnabled(id);
    }

function addV4Route(ZZZV4RouteExecutor.Policy calldata policy)
        external onlyGovernance operating nonReentrant returns (bytes32 id) {
        if (!activationAssets.isContributionAsset(policy.source)) revert InvalidConfiguration();
        id = v4Executor.addRoute(policy);
        if (v3RouteExists[id]) revert InvalidConfiguration();
        emit RouteEnabled(id, true);
    }

function v4Route(bytes32 id) external view returns (ZZZV4RouteExecutor.Policy memory) {
        return v4Executor.route(id);
    }

function setRouteEnabled(bytes32 id, bool enabled) external onlyGovernance operating nonReentrant {
        if (v3RouteExists[id]) {
            if (enabled) _checkRoute(routes[id]);
            v3RouteEnabled[id] = enabled;
        } else {
            if (enabled && !activationAssets.isContributionAsset(v4Executor.route(id).source)) revert InvalidConfiguration();
            v4Executor.setRouteEnabled(id, enabled);
        }
        emit RouteEnabled(id, enabled);
    }

function _pin(address target, bytes32 expected) private view {
        if (expected == bytes32(0) || target.code.length == 0 || target.codehash != expected) revert InvalidConfiguration();
    }

function _checkRoute(RoutePolicy memory p) private view {
        if (p.source == address(0) || p.output == address(0) || p.source == p.output ||
            !activationAssets.isContributionAsset(p.source) ||
            p.reviewHash == bytes32(0) || p.fee >= 1_000_000) revert InvalidConfiguration();
        _pin(p.source, p.sourceCodeHash); _pin(p.output, p.outputCodeHash);
        _pin(p.router, p.routerCodeHash); _pin(p.factory, p.factoryCodeHash); _pin(p.pool, p.poolCodeHash);
        ZZZV3VenueValidation.validate(p.router, p.factory, p.pool, p.source, p.output, p.fee);
    }

function _owner(uint256 id) private view returns (address) {
        return IZZZNFT(access.module(Ids.NFT)).ownerOf(id);
    }

function _vault() private view returns (address vault) {
        vault = access.module(Ids.VAULT);
        if (!access.isSealed() || access.module(Ids.POOLS) != registry || vault.code.length == 0) revert InvalidConfiguration();
    }

function validateOwner(uint256 id, bytes32 vaultCallHash) external view {
        Context memory c = context;
        if (msg.sender != _vault() || c.owner == address(0) || c.nftId != id ||
            c.callHash != vaultCallHash || _owner(id) != c.owner) revert Unauthorized();
    }

function sourceValue(bytes32 poolId, uint256 amount0, uint256 amount1) external view returns (uint256) {
        if (msg.sender != registry) revert Unauthorized();
        Context memory c = context;
        if (c.owner == address(0)) return 0;
        if (c.poolId != poolId || c.amount0 != amount0 || c.amount1 != amount1 ||
            _owner(c.nftId) != c.owner) revert InvalidState();
        return c.grossUSD;
    }

function _pricing() private view returns(ZZZContributionPricing) {
        return ZZZContributionPricing(IZZZOracle(access.module(Ids.ORACLE)).contributionPricing());
    }

function pricingContext(uint256 id,bytes32 pool,uint256 packed,uint256 gross) external view returns(bool) {
        if (msg.sender != address(_pricing())) revert Unauthorized();
        Context memory c = context;
        return c.owner != address(0) && c.nftId == id && c.poolId == pool && c.grossUSD == gross &&
            c.amount0 <= type(uint128).max && c.amount1 <= type(uint128).max &&
            packed == (c.amount0 | (c.amount1 << 128)) && _owner(id) == c.owner;
    }

function _convertV4(Request calldata r, address output, uint256 sourceBaseline, uint256 outputBaseline)
        private returns (uint256 acquired) {
        ExactAsset.approve(r.sourceAsset,address(v4Executor),r.amountIn);
        nativeReceived = 0;
        nativeSender = output == address(0) ? address(v4Executor) : address(0);
        acquired = v4Executor.execute{value:r.sourceAsset == address(0) ? r.amountIn : 0}(
            r.routeId,r.amountIn,r.minimumOut,r.deadline);
        nativeSender = address(0);
        ExactAsset.approve(r.sourceAsset,address(v4Executor),0);
        if (acquired < r.minimumOut || (output == address(0) && nativeReceived != acquired) ||
            ExactAsset.balance(r.sourceAsset,address(this)) != sourceBaseline ||
            ExactAsset.balance(output,address(this)) != outputBaseline+acquired) revert InvalidState();
        nativeReceived = 0;
    }

function executeReviewed(Request calldata request, uint16 maximumLossBps)
        external payable live operating principalOperating nonReentrant {
        _deadline(request.deadline);
        address vault = _vault();
        if (request.amountIn == 0 || request.minimumLiquidity == 0 || _owner(request.nftId) != msg.sender) revert Unauthorized();
        PoolConfig memory pool = IZZZPools(registry).accounting(request.poolId);
        if (!pool.depositsEnabled || !pool.operationsEnabled ||
            pool.key.currency0 == pool.key.currency1) revert InvalidConfiguration();
        address source = request.sourceAsset;
        if (!activationAssets.isContributionAsset(source)) revert InvalidConfiguration();
        address output;
        RoutePolicy memory policy;
        uint8 kind;
        if (msg.value != (source == address(0) ? request.amountIn : 0)) revert InvalidAmount();
        if (request.routeId == bytes32(0)) {
            if (request.minimumOut != 0) revert InvalidAmount();
            output = source;
        } else {
            kind = routeKind(request.routeId);
            if (!routeEnabled(request.routeId) || request.minimumOut == 0) revert InvalidConfiguration();
            if (kind == 2) {
                ZZZV4RouteExecutor.Policy memory v4 = v4Executor.validate(request.routeId);
                if (v4.source != source) revert InvalidConfiguration();
                output = v4.output;
            } else {
                if (kind != 1 || source == address(0)) revert InvalidConfiguration();
                policy = routes[request.routeId];
                if (policy.source != source) revert InvalidConfiguration();
                _checkRoute(policy);
                output = policy.output;
            }
        }
        if (output != pool.key.currency0 && output != pool.key.currency1) revert InvalidConfiguration();
        uint256 nativeBaseline = address(this).balance - msg.value;
        uint256 sourceBaseline = ExactAsset.balance(source,address(this)) - (source == address(0) ? msg.value : 0);
        uint256 outputBaseline = ExactAsset.balance(output,address(this)) - (output == address(0) ? msg.value : 0);
        // Admit and freeze source + LP-pair prices BEFORE a token pull, approval
        // or conversion can call external code. Both bounds come from two sources.
        uint256 grossUSD = activationAssets.value(source, request.amountIn);
        if (_pricing().beginEntryReviewed(request.nftId,request.poolId,source,request.amountIn,maximumLossBps) != grossUSD) revert InvalidState();
        if (source != address(0)) ExactToken.pull(source, msg.sender, request.amountIn);
        if (grossUSD == 0 || (!request.increase && grossUSD < 100e18) ||
            (request.increase && grossUSD < 5e18)) revert InvalidAmount();
        uint256 acquired = request.amountIn;
        if (kind == 2) {
            acquired = _convertV4(request,output,sourceBaseline,outputBaseline);
        } else if (kind == 1) {
            IERC20(source).forceApprove(policy.router, request.amountIn);
            acquired = IV3RouteRouter(policy.router).exactInputSingle(IV3RouteRouter.ExactInputSingleParams(
                source, output, policy.fee, address(this), request.amountIn, request.minimumOut, 0));
            IERC20(source).forceApprove(policy.router, 0);
            if (acquired < request.minimumOut || IERC20(source).balanceOf(address(this)) != sourceBaseline ||
                IERC20(output).balanceOf(address(this)) != outputBaseline + acquired) revert InvalidState();
        }
        if (_owner(request.nftId) != msg.sender) revert Unauthorized();
        uint256 amount0 = output == pool.key.currency0 ? acquired : 0;
        uint256 amount1 = output == pool.key.currency1 ? acquired : 0;
        bytes memory payload = request.increase
            ? abi.encodeCall(IActivationVault.increase, (request.nftId, amount0, amount1, request.minimumLiquidity, request.deadline))
            : abi.encodeCall(IActivationVault.activate, (request.nftId, request.poolId, amount0, amount1, request.minimumLiquidity, request.deadline));
        // Token approval can call arbitrary token code. Context must remain
        // inactive until the immediate Vault call, whose own guard then protects
        // contribution valuation against unrelated callback-driven joins.
        ExactAsset.approve(output,vault, acquired);
        if (_owner(request.nftId) != msg.sender) revert Unauthorized();
        context = Context(msg.sender, request.nftId, keccak256(payload), request.poolId, amount0, amount1, grossUSD);
        (bool success, bytes memory result) = vault.call{value: output == address(0) ? acquired : 0}(payload);
        if (!success) assembly ("memory-safe") { revert(add(result, 32), mload(result)) }
        delete context;
        ExactAsset.approve(output,vault, 0);
        if (_owner(request.nftId) != msg.sender || ExactAsset.balance(output,address(this)) != outputBaseline ||
            ExactAsset.balance(source,address(this)) != sourceBaseline || address(this).balance != nativeBaseline) revert InvalidState();
        _pricing().endEntry();
        emit SourceContributed(msg.sender, request.nftId, request.poolId, request.sourceAsset,
            request.amountIn, grossUSD, output, acquired, request.increase);
    }

constructor(address controller, address zzzToken, uint256 maximumTradeUSD) ZZZModule(controller) {
        if (zzzToken.code.length == 0 || maximumTradeUSD == 0) revert InvalidConfiguration();
        zzz = zzzToken;
        maxTradeUSD = maximumTradeUSD;
        operatingTradeUSD = maximumTradeUSD;
    }

receive() external payable {
        if (msg.sender != access.module(Ids.FEES)) revert Unauthorized();
    }

function setOperatingTradeUSD(uint256 limit) external onlyGovernance operating nonReentrant {
        if (limit > maxTradeUSD) revert InvalidConfiguration();
        uint256 previous = operatingTradeUSD;
        operatingTradeUSD = limit;
        emit OperatingTradeLimitChanged(previous, limit);
    }

function execute(address token, uint256 amount, bytes32 poolId, uint256 deadline) external onlyKeeper live operating nonReentrant {
        _deadline(deadline);
        if (amount == 0 || operatingTradeUSD == 0) revert InvalidAmount();
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        // The maximum spend must hold at either admitted source price. Ordinary
        // Oracle.value is the lower mark for minimum contributions/display; it
        // can understate a trade budget. Round the upper input value upward.
        (, uint256 upper,) = oracle.priceBounds(token);
        if (Math.mulDiv(amount, upper, 10 ** oracle.tokenDecimals(token), Math.Rounding.Ceil) > operatingTradeUSD)
            revert InvalidAmount();
        uint256 beforeZZZ = IERC20(zzz).balanceOf(address(this));
        uint256 beforeInput = ExactAsset.balance(token,address(this));
        IZZZFees(access.module(Ids.FEES)).releaseBuyback(token, amount);
        if (ExactAsset.balance(token,address(this)) != beforeInput + amount) revert InvalidState();
        uint256 acquired = amount;
        if (token != zzz) {
            PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
            bool zeroForOne = c.key.currency0 == token && c.key.currency1 == zzz;
            if (!zeroForOne && !(c.key.currency1 == token && c.key.currency0 == zzz)) revert InvalidConfiguration();
            uint256 minimum = Math.mulDiv(oracle.quote(token, zzz, amount), 10000 - c.maxSlippageBps, 10000);
            address manager = access.module(Ids.LIQUIDITY);
            ExactAsset.approve(token,manager, amount);
            acquired = IZZZLiquidity(manager).swap{value: token == address(0) ? amount : 0}(poolId, zeroForOne, amount, minimum, deadline);
            ExactAsset.approve(token,manager, 0);
            if (ExactAsset.balance(token,address(this)) != beforeInput) revert InvalidState();
        }
        if (IERC20(zzz).balanceOf(address(this)) != beforeZZZ + acquired) revert InvalidState();
        uint256 supplyBefore = IBurnable(zzz).totalSupply();
        IBurnable(zzz).burn(acquired);
        if (IBurnable(zzz).totalSupply() + acquired != supplyBefore ||
            IERC20(zzz).balanceOf(address(this)) != beforeZZZ) revert InvalidState();
        emit BoughtAndBurned(token, amount, acquired);
        if (!access.keeperAuthorized(msg.sender) || access.paused()) revert Unauthorized();
    }

constructor(address controller) {
        access = ICanonicalController(controller);
    }

modifier governance() {
        if (msg.sender != access.governance() || !access.isSealed()) revert Unauthorized();
        _;
    }

function moduleAt(uint8 slot) public view returns (address) {
        if (slot == DOMAIN_NFT) return access.module(Ids.NFT_CANONICAL);
        if (slot == DOMAIN_VAULT) return ICanonicalHelpers(access.module(Ids.VAULT)).canonicalModule();
        if (slot == DOMAIN_MEMBERSHIP) return access.module(Ids.MEMBERSHIP);
        if (slot == DOMAIN_LP_REWARDS) return access.module(Ids.REWARDS);
        if (slot == DOMAIN_ROYALTIES) return ICanonicalHelpers(access.module(Ids.NFT)).royaltyRewards();
        if (slot == DOMAIN_FEES) return access.module(Ids.FEES_CANONICAL);
        revert InvalidState();
    }

function _module(uint8 slot) private view returns (IZZZCanonicalModule) {
        return IZZZCanonicalModule(moduleAt(slot));
    }

function _peer(address controller) private view returns (ZZZCanonicalHandoff) {
        return ZZZCanonicalHandoff(IZZZAccess(controller).canonicalHandoff());
    }

function deploymentCommitment() public view returns (bytes32 result) {
        if (!access.isSealed()) revert InvalidState();
        result = keccak256(
            abi.encode(
                SCHEMA,
                block.chainid,
                address(access),
                address(this),
                address(access).codehash,
                address(this).codehash,
                incomingSource
            )
        );
        bytes32[16] memory ids = [
            Ids.VAULT,
            Ids.NFT,
            Ids.LIQUIDITY,
            Ids.REWARDS,
            Ids.MEMBERSHIP,
            Ids.FEES,
            Ids.STRATEGY,
            Ids.COMPOUNDER,
            Ids.BUYBACK,
            Ids.MIGRATION,
            Ids.ORACLE,
            Ids.POOLS,
            Ids.CANONICAL,
            Ids.NFT_CANONICAL,
            Ids.VAULT_CANONICAL,
            Ids.FEES_CANONICAL
        ];
        for (uint256 i; i < ids.length; ++i) {
            address target = access.module(ids[i]);
            if (target.code.length == 0) revert InvalidState();
            result = keccak256(abi.encode(result, ids[i], target, target.codehash));
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            address target = moduleAt(slot);
            result = keccak256(abi.encode(result, slot, target, target.codehash));
        }
    }

function prepareImport(address sourceController) external nonReentrant {
        if (
            access.isSealed() || msg.sender != access.bootstrap() || phase != PHASE_IDLE
                || sourceController == address(access) || sourceController.code.length == 0
                || !IZZZAccess(sourceController).isSealed()
        ) revert Unauthorized();
        if (IZZZVault(access.module(Ids.VAULT)).canonicalChainId() != block.chainid) revert UnsupportedTransport();
        if (_peer(sourceController).SCHEMA() != SCHEMA) revert UnsupportedTransport();
        incomingSource = sourceController;
        phase = PHASE_IMPORTING;
        access.canonicalTransition(STATE_IMPORTING, false, false);
        emit ImportPrepared(sourceController);
    }

function freeze() external governance nonReentrant {
        if (
            access.lpExitStarted() || (phase != PHASE_IDLE && phase != PHASE_ACTIVE_REPLACEMENT) || !access.preparationActive()
                || access.canonicalState() != STATE_OPERATING || !access.preparationReadyDestination()
        ) {
            revert InvalidState();
        }
        (uint256 chain, address destination, bytes32 deployment,) = access.preparationNotice();
        if (chain != block.chainid) revert UnsupportedTransport();
        ZZZCanonicalHandoff peer = _peer(destination);
        if (
            !IZZZAccess(destination).isSealed() || peer.SCHEMA() != SCHEMA || peer.phase() != PHASE_IMPORTING
                || peer.incomingSource() != address(access) || peer.deploymentCommitment() != deployment
        ) {
            revert InvalidState();
        }
        if (IZZZVault(IZZZAccess(destination).module(Ids.VAULT)).canonicalChainId() != block.chainid) {
            revert UnsupportedTransport();
        }
        // Every bucket must be parked and have no active custody handoff.
        // Capture enforces that boundary; no retired v3 channel is admitted.
        destinationController = destination;
        destinationDeployment = deployment;
        handoffId = keccak256(
            abi.encode(
                SCHEMA,
                block.chainid,
                address(access),
                address(this),
                destination,
                address(peer),
                access.preparationHash(),
                deployment
            )
        );
        phase = PHASE_SETTLING;
        settlementCursor = 0;
        stateRoot = bytes32(0);
        // Establish the guard BEFORE any external balance observation. Capture
        // every module first, then process only those immutable cutoffs.
        access.canonicalTransition(STATE_FROZEN, false, false);
        for (uint8 slot; slot < SLOTS; ++slot) {
            _module(slot).canonicalCapture();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            recordCount[slot] = _module(slot).canonicalCount();
            assetCount[slot] = _module(slot).canonicalAssetCount();
            if (recordCount[slot] == 0 || assetCount[slot] > 256) {
                revert InvalidState();
            }
            exportCursor[slot] = 0;
            exportRoot[slot] = bytes32(0);
            for (uint256 index; index < assetCount[slot]; ++index) {
                funded[slot][index] = false;
                returned[slot][index] = false;
            }
        }
        peer.bindFrozen(handoffId);
        emit Frozen(handoffId, destination);
    }

function settle(uint8 slot) external nonReentrant {
        if (phase != PHASE_SETTLING || slot != settlementCursor || slot >= SLOTS) revert InvalidState();
        access.canonicalTransition(STATE_FROZEN, true, false);
        _module(slot).canonicalSettle();
        access.canonicalTransition(STATE_FROZEN, false, false);
        settlementCursor = slot + 1;
        if (settlementCursor == SLOTS) phase = PHASE_EXPORTING;
        emit DomainSettled(handoffId, slot);
    }

function bindFrozen(bytes32 id) external {
        if (phase != PHASE_IMPORTING || msg.sender != address(_peer(incomingSource)) || handoffId != bytes32(0)) {
            revert Unauthorized();
        }
        handoffId = id;
        ZZZCanonicalHandoff source = ZZZCanonicalHandoff(msg.sender);
        if (source.handoffId() != id || source.destinationController() != address(access)) revert InvalidState();
        for (uint8 slot; slot < SLOTS; ++slot) {
            recordCount[slot] = source.recordCount(slot);
            assetCount[slot] = source.assetCount(slot);
        }
    }

function _next(bytes32 previous, uint8 slot, uint256 row, bytes memory record) private view returns (bytes32) {
        return keccak256(abi.encode(handoffId, slot, row, previous, keccak256(record)));
    }

function exportRows(uint8 slot, uint256 count) external nonReentrant {
        if (
            phase != PHASE_EXPORTING || slot >= SLOTS || count == 0 || count > MAX_ROWS
                || exportCursor[slot] + count > recordCount[slot]
        ) revert InvalidState();
        uint256 end = exportCursor[slot] + count;
        for (uint256 row = exportCursor[slot]; row < end; ++row) {
            bytes memory record = _module(slot).canonicalExport(row);
            exportRoot[slot] = _next(exportRoot[slot], slot, row, record);
            emit RecordExported(handoffId, slot, row, record);
        }
        exportCursor[slot] = end;
        bool complete = true;
        for (uint8 i; i < SLOTS; ++i) {
            if (exportCursor[i] != recordCount[i]) complete = false;
        }
        if (complete) {
            stateRoot = keccak256(abi.encode(handoffId, recordCount, assetCount, exportRoot));
            emit SnapshotCommitted(handoffId, stateRoot);
        }
    }

function importRows(uint8 slot, bytes[] calldata records) external nonReentrant {
        if (
            phase != PHASE_IMPORTING || slot >= SLOTS || records.length == 0 || records.length > MAX_ROWS
                || importCursor[slot] + records.length > recordCount[slot]
        ) revert InvalidState();
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (source.phase() != PHASE_EXPORTING || source.stateRoot() == bytes32(0) || source.handoffId() != handoffId) {
            revert InvalidState();
        }
        IZZZCanonicalModule sourceModule = IZZZCanonicalModule(source.moduleAt(slot));
        for (uint256 i; i < records.length; ++i) {
            uint256 row = importCursor[slot]++;
            if (keccak256(records[i]) != keccak256(sourceModule.canonicalExport(row))) revert InvalidRecord();
            _module(slot).canonicalImport(row, records[i]);
            importRoot[slot] = _next(importRoot[slot], slot, row, records[i]);
            emit RecordImported(handoffId, slot, row);
        }
    }

function completeImport() external nonReentrant {
        if (phase != PHASE_IMPORTING) revert InvalidState();
        ZZZCanonicalHandoff source = _peer(incomingSource);
        for (uint8 slot; slot < SLOTS; ++slot) {
            if (
                importCursor[slot] != recordCount[slot] || importRoot[slot] != source.exportRoot(slot)
                    || _module(slot).canonicalCount() != recordCount[slot]
                    || _module(slot).canonicalAssetCount() != assetCount[slot]
            ) revert InvalidRecord();
        }
        stateRoot = keccak256(abi.encode(handoffId, recordCount, assetCount, importRoot));
        if (source.phase() != PHASE_EXPORTING || stateRoot == bytes32(0) || stateRoot != source.stateRoot()) {
            revert InvalidRecord();
        }
        importComplete = true;
        phase = PHASE_IMPORTED_AWAITING_BACKING;
    }

function _balance(address asset, address owner) private view returns (uint256) {
        return asset == address(0) ? owner.balance : IERC20(asset).balanceOf(owner);
    }

function fund(uint8 slot, uint256 index) external nonReentrant {
        if (phase != PHASE_EXPORTING || slot >= SLOTS || index >= assetCount[slot] || funded[slot][index]) {
            revert InvalidState();
        }
        ZZZCanonicalHandoff peer = _peer(destinationController);
        if (peer.phase() != PHASE_IMPORTED_AWAITING_BACKING || peer.stateRoot() != stateRoot || stateRoot == bytes32(0))
        revert InvalidState();
        (address asset, uint256 amount) = _module(slot).canonicalBacking(index);
        IZZZCanonicalModule destination = IZZZCanonicalModule(peer.moduleAt(slot));
        (address otherAsset, uint256 otherAmount) = destination.canonicalBacking(index);
        if (otherAsset != asset || otherAmount != amount) revert InvalidBacking();
        funded[slot][index] = true;
        uint256 beforeBalance = _balance(asset, address(destination));
        _module(slot).canonicalRelease(index, address(destination));
        if (_balance(asset, address(destination)) != beforeBalance + amount) revert InvalidBacking();
        peer.acceptFunding(slot, index);
        emit BackingTransferred(handoffId, slot, index, asset, amount);
    }

function acceptFunding(uint8 slot, uint256 index) external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || phase != PHASE_IMPORTED_AWAITING_BACKING || slot >= SLOTS
                || index >= assetCount[slot] || incomingFunded[slot][index] || !source.funded(slot, index)
        ) revert Unauthorized();
        incomingFunded[slot][index] = true;
        _module(slot).canonicalAccept(index, source.moduleAt(slot));
    }

function _allFunded() private view {
        for (uint8 slot; slot < SLOTS; ++slot) {
            for (uint256 index; index < assetCount[slot]; ++index) {
                if (!funded[slot][index]) revert InvalidBacking();
            }
        }
    }

function commit() external governance nonReentrant {
        if (phase != PHASE_EXPORTING || stateRoot == bytes32(0)) revert InvalidState();
        ZZZCanonicalHandoff peer = _peer(destinationController);
        if (
            peer.phase() != PHASE_IMPORTED_AWAITING_BACKING || peer.stateRoot() != stateRoot
                || peer.deploymentCommitment() != destinationDeployment
        ) revert InvalidState();
        _allFunded();
        // Both transitions are atomic on this chain. A failed readiness or
        // backing check rolls retirement back; no competing successor is added.
        phase = PHASE_RETIRED;
        access.canonicalTransition(STATE_RETIRED, false, false);
        ICanonicalHelpers(access.module(Ids.NFT)).canonicalRetire();
        peer.activate();
        emit Retired(handoffId, destinationController, stateRoot);
    }

function activate() external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || phase != PHASE_IMPORTED_AWAITING_BACKING || source.phase() != PHASE_RETIRED
                || source.destinationController() != address(access) || source.stateRoot() != stateRoot
        ) {
            revert Unauthorized();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            for (uint256 index; index < assetCount[slot]; ++index) {
                if (!incomingFunded[slot][index]) revert InvalidBacking();
            }
            _module(slot).canonicalValidate();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            _module(slot).canonicalActivate();
        }
        phase = PHASE_ACTIVE_REPLACEMENT;
        access.canonicalTransition(STATE_OPERATING, false, true);
        emit Activated(handoffId, incomingSource, stateRoot);
    }

function abort() external governance nonReentrant {
        if (phase != PHASE_EXPORTING && phase != PHASE_SETTLING) revert InvalidState();
        phase = PHASE_ABORTING;
        _peer(destinationController).cancelImport();
        emit AbortStarted(handoffId);
    }

function cancelImport() external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || source.phase() != PHASE_ABORTING
                || (phase != PHASE_IMPORTING && phase != PHASE_IMPORTED_AWAITING_BACKING)
        ) {
            revert Unauthorized();
        }
        phase = PHASE_CANCELLED_IMPORT;
        access.canonicalTransition(STATE_CANCELLED, false, false);
    }

function returnFunds(uint8 slot, uint256 index) external nonReentrant {
        if (
            phase != PHASE_ABORTING || slot >= SLOTS || index >= assetCount[slot] || !funded[slot][index]
                || returned[slot][index]
        ) revert InvalidState();
        ZZZCanonicalHandoff peer = _peer(destinationController);
        if (peer.phase() != PHASE_CANCELLED_IMPORT) revert InvalidState();
        (address asset, uint256 amount) = _module(slot).canonicalBacking(index);
        returned[slot][index] = true;
        uint256 beforeBalance = _balance(asset, moduleAt(slot));
        peer.returnFunding(slot, index);
        if (_balance(asset, moduleAt(slot)) != beforeBalance + amount) revert InvalidBacking();
        _module(slot).canonicalRestore(index, peer.moduleAt(slot));
        emit BackingReturned(handoffId, slot, index);
    }

function returnFunding(uint8 slot, uint256 index) external nonReentrant {
        ZZZCanonicalHandoff source = _peer(incomingSource);
        if (
            msg.sender != address(source) || phase != PHASE_CANCELLED_IMPORT || source.phase() != PHASE_ABORTING
                || !incomingFunded[slot][index] || !source.returned(slot, index)
        ) revert Unauthorized();
        incomingFunded[slot][index] = false;
        _module(slot).canonicalRelease(index, source.moduleAt(slot));
    }

function finishAbort() external governance nonReentrant {
        if (phase != PHASE_ABORTING || _peer(destinationController).phase() != PHASE_CANCELLED_IMPORT) {
            revert InvalidState();
        }
        for (uint8 slot; slot < SLOTS; ++slot) {
            for (uint256 index; index < assetCount[slot]; ++index) {
                if (funded[slot][index] && !returned[slot][index]) revert InvalidBacking();
            }
            _module(slot).canonicalValidate();
        }
        phase = incomingSource == address(0) ? PHASE_IDLE : PHASE_ACTIVE_REPLACEMENT;
        access.canonicalTransition(STATE_OPERATING, false, true);
        emit Aborted(handoffId);
    }

constructor(address controller, address nftController, address royaltyLedger) {
        if (controller.code.length == 0 || msg.sender != nftController || royaltyLedger.code.length == 0) {
            revert InvalidConfiguration();
        }
        access = IZZZAccess(controller);
        nft = nftController;
        royalties = royaltyLedger;
    }

function claimBatch(Claim[] calldata claims) external nonReentrant returns (uint256[] memory amounts) {
        uint256 length = claims.length;
        if (length == 0 || length > MAX_CLAIMS) revert InvalidBatch();
        if (!access.isSealed() || access.module(Ids.NFT) != nft) revert InvalidConfiguration();
        // Reject malformed/unauthorized batches before any payout callback.
        for (uint256 i; i < length; ++i) {
            Claim calldata entry = claims[i];
            if (IZZZNFT(nft).ownerOf(entry.nftId) != msg.sender) revert Unauthorized();
            for (uint256 j; j < i; ++j) {
                Claim calldata earlier = claims[j];
                if (entry.nftId == earlier.nftId && entry.asset == earlier.asset && entry.royalty == earlier.royalty) {
                    revert DuplicateClaim();
                }
            }
        }
        amounts = new uint256[](length);
        for (uint256 i; i < length; ++i) {
            Claim calldata entry = claims[i];
            // A preceding native/token callback may have transferred this NFT.
            // Each ledger independently repeats the same current-owner check.
            if (IZZZNFT(nft).ownerOf(entry.nftId) != msg.sender) revert Unauthorized();
            address target = entry.royalty ? royalties : access.module(Ids.REWARDS);
            if (target.code.length == 0) revert InvalidConfiguration();
            amounts[i] = IZZZClaimLedger(target).claimFor(entry.nftId, entry.asset, msg.sender);
        }
        emit BatchClaimed(msg.sender, length);
    }

function compound(uint256 id, uint128 minimumLiquidity, uint256 deadline) external onlyKeeper live operating {
        _deadline(deadline);
        if (minimumLiquidity == 0) revert InvalidAmount();
        IZZZVault(access.module(Ids.VAULT)).compound(id, minimumLiquidity, deadline);
        if (!access.keeperAuthorized(msg.sender) || access.paused()) revert Unauthorized();
    }

constructor(address controller,address priceOracle) {
        if (msg.sender != priceOracle || controller.code.length == 0) revert Unauthorized();
        access = IZZZAccess(controller); oracle = IZZZOracle(priceOracle);
    }

modifier onlyBudget() {
        if (msg.sender != IPricingVault(access.module(Ids.VAULT)).migrationBudget()) revert Unauthorized();
        _;
    }

function _live() private view {
        if (!access.isSealed() || access.paused() || access.preparationActive() || access.canonicalState() != 0) revert InvalidState();
    }

function compoundReady(uint256 bucket) external view onlyBudget returns(bool) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(bucket);
        if(p.status != PositionStatus.Active || p.lpTokenId == 0) return false;
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        if(!c.operationsEnabled) return false;
        IPricingBudget budget = IPricingBudget(msg.sender);
        uint256 previous = budget.lastCompound(bucket);
        if(p.lastRebalance > previous) previous = p.lastRebalance;
        if(block.timestamp < previous+budget.compoundInterval(p.poolId)) return false;
        IZZZStrategy strategy = IZZZStrategy(access.module(Ids.STRATEGY));
        return !strategy.needsRebalance(bucket) && strategy.keeperRangeTarget(p.poolId) == 0;
    }

function markMaintenance(uint256 bucket) external view onlyBudget returns(MaintenanceMark memory mark) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(bucket);
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        mark.price0 = oracle.price(c.key.currency0); mark.price1 = oracle.price(c.key.currency1);
        mark.scale0 = 10 ** oracle.tokenDecimals(c.key.currency0); mark.scale1 = 10 ** oracle.tokenDecimals(c.key.currency1);
        mark.idle0 = p.idle0; mark.idle1 = p.idle1;
        (uint256 deployed,uint256 idle) = _maintenanceValues(p,mark.price0,mark.price1,mark.scale0,mark.scale1);
        mark.value = deployed+idle;
    }

function maintenanceValues(uint256 bucket,uint256 price0,uint256 price1,uint256 scale0,uint256 scale1)
        external view onlyBudget returns(uint256 deployed,uint256 idle) {
        return _maintenanceValues(IZZZVault(access.module(Ids.VAULT)).group(bucket),price0,price1,scale0,scale1);
    }

function _maintenanceValues(Position memory p,uint256 price0,uint256 price1,uint256 scale0,uint256 scale1)
        private view returns(uint256 deployed,uint256 idle) {
        if(p.lpTokenId != 0) {
            (uint256 a0,uint256 a1) = IZZZLiquidity(access.module(Ids.LIQUIDITY)).amounts(p.lpTokenId);
            deployed = Math.mulDiv(a0,price0,scale0)+Math.mulDiv(a1,price1,scale1);
        }
        idle = Math.mulDiv(p.idle0,price0,scale0)+Math.mulDiv(p.idle1,price1,scale1);
    }

function _mark(address token) private {
        if (marks[token].lower != 0) return;
        if (assets.length == 34) revert InvalidState();
        (uint256 lower,uint256 upper,bytes32 fingerprint) = oracle.priceBounds(token);
        if (lower == 0 || upper < lower || upper > type(uint128).max) revert InvalidState();
        marks[token] = Mark(uint128(lower),uint128(upper),10 ** oracle.tokenDecimals(token),fingerprint);
        assets.push(token);
    }

function _pair(bytes32 pool) private {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(pool);
        basis.pool = pool; basis.token0 = c.key.currency0; basis.token1 = c.key.currency1;
        // Entry freezes operating limits before the original-source transfer
        // and conversion, not only when it eventually enters the Vault.
        uint16 cap = IPricingBudget(IPricingVault(access.module(Ids.VAULT)).migrationBudget()).contributionLossBps();
        if (cap > 1000 || c.maxSlippageBps > 1000) revert InvalidState();
        basis.limits = uint32(c.maxSlippageBps) | (uint32(cap) << 16);
        _mark(c.key.currency0); _mark(c.key.currency1);
    }

function _historicalMarks(uint256 bucket) private {
        if (bucket == 0) return;
        // Before the first custody composition, compound belongs only to the
        // already marked current pair. Unrelated global reward assets cannot
        // be this bucket's historical principal backing.
        IPricingBudget budget = IPricingBudget(IPricingVault(access.module(Ids.VAULT)).migrationBudget());
        if (budget.compositionEpoch(bucket) == 0) return;
        IPricingAssets admitted = IPricingAssets(access.module(Ids.REWARDS));
        uint256 count = admitted.assetCount();
        if (count > 33) revert InvalidState();
        for (uint256 i; i < count; ++i) {
            address token = admitted.assets(i);
            if (token == basis.token0 || token == basis.token1) continue;
            if (IZZZFees(access.module(Ids.FEES)).compoundBalance(bucket,token) != 0) _mark(token);
        }
    }

function beginEntryReviewed(uint256 nft,bytes32 pool,address source,uint256 amount,uint16 maximumLossBps)
        external returns(uint256 lowerUSD) {
        if (msg.sender != _entry()) revert Unauthorized();
        _live(); if (basis.phase != 0 || amount == 0) revert InvalidState();
        if (maximumLossBps > 1000) revert InvalidAmount();
        basis.phase = 1; basis.entry = true; basis.nft = nft;
        _pair(pool);
        if (uint16(basis.limits >> 16) > maximumLossBps) revert Slippage();
        _mark(source);
        Mark memory m = marks[source];
        lowerUSD = Math.mulDiv(amount,m.lower,m.scale);
        basis.lowerInput = lowerUSD;
        basis.upperInput = Math.mulDiv(amount,m.upper,m.scale,Math.Rounding.Ceil);
        _historicalMarks(IZZZVault(access.module(Ids.VAULT)).poolBucket(pool));
    }

function begin(uint256 nft,uint256 bucket,uint256 packed,uint256 inputUSD,uint32 limits) external onlyBudget {
        _live();
        bytes32 pool = IZZZVault(access.module(Ids.VAULT)).group(bucket).poolId;
        if (basis.phase != 0) {
            if (!basis.entry || basis.phase != 1 || basis.pool != pool || basis.nft != nft ||
                basis.lowerInput != inputUSD || !IPricingEntry(_entry()).pricingContext(nft,pool,packed,inputUSD)) revert InvalidState();
        } else {
            basis.phase = 1; basis.nft = nft; _pair(pool);
            uint256 a0 = uint128(packed); uint256 a1 = packed >> 128;
            basis.lowerInput = _pairValue(a0,a1);
            basis.upperInput = _upper(basis.token0,a0) + _upper(basis.token1,a1);
            if (inputUSD != basis.lowerInput) revert InvalidAmount();
            _historicalMarks(bucket);
        }
        // A callback cannot adopt a later, wider governance/venue policy.
        // Even a tightening during this operation requires a fresh review.
        if (basis.limits != limits) revert InvalidState();
        basis.bucket = bucket;
        // Conversion/pull callbacks may not replace policies or round data.
        _unchanged();
    }

function _lower(address token,uint256 amount) private view returns(uint256) {
        if (amount == 0) return 0;
        if (basis.phase == 0) return oracle.value(token,amount);
        Mark memory m = marks[token];
        if (m.lower == 0) revert InvalidState();
        return Math.mulDiv(amount,m.lower,m.scale);
    }

function _upper(address token,uint256 amount) private view returns(uint256) {
        if (amount == 0) return 0;
        Mark memory m = marks[token];
        if (m.upper == 0) revert InvalidState();
        return Math.mulDiv(amount,m.upper,m.scale,Math.Rounding.Ceil);
    }

function _pairValue(uint256 amount0,uint256 amount1) private view returns(uint256) {
        return _lower(basis.token0,amount0) + _lower(basis.token1,amount1);
    }

function valueBucket(uint256 bucket,uint256 amount0,uint256 amount1) public view returns(uint256) {
        if (basis.phase != 0 && basis.bucket == bucket) return _pairValue(amount0,amount1);
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(IZZZVault(access.module(Ids.VAULT)).group(bucket).poolId);
        return oracle.value(c.key.currency0,amount0) + oracle.value(c.key.currency1,amount1);
    }

function nav(uint256 bucket) public view returns(uint256 deployed,uint256 idle) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(bucket);
        if (p.lpTokenId != 0) {
            (uint256 a0,uint256 a1) = IZZZLiquidity(access.module(Ids.LIQUIDITY)).amounts(p.lpTokenId);
            deployed = valueBucket(bucket,a0,a1);
        }
        idle = valueBucket(bucket,p.idle0,p.idle1);
    }

function contributionNav(uint256 bucket) external onlyBudget returns(uint256 deployed,uint256 idle) {
        if (basis.phase == 0 || basis.phase > 3 || basis.bucket != bucket) revert InvalidState();
        if (basis.phase == 2) basis.putSpot = IZZZStrategy(access.module(Ids.STRATEGY)).validatePrice(basis.pool);
        if (basis.phase == 3) _putUnchanged();
        ++basis.phase;
        return nav(bucket);
    }

function historicalValue(uint256 bucket) public view returns(uint256 value) {
        IPricingBudget budget = IPricingBudget(IPricingVault(access.module(Ids.VAULT)).migrationBudget());
        if (budget.compositionEpoch(bucket) == 0) return 0;
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(IZZZVault(access.module(Ids.VAULT)).group(bucket).poolId);
        IPricingAssets admitted = IPricingAssets(access.module(Ids.REWARDS));
        uint256 count = admitted.assetCount(); if (count > 33) revert InvalidState();
        for (uint256 i; i < count; ++i) {
            address token = admitted.assets(i);
            if (token == c.key.currency0 || token == c.key.currency1) continue;
            uint256 amount = IZZZFees(access.module(Ids.FEES)).compoundBalance(bucket,token);
            if (amount != 0) value += basis.phase != 0 && basis.bucket == bucket ? _lower(token,amount) : oracle.value(token,amount);
        }
    }

function _putUnchanged() private view {
        if (IZZZStrategy(access.module(Ids.STRATEGY)).validatePrice(basis.pool) != basis.putSpot) revert Slippage();
    }

function _unchanged() private view returns(bytes32 hash) {
        hash = keccak256(abi.encode(basis.pool,basis.nft,basis.lowerInput,basis.upperInput));
        for (uint256 i; i < assets.length; ++i) {
            address token = assets[i]; Mark memory m = marks[token];
            (uint256 low,uint256 high,bytes32 fingerprint) = oracle.priceBounds(token);
            if (low != m.lower || high != m.upper || fingerprint != m.fingerprint ||
                10 ** oracle.tokenDecimals(token) != m.scale) revert InvalidState();
            hash = keccak256(abi.encode(hash,token,m));
        }
    }

function finish(uint256 bucket,uint256 inputUSD,uint256 supply,uint256 incumbentNAV,
        uint256 incumbentDeployed,uint256 deployed,uint256 idle,uint32 limits)
        external onlyBudget returns(uint256 issued,uint256 netUSD) {
        if (basis.phase != 4 || basis.bucket != bucket || basis.lowerInput != inputUSD || basis.limits != limits ||
            uint16(limits) > 1000 || uint16(limits >> 16) > 1000) revert InvalidState();
        // Previously zero old-currency compound can first arrive during fee
        // synchronization. Mark it only for incumbent historical backing now;
        // never overwrite a starting mark or count it as newly deployed LP.
        _historicalMarks(bucket);
        _putUnchanged(); bytes32 hash = _unchanged();
        if (deployed == 0 || idle > Math.mulDiv(deployed+idle,500,10000) ||
            deployed+idle <= incumbentNAV || deployed < incumbentDeployed) revert Slippage();
        netUSD = deployed+idle-incumbentNAV;
        uint256 required = basis.upperInput - Math.mulDiv(basis.upperInput,uint16(limits >> 16),10000);
        // Vault caps both balancing and deployment to the entrant's budget;
        // this baseline is the repriced incumbent physical LP only. Existing
        // idle/compound belongs in NAV, never in the marginal deployment test.
        if (netUSD < Math.mulDiv(basis.upperInput,10000-uint16(limits),10000) ||
            netUSD < required || deployed-incumbentDeployed < required) revert Slippage();
        issued = supply == 0 ? netUSD : Math.mulDiv(supply,netUSD,incumbentNAV+historicalValue(bucket));
        if (issued == 0 || supply+issued > 1e36) revert InvalidAmount();
        emit ContributionVerified(basis.nft,bucket,basis.lowerInput,basis.upperInput,
            deployed-incumbentDeployed,netUSD,basis.putSpot,hash);
        if (basis.entry) basis.phase = 5;
        else _clear();
    }

function endEntry() external {
        if (msg.sender != _entry()) revert Unauthorized();
        if (!basis.entry || basis.phase != 5) revert InvalidState();
        _putUnchanged(); _unchanged(); _clear();
    }

function _clear() private {
        for (uint256 i; i < assets.length; ++i) delete marks[assets[i]];
        delete assets; delete basis;
    }

function validateParking(bytes calldata encoded) external view {
        if(msg.sender!=migration) revert Unauthorized();
        Parking memory r=abi.decode(encoded,(Parking));
        IZZZVault v=IZZZVault(access.module(Ids.VAULT));Position memory p=v.group(r.bucketId);
        PoolConfig memory c=IZZZPools(access.module(Ids.POOLS)).accounting(r.poolId);
        ILocalParkingState state=ILocalParkingState(migration);
        if(!access.isSealed() || !access.paused() || access.lpExitStarted() || r.reviewHash==bytes32(0) ||
            (r.minimum0==0 && r.minimum1==0) || r.lpTokenId==0 || r.nonce!=state.parkingNonce(r.bucketId) ||
            r.custodyEpoch!=state.custodyEpoch(r.bucketId) || p.status!=PositionStatus.Active || p.poolId!=r.poolId ||
            p.lpTokenId!=r.lpTokenId || p.depositUSD!=r.depositUSD ||
            r.totalShares==0 || v.bucketTotalShares(r.bucketId)!=r.totalShares ||
            c.key.currency0!=r.token0 || c.key.currency1!=r.token1) revert InvalidState();
    }

function _balance(address token) private view returns (uint256) {
        return token == address(0) ? address(this).balance : IERC20(token).balanceOf(address(this));
    }

function _pull(address token, uint256 amount) private {
        if (msg.value != (token == address(0) ? amount : 0)) revert InvalidAmount();
        if (token != address(0)) ExactToken.pull(token, msg.sender, amount);
    }

function _push(address token, address destination, uint256 amount) private {
        if (token != address(0)) { ExactToken.push(token, destination, amount); return; }
        if (amount == 0) return;
        uint256 beforeBalance = address(this).balance;
        (bool ok,) = payable(destination).call{value: amount}("");
        if (!ok || address(this).balance != beforeBalance - amount) revert InvalidState();
    }

function _approve(address token, address spender, uint256 amount) private {
        if (token != address(0)) IERC20(token).forceApprove(spender, amount);
    }

function _credit(uint256 id, address token, uint256 personal, uint256 shared) private {
        address rewards = access.module(Ids.REWARDS);
        _approve(token, rewards, personal + shared);
        if (canonicalState() == 1) {
            if (!access.canonicalSettling()) revert InvalidState();
            ICanonicalFeeCutoff(rewards).creditCanonicalCutoff{value: token == address(0) ? personal + shared : 0}(id, token, personal, shared);
        } else IZZZRewards(rewards).creditPool{value: token == address(0) ? personal + shared : 0}(id, token, personal, shared);
        _approve(token, rewards, 0);
    }

function _solvent(address token) private view {
        if (_balance(token) < accounted[token]) revert InvalidState();
    }

function allocate(uint256 id, address token, uint256 amount) external payable onlyModule(Ids.VAULT) nonReentrant canonicalAccounting {
        if (amount == 0) revert InvalidAmount();
        Position memory p = IZZZVault(msg.sender).group(id);
        if (p.status != PositionStatus.Active) revert InvalidState();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        if (token != c.key.currency0 && token != c.key.currency1) revert InvalidConfiguration();
        _pull(token, amount);
        accounted[token] += amount;
        uint256 total = dust[id][token] + amount;
        // Twenty raw units allocate exactly 80/10/5/5. Smaller receipts carry
        // until another receipt or the incumbent-owner dust settlement barrier.
        uint256 units = total / 20;
        dust[id][token] = total % 20;
        if (units != 0) {
            compoundBalance[id][token] += units;
            buybackBalance[token] += units;
            accounted[token] -= units * 18;
            _credit(id, token, units * 16, units * 2);
        }
        _solvent(token);
        emit FeesAllocated(id, token, units * 20, dust[id][token]);
    }

function flushDust(uint256 id, address token) external nonReentrant canonicalAccounting {
        IZZZVault vault = _vault();
        if (!access.isSealed() || (msg.sender != address(vault) && msg.sender != access.module(Ids.MEMBERSHIP))) revert Unauthorized();
        Position memory p = vault.group(id);
        if (p.status != PositionStatus.Outbound && p.status != PositionStatus.Active && p.status != PositionStatus.Parked) revert InvalidState();
        _flushHomeDust(id, token);
    }

function _flushHomeDust(uint256 id, address token) private {
        uint256 remainder = dust[id][token];
        if (remainder == 0) return;
        dust[id][token] = 0;
        accounted[token] -= remainder;
        _credit(id, token, remainder, 0);
        _solvent(token);
        emit MembershipDustSettled(id, token, remainder);
    }

function releaseCompound(uint256 id, address token)
        external nonReentrant canonicalAccounting returns (uint256 amount) {
        if (!access.moduleAuthorized(Ids.VAULT, msg.sender)) revert Unauthorized();
        amount = compoundBalance[id][token];
        compoundBalance[id][token] = 0;
        accounted[token] -= amount;
        _push(token, msg.sender, amount);
        _solvent(token);
    }

function releaseBuyback(address token, uint256 amount) external onlyModule(Ids.BUYBACK) nonReentrant canonicalAccounting {
        if (amount == 0 || amount > buybackBalance[token]) revert InvalidAmount();
        buybackBalance[token] -= amount;
        accounted[token] -= amount;
        _push(token, msg.sender, amount);
        _solvent(token);
    }

function canonicalBarrier() external onlyCanonical nonReentrant {
        if (canonicalState() != 1) revert InvalidState();
    }

function canonicalBucketRecord(uint256 id, address asset) external view returns (bytes memory) {
        return abi.encode(CanonicalBucket(id, asset, dust[id][asset], compoundBalance[id][asset]));
    }

function canonicalWrite(uint8 kind, bytes calldata record) external onlyCanonical {
        if (canonicalState() != 2) revert InvalidState();
        if (kind == 0) {
            if (record.length != 160) revert InvalidState();
            (address asset, uint256 total, uint256 buyback,,) = abi.decode(record, (address,uint256,uint256,uint256,uint256));
            if (accounted[asset] != 0 || buybackBalance[asset] != 0 || buyback > total) revert InvalidState();
            accounted[asset] = total; buybackBalance[asset] = buyback;
        } else if (kind == 1) {
            if (record.length != 128) revert InvalidState();
            CanonicalBucket memory r = abi.decode(record, (CanonicalBucket));
            dust[r.id][r.asset] = r.dustAmount; compoundBalance[r.id][r.asset] = r.compoundAmount;
        } else revert InvalidState();
    }

function canonicalSend(address asset, address destination, uint256 amount) external onlyCanonical nonReentrant {
        _push(asset, destination, amount);
    }

constructor(address controller, address feeController) ZZZModule(controller) {
        fees = ZZZFeeController(payable(feeController));
        if (feeController.code.length == 0 || address(fees.access()) != controller || fees.FEE_INTAKE_VERSION() != 1) revert InvalidConfiguration();
    }

function _balance(address asset, address holder) private view returns (uint256) {
        return asset == address(0) ? holder.balance : IERC20(asset).balanceOf(holder);
    }

function _push(address asset, address destination, uint256 amount) private {
        if (asset != address(0)) { ExactToken.push(asset, destination, amount); return; }
        if (amount == 0) return;
        uint256 beforeBalance = address(this).balance;
        (bool ok,) = payable(destination).call{value: amount}("");
        if (!ok || address(this).balance != beforeBalance - amount) revert InvalidState();
    }

function canonicalCapture() external onlyHandoff {
        // Reject snapshotting from an ordinary allocation/reserve-send callback.
        fees.canonicalBarrier();
        imported = false;
        for (uint256 i; i < assets.length; ++i) delete accepted[i];
        delete assets; delete amounts; delete quarantine;
        groups = _vault().bucketCount();
        ICanonicalFeeAssets rewards = ICanonicalFeeAssets(access.module(Ids.REWARDS));
        lpAssets = rewards.assetCount();
        if (lpAssets == 0 || lpAssets > 33 || groups > 4) revert InvalidState();
        for (uint256 i; i < lpAssets; ++i) {
            address asset = rewards.assets(i);
            uint256 raw = _balance(asset, address(fees));
            assets.push(asset); amounts.push(0);
            // Donations remain quarantined, never converted into new income.
            // Restores are authenticated by the handoff's exact incoming delta;
            // arbitrary companion prefunds do not inflate the source snapshot.
            quarantine.push(raw - fees.accounted(asset));
            released[i] = false;
        }
        captured = true;
    }

function canonicalSettle() external onlyHandoff {
        if (!captured) revert InvalidState();
        for (uint256 i; i < groups; ++i) {
            uint256 id = _vault().bucketAt(i);
            for (uint256 j; j < lpAssets; ++j) fees.canonicalFlush(id, assets[j]);
        }
        for (uint256 i; i < lpAssets; ++i) {
            amounts[i] = fees.accounted(assets[i]) + quarantine[i];
            if (_balance(assets[i], address(fees)) < amounts[i]) revert InvalidState();
        }
    }

function canonicalExport(uint256 row) external view returns (bytes memory) {
        if (!captured || row >= canonicalCount()) revert InvalidState();
        if (row == 0) return abi.encode(lpAssets, groups);
        --row;
        if (row < lpAssets) {
            address asset = assets[row];
            return abi.encode(asset, fees.accounted(asset), fees.buybackBalance(asset), amounts[row], quarantine[row]);
        }
        row -= lpAssets;
        return fees.canonicalBucketRecord(_vault().bucketAt(row / lpAssets), assets[row % lpAssets]);
    }

function canonicalImport(uint256 row, bytes calldata record) external onlyHandoff {
        if (row != cursor++ || access.canonicalState() != 2) revert InvalidState();
        if (row == 0) {
            if (record.length != 64) revert InvalidState();
            (lpAssets, groups) = abi.decode(record, (uint256,uint256));
            if (lpAssets == 0 || lpAssets > 33 || groups > 4) revert InvalidState();
            imported = true; return;
        }
        --row;
        if (row < lpAssets) {
            if (record.length != 160) revert InvalidState();
            (address asset, uint256 total,, uint256 backing, uint256 q) =
                abi.decode(record, (address,uint256,uint256,uint256,uint256));
            if ((row == 0 ? asset != address(0) : asset == address(0) || asset.code.length == 0) || backing != total + q) revert InvalidState();
            for (uint256 i; i < row; ++i) if (assets[i] == asset) revert InvalidState();
            assets.push(asset); amounts.push(backing); quarantine.push(q);
            prefunds[asset] = _balance(asset, address(this));
            fees.canonicalWrite(0, record); return;
        }
        row -= lpAssets;
        if (row >= groups * lpAssets || record.length != 128) revert InvalidState();
        ZZZFeeController.CanonicalBucket memory r = abi.decode(record, (ZZZFeeController.CanonicalBucket));
        if (r.id != _vault().bucketAt(row / lpAssets) || r.asset != assets[row % lpAssets]) revert InvalidState();
        fees.canonicalWrite(1, record);
    }

function canonicalRelease(uint256 index, address destination) external onlyHandoff {
        uint8 state = access.canonicalState();
        if ((state != 1 && state != 4) || index >= assets.length || released[index] ||
            (state == 4 && !accepted[index])) revert InvalidState();
        released[index] = true;
        fees.canonicalSend(assets[index], destination, amounts[index]);
    }

function _accept(uint256 index, bool restore) private {
        if (msg.value != 0 || index >= assets.length || (!restore && accepted[index]) ||
            _balance(assets[index], address(this)) < (restore ? 0 : prefunds[assets[index]]) + amounts[index]) revert InvalidAmount();
        if (!restore) accepted[index] = true;
        _push(assets[index], address(fees), amounts[index]);
    }

function canonicalAccept(uint256 index, address) external payable onlyHandoff {
        if (access.canonicalState() != 2) revert InvalidState();
        _accept(index, false);
    }

function canonicalRestore(uint256 index, address) external payable onlyHandoff {
        if (access.canonicalState() != 1 || !released[index]) revert InvalidState();
        _accept(index, true); released[index] = false;
    }

function canonicalValidate() external view {
        if ((!captured && !imported) || (imported && cursor != canonicalCount())) revert InvalidState();
        for (uint256 i; i < assets.length; ++i) if (_balance(assets[i], address(fees)) < amounts[i]) revert InvalidState();
    }

function canonicalActivate() external onlyHandoff {
        if (access.canonicalState() != 2 || !imported || cursor != canonicalCount()) revert InvalidState();
    }

constructor(address controller, address core, address state) ZZZModule(controller) {
        // Created by the manager while its runtime does not yet exist.
        liquidityManager = msg.sender;
        poolManager = IPoolManagerMinimal(core);
        stateView = IStateViewMinimal(state);
    }

function deploymentAmounts(uint160 current,int24 lower,int24 upper,uint256 amount0,uint256 amount1)
        external pure returns(uint128 liquidity,uint256 nativeDebt) {
        uint160 a = TickMath.getSqrtPriceAtTick(lower); uint160 b = TickMath.getSqrtPriceAtTick(upper);
        liquidity = LiquidityAmounts.getLiquidityForAmounts(current,a,b,amount0,amount1);
        if(current < b) nativeDebt = SqrtPriceMath.getAmount0Delta(current <= a ? a : current,b,liquidity,true);
    }

function principalAmounts(uint256 id) external view returns(uint256 amount0,uint256 amount1) {
        IPositionManagerMinimal posm = IPositionManagerMinimal(IZZZLiquidity(liquidityManager).positionManager());
        (PoolKey memory key,uint256 info) = posm.getPoolAndPositionInfo(id);
        uint160 a = TickMath.getSqrtPriceAtTick(int24(uint24(info >> 8)));
        uint160 b = TickMath.getSqrtPriceAtTick(int24(uint24(info >> 32)));
        (uint160 current,,,) = stateView.getSlot0(keccak256(abi.encode(key)));
        uint128 liquidity = posm.getPositionLiquidity(id);
        if(current <= a) amount0 = SqrtPriceMath.getAmount0Delta(a,b,liquidity,false);
        else if(current >= b) amount1 = SqrtPriceMath.getAmount1Delta(a,b,liquidity,false);
        else {
            amount0 = SqrtPriceMath.getAmount0Delta(current,b,liquidity,false);
            amount1 = SqrtPriceMath.getAmount1Delta(a,current,liquidity,false);
        }
    }

function additionalLossBps() public view returns(uint16) {
        return IZZZStrategy(access.module(Ids.STRATEGY)).additionalLossBps();
    }

function policyFingerprint(bytes32 target, bytes32 venue) public view returns (bytes32) {
        address registry = access.module(Ids.POOLS);
        PoolConfig memory t = IZZZPools(registry).accounting(target);
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        (,,bytes32 first) = oracle.priceBounds(address(0));
        (,,bytes32 second) = oracle.priceBounds(t.key.currency1);
        bytes32 route = venue == bytes32(0) ? bytes32(0) : keccak256(abi.encode(IZZZPools(registry).accounting(venue)));
        (int24 lower,int24 upper,uint160 referencePrice) = IZZZStrategy(access.module(Ids.STRATEGY)).target(target);
        return keccak256(abi.encode(registry,ILPRegistryRevision(registry).configurationRevision(),t,route,
            address(oracle),access.module(Ids.STRATEGY),
            IZZZStrategy(access.module(Ids.STRATEGY)).executionQualityRevision(),lower,upper,referencePrice,first,second));
    }

function configureExecutionPools(bytes32[] calldata pools, bytes32 reviewHash)
        external onlyGovernance operating principalOperating {
        if (pools.length > MAX_EXECUTION_POOLS || reviewHash == bytes32(0)) revert InvalidConfiguration();
        for (uint256 i; i < pools.length; ++i) {
            PoolConfig memory c = _pool(pools[i]);
            IZZZStrategy(access.module(Ids.STRATEGY)).validatePrice(pools[i]);
            (,,,uint24 fee) = stateView.getSlot0(pools[i]);
            if (fee != c.key.fee) revert InvalidConfiguration();
            for (uint256 j; j < i; ++j) if (pools[j] == pools[i]) revert InvalidConfiguration();
        }
        venues = pools;
        ++executionRevision;
        emit ExecutionPoolsConfigured(executionRevision, pools, reviewHash);
    }

function configureSolver(uint8 iterations, uint32 gasLimit, bytes32 reviewHash)
        external onlyGovernance operating principalOperating {
        if (iterations < 4 || iterations > 12 || gasLimit < 100000 || gasLimit > 300000 || reviewHash == bytes32(0))
            revert InvalidConfiguration();
        searchIterations = iterations; quoteGasLimit = gasLimit; ++executionRevision;
        emit SolverConfigured(executionRevision, iterations, gasLimit, reviewHash);
    }

function _fee(PoolConfig memory c, bool direction, uint24 protocol, uint24 fee) private pure returns (uint256) {
        if (fee != c.key.fee || (protocol & 0xfff) > 1000 || protocol >> 12 > 1000) revert InvalidState();
        uint256 selected = direction ? protocol & 0xfff : protocol >> 12;
        return selected + fee - Math.mulDiv(selected,fee,1_000_000);
    }

function _pool(bytes32 id) private view returns (PoolConfig memory c) {
        c = IZZZPools(access.module(Ids.POOLS)).accounting(id);
        if (!c.operationsEnabled || c.key.currency0 != address(0) || c.key.currency1 == address(0) ||
            c.key.hooks != address(0) || c.key.fee > 100000 || c.maxSlippageBps > 1000 ||
            keccak256(abi.encode(c.key)) != id) revert InvalidConfiguration();
    }

function _prices(address token) private view returns (Prices memory p) {
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        (p.lower0,p.upper0,) = oracle.priceBounds(address(0));
        (p.lower1,p.upper1,) = oracle.priceBounds(token);
        uint8 d1 = oracle.tokenDecimals(token);
        p.scale1 = 10 ** d1;
        p.referenceX96 = ZZZPriceMath.referenceX96(p.lower0,p.lower1,18,d1,address(0));
        p.extraLoss = additionalLossBps();
    }

function _validSpot(uint160 price, uint160 referencePrice, uint16 deviation) private pure returns (bool) {
        if (price < TickMath.MIN_SQRT_PRICE || price >= TickMath.MAX_SQRT_PRICE) return false;
        uint256 root = Math.mulDiv(price,1e18,referencePrice);
        uint256 ratio = Math.mulDiv(root,root,1e18);
        return (ratio > 1e18 ? ratio-1e18 : 1e18-ratio) <= uint256(deviation)*1e14;
    }

function _values(Prices memory p, uint256 amount0, uint256 amount1) private pure returns (uint256 v0, uint256 v1) {
        return (Math.mulDiv(amount0,p.lower0,1e18),Math.mulDiv(amount1,p.lower1,p.scale1));
    }

function _evaluate(Context memory x, uint160 price, uint256 a0, uint256 a1) private pure returns (Evaluation memory e) {
        (uint256 v0,uint256 v1) = _values(x.prices,a0,a1);
        e.retained = v0+v1;
        uint256 u0; uint256 u1;
        if (price <= x.lower) u0 = SqrtPriceMath.getAmount0Delta(x.lower,x.upper,1e18,false);
        else if (price >= x.upper) u1 = SqrtPriceMath.getAmount1Delta(x.lower,x.upper,1e18,false);
        else {
            u0 = SqrtPriceMath.getAmount0Delta(price,x.upper,1e18,false);
            u1 = SqrtPriceMath.getAmount1Delta(x.lower,price,1e18,false);
        }
        (u0,u1) = _values(x.prices,u0,u1);
        if (u0+u1 == 0) revert InvalidAmount();
        uint256 desired0 = Math.mulDiv(e.retained,u0,u0+u1);
        e.excess0 = v0 > desired0;
        e.imbalance = e.excess0 ? v0-desired0 : desired0-v0;
        uint128 liquidity = LiquidityAmounts.getLiquidityForAmounts(price,x.lower,x.upper,a0,a1);
        uint256 used0; uint256 used1;
        if (price <= x.lower) used0 = SqrtPriceMath.getAmount0Delta(x.lower,x.upper,liquidity,false);
        else if (price >= x.upper) used1 = SqrtPriceMath.getAmount1Delta(x.lower,x.upper,liquidity,false);
        else {
            used0 = SqrtPriceMath.getAmount0Delta(price,x.upper,liquidity,false);
            used1 = SqrtPriceMath.getAmount1Delta(x.lower,price,liquidity,false);
        }
        (used0,used1) = _values(x.prices,used0,used1);
        e.deployed = used0+used1;
    }

function _quoted(Prices memory p, bool direction, uint256 amount) private pure returns (uint256) {
        uint256 value = Math.mulDiv(amount,direction ? p.upper0 : p.upper1,direction ? 1e18 : p.scale1);
        return Math.mulDiv(value,direction ? p.scale1 : 1e18,direction ? p.lower1 : p.lower0);
    }

function _minimum(Prices memory p, bool direction, uint256 amount, uint16 loss, uint256 fee) private pure returns (uint256) {
        uint256 gross = Math.mulDiv(_quoted(p,direction,amount),10000-loss,10000);
        uint256 netInput = Math.mulDiv(amount,1_000_000-fee,1_000_000);
        return Math.max(gross,Math.mulDiv(_quoted(p,direction,netInput),10000-p.extraLoss,10000,Math.Rounding.Ceil));
    }

function _seed(Context memory x, bool direction, uint256 fee) private pure returns (uint256 input,uint256 residual) {
        uint256 unit0; uint256 unit1;
        if (x.spot <= x.lower) unit0 = SqrtPriceMath.getAmount0Delta(x.lower,x.upper,1e18,false);
        else if (x.spot >= x.upper) unit1 = SqrtPriceMath.getAmount1Delta(x.lower,x.upper,1e18,false);
        else {
            unit0 = SqrtPriceMath.getAmount0Delta(x.spot,x.upper,1e18,false);
            unit1 = SqrtPriceMath.getAmount1Delta(x.lower,x.spot,1e18,false);
        }
        (unit0,unit1) = _values(x.prices,unit0,unit1);
        (uint256 v0,uint256 v1) = _values(x.prices,x.amount0,x.amount1);
        uint256 desired = Math.mulDiv(v0+v1,unit0,unit0+unit1);
        uint256 excess = direction ? v0-desired : desired-v0;
        residual = excess;
        uint256 weight = Math.mulDiv(direction ? unit0 : unit1,1e18,unit0+unit1);
        excess = Math.mulDiv(excess,1e18,1e18-Math.mulDiv(weight,fee,1_000_000));
        input = Math.mulDiv(excess,direction ? 1e18 : x.prices.scale1,direction ? x.prices.lower0 : x.prices.lower1);
    }

function plan(bytes32 target, int24 lower, int24 upper, uint256 amount0, uint256 amount1)
        external returns (Plan memory best) {
        if (msg.sender != liquidityManager || access.module(Ids.LIQUIDITY) != msg.sender || !access.isSealed()) revert Unauthorized();
        if (amount0 > type(uint128).max || amount1 > type(uint128).max || lower >= upper) revert InvalidAmount();
        PoolConfig memory destination = _pool(target);
        Context memory x = Context(target,IZZZStrategy(access.module(Ids.STRATEGY)).validatePrice(target),
            TickMath.getSqrtPriceAtTick(lower),TickMath.getSqrtPriceAtTick(upper),amount0,amount1,_prices(destination.key.currency1));
        Evaluation memory baseline = _evaluate(x,x.spot,amount0,amount1);
        best.revision = executionRevision;
        best.targetSqrtAfter = x.spot;
        bytes32 original = policyFingerprint(target,bytes32(0));
        best.fingerprint = original;
        uint256 bestValue = baseline.deployed;
        // A balanced budget needs no swap just to chase rounding dust.
        if (baseline.retained == 0 || baseline.deployed >= Math.mulDiv(baseline.retained,9990,10000)) {
            emit BalancePlanned(target,bytes32(0),false,0,0,best.revision);
            return best;
        }
        for (uint256 i; i < venues.length; ++i) {
            // An independently disabled venue must not freeze healthy candidates.
            try this.routePlan(x,venues[i],baseline.excess0) returns (Plan memory candidate,uint256 deployed) {
                if (deployed > bestValue) { best = candidate; bestValue = deployed; }
            } catch {}
        }
        if (executionRevision != best.revision || policyFingerprint(target,bytes32(0)) != original) revert InvalidState();
        emit BalancePlanned(target,best.poolId,best.zeroForOne,best.amountIn,best.amountOut,best.revision);
    }

function routePlan(Context calldata x, bytes32 id, bool direction) external returns (Plan memory best,uint256 bestValue) {
        if (msg.sender != address(this)) revert Unauthorized();
        PoolConfig memory c = _pool(id);
        PoolConfig memory target = _pool(x.target);
        if (c.key.currency1 != target.key.currency1) revert InvalidConfiguration();
        (uint160 beforePrice,,uint24 protocol,uint24 fee) = stateView.getSlot0(id);
        uint256 swapFee = _fee(c,direction,protocol,fee);
        if (!_validSpot(beforePrice,x.prices.referenceX96,c.maxSpotDeviationBps)) revert InvalidState();
        uint256 lo; uint256 hi = direction ? x.amount0 : x.amount1;
        if (hi > uint256(uint128(type(int128).max))) hi = uint256(uint128(type(int128).max));
        (uint256 input,uint256 initialResidual) = _seed(x,direction,swapFee);
        if (input == 0) return (best,0);
        if (input > hi) input = hi;
        best.revision = executionRevision;
        for (uint256 pass; pass < searchIterations && lo < hi; ++pass) {
            uint256 interpolated;
            bool quoted; uint256 output; uint160 afterPrice;
            try this.quoteCandidate{gas:quoteGasLimit}(c.key,direction,input) returns (uint256 out,uint160 price) {
                quoted = true; output = out; afterPrice = price;
            } catch {}
            if (!quoted) hi = input;
            else {
                uint256 minimum = _minimum(x.prices,direction,input,
                    c.maxSlippageBps < target.maxSlippageBps ? c.maxSlippageBps : target.maxSlippageBps,swapFee);
                if (minimum == 0) lo = input+1;
                // Feasibility comes before the target-ratio bracket. Increasing
                // an already excessive trade cannot repair impact/spot limits.
                else if (output < minimum || !_validSpot(afterPrice,x.prices.referenceX96,c.maxSpotDeviationBps)) hi = input;
                else {
                    uint256 a0 = direction ? x.amount0-input : x.amount0+output;
                    uint256 a1 = direction ? x.amount1+output : x.amount1-input;
                    Evaluation memory e = _evaluate(x,id == x.target ? afterPrice : x.spot,a0,a1);
                    if (e.deployed > bestValue) {
                        bestValue = e.deployed;
                        best = Plan(id,direction,input,output,minimum,afterPrice,id == x.target ? afterPrice : x.spot,
                            executionRevision,policyFingerprint(x.target,id));
                        if (e.deployed >= Math.mulDiv(e.retained,9990,10000)) break;
                    }
                    if (e.excess0 == direction) lo = input+1;
                    else hi = input;
                    // Safeguarded secant from the original zero-input residual:
                    // smooth v4 curves converge faster than midpoint-only
                    // search, without another real swap or an unbounded loop.
                    if (initialResidual != 0) {
                        if (e.excess0 == direction && e.imbalance < initialResidual) {
                            uint256 denominator = initialResidual-e.imbalance;
                            // Prove the quotient is bounded before mulDiv;
                            // a nearly flat residual must not overflow or jump
                            // outside the already established feasible bracket.
                            if (input < Math.mulDiv(hi,denominator,initialResidual))
                                interpolated = Math.mulDiv(input,initialResidual,denominator);
                        } else if (e.excess0 != direction && e.imbalance <= type(uint256).max-initialResidual) {
                            interpolated = Math.mulDiv(input,initialResidual,initialResidual+e.imbalance);
                        }
                    }
                }
            }
            if (lo >= hi) break;
            input = interpolated != 0 && interpolated >= lo && interpolated < hi ? interpolated : lo+(hi-lo)/2;
        }
    }

function quoteCandidate(PoolKey calldata key, bool direction, uint256 amount) external returns (uint256 output,uint160 afterPrice) {
        if (msg.sender != address(this) || amount == 0 || amount > uint256(uint128(type(int128).max))) revert Unauthorized();
        bytes memory payload = abi.encode(key,direction,amount);
        pendingQuoteHash = keccak256(payload);
        try poolManager.unlock(payload) returns (bytes memory) { revert InvalidState(); }
        catch (bytes memory reason) {
            pendingQuoteHash = bytes32(0);
            bytes4 selector;
            if (reason.length == 68) assembly ("memory-safe") { selector := mload(add(reason,32)) }
            if (selector != QuoteResult.selector) revert InvalidState();
            assembly ("memory-safe") { output := mload(add(reason,36)) afterPrice := mload(add(reason,68)) }
            if (output == 0 || afterPrice == 0) revert InvalidState();
        }
    }

function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager) || pendingQuoteHash == bytes32(0) || keccak256(data) != pendingQuoteHash) revert Unauthorized();
        (PoolKey memory key,bool direction,uint256 amount) = abi.decode(data,(PoolKey,bool,uint256));
        int256 delta = poolManager.swap(key,IPoolManagerMinimal.SwapParams(direction,-int256(amount),
            direction ? TickMath.MIN_SQRT_PRICE+1 : TickMath.MAX_SQRT_PRICE-1),"");
        int128 d0 = int128(delta >> 128); int128 d1 = int128(uint128(uint256(delta)));
        int128 spent = direction ? d0 : d1; int128 received = direction ? d1 : d0;
        if (spent >= 0 || received <= 0 || uint256(-int256(spent)) != amount) revert Slippage();
        (uint160 afterPrice,,,) = stateView.getSlot0(keccak256(abi.encode(key)));
        revert QuoteResult(uint256(int256(received)),afterPrice);
    }

constructor(address controller, address positionManager_, address stateView_, address poolManager_, address permit2_)
        ZZZModule(controller) {
        if (positionManager_.code.length == 0 || stateView_.code.length == 0 || poolManager_.code.length == 0 ||
            permit2_.code.length == 0) revert InvalidConfiguration();
        posm = IPositionManagerMinimal(positionManager_);
        stateView = IStateViewMinimal(stateView_);
        poolManager = IPoolManagerMinimal(poolManager_);
        permit2 = IPermit2Minimal(permit2_);
        if (posm.poolManager() != poolManager_ || posm.permit2() != permit2_ ||
            stateView.poolManager() != poolManager_) revert InvalidConfiguration();
        balancingRouter = new ZZZLPBalancer(controller,poolManager_,stateView_);
    }

receive() external payable {
        if (msg.sender != nativeSender || nativeSender == address(0)) revert Unauthorized();
        nativeReceived += msg.value;
    }

function balanceContext(bytes32 targetPool) external view returns (bytes32) {
        return _balanceContext(targetPool);
    }

function _balanceContext(bytes32 targetPool) private view returns (bytes32) {
        address emergency = _emergencyBudget();
        if(emergency != address(0)) return IZZZEmergencyBudget(emergency).emergencyFingerprint();
        return keccak256(abi.encode(address(balancingRouter),balancingRouter.executionRevision(),
            balancingRouter.policyFingerprint(targetPool,bytes32(0))));
    }

function _emergencyBudget() private view returns(address budget) {
        return msg.sender == access.module(Ids.VAULT) ? emergencyBudget : address(0);
    }

function beginEmergency() external onlyModule(Ids.VAULT) nonReentrant {
        if(emergencyBudget != address(0)) revert InvalidState();
        address budget = IZZZEmergencyVault(msg.sender).migrationBudget();
        IZZZEmergencyBudget(budget).validateEmergency(IZZZEmergencyBudget(budget).emergencyBucket());
        emergencyBudget = budget;
    }

function endEmergency() external onlyModule(Ids.VAULT) nonReentrant {
        address budget = emergencyBudget;
        // Set only by this same immutable Vault's beginEmergency, in one atomic
        // nonreentrant Vault operation. Its Budget binding cannot be replaced.
        if(budget == address(0)) revert InvalidState();
        IZZZEmergencyBudget(budget).validateEmergency(IZZZEmergencyBudget(budget).emergencyBucket());
        emergencyBudget = address(0);
    }

function _retains(uint8 bit) private view returns(bool) {
        address budget = _emergencyBudget();
        return budget == address(0) || (IZZZEmergencyBudget(budget).emergencyChecks() & bit) != 0;
    }

function _policySpot(bytes32 poolId) private view returns(uint160) {
        address budget = _emergencyBudget();
        if(budget != address(0)) return (IZZZEmergencyBudget(budget).emergencyChecks() & 2) != 0 ?
            IZZZStrategy(access.module(Ids.STRATEGY)).validateExitPrice(poolId) : spot(poolId);
        return IZZZStrategy(access.module(Ids.STRATEGY)).validatePrice(poolId);
    }

function spot(bytes32 poolId) public view returns (uint160 priceX96) {
        (priceX96,,,) = stateView.getSlot0(poolId);
    }

function _config(bytes32 poolId, bool requireOperations) private view returns (PoolConfig memory c) {
        c = IZZZPools(access.module(Ids.POOLS)).get(poolId);
        // Fresh production admission is native ETH/fixed ZZZ only. Historical
        // ERC20-pair deployments retain their own immutable implementation.
        if ((requireOperations && _retains(8) && !c.operationsEnabled) || keccak256(abi.encode(c.key)) != poolId ||
            c.key.currency0 != address(0) || c.key.currency1 == address(0) || c.key.fee > 100000 ||
            c.key.hooks != address(0) || !INativePoolAssets(access.module(Ids.POOLS)).isNativePool(poolId)) revert InvalidState();
    }

function _balance(address token, address owner) private view returns (uint256) {
        return token == address(0) ? owner.balance : IERC20(token).balanceOf(owner);
    }

function _sendNative(address recipient, uint256 amount) private {
        if (amount == 0) return;
        uint256 beforeNative = address(this).balance;
        (bool ok,) = recipient.call{value: amount}("");
        if (!ok || address(this).balance + amount != beforeNative) revert InvalidState();
    }

function _finishNativeCredit(uint256 beforeNative, address recipient) private {
        nativeSender = address(0);
        uint256 amount = nativeReceived;
        nativeReceived = 0;
        if (address(this).balance != beforeNative + amount) revert InvalidState();
        _sendNative(recipient, amount);
    }

function _checkPosition(bytes32 poolId, uint256 id) private view returns (int24 lower, int24 upper) {
        if (posm.ownerOf(id) != access.module(Ids.VAULT)) revert InvalidState();
        (PoolKey memory key, uint256 info) = posm.getPoolAndPositionInfo(id);
        if (keccak256(abi.encode(key)) != poolId) revert InvalidState();
        lower = int24(uint24(info >> 8));
        upper = int24(uint24(info >> 32));
    }

function _approve(address token, uint256 amount, uint256 deadline) private {
        if (amount > type(uint128).max) revert InvalidAmount();
        IERC20(token).forceApprove(address(permit2), amount);
        permit2.approve(token, address(posm), uint160(amount), uint48(deadline));
    }

function _reset(address token) private {
        permit2.approve(token, address(posm), 0, 0);
        IERC20(token).forceApprove(address(permit2), 0);
    }

function _mintOrIncrease(bytes32 poolId, uint256 id, int24 lower, int24 upper, uint256 amount0,
        uint256 amount1, uint128 minimumLiquidity, uint256 deadline)
        private returns (uint256 tokenId, uint256 spent0, uint256 spent1) {
        _deadline(deadline);
        if (amount0 > type(uint128).max || amount1 > type(uint128).max) revert InvalidAmount();
        PoolConfig memory c = _config(poolId, true);
        uint160 current = _policySpot(poolId);
        if (lower % c.key.tickSpacing != 0 || upper % c.key.tickSpacing != 0 || lower >= upper) revert InvalidConfiguration();
        uint128 previousLiquidity = id == 0 ? 0 : posm.getPositionLiquidity(id);
        (uint128 liquidity,uint256 nativeValue) = balancingRouter.deploymentAmounts(current,lower,upper,amount0,amount1);
        if (liquidity == 0 || liquidity < minimumLiquidity) revert Slippage();
        address t1 = c.key.currency1;
        if (msg.value != amount0) revert InvalidAmount();
        uint256 before0 = address(this).balance - msg.value;
        uint256 before1 = IERC20(t1).balanceOf(address(this));
        ExactToken.pull(t1, msg.sender, amount1);
        uint256 beforeNative = address(this).balance;
        if (beforeNative != before0 + msg.value) revert InvalidState();
        // No SWEEP: pay exactly rounded-up principal debt. Prior PosM donations
        // cannot fund this operation and any unconsumed value makes it revert.
        if (nativeValue > amount0) revert Slippage();
        uint256 beforePosmNative = address(posm).balance;
        _approve(t1, amount1, deadline);
        bytes[] memory parameters = new bytes[](2);
        tokenId = id;
        if (id == 0) {
            tokenId = posm.nextTokenId();
            parameters[0] = abi.encode(c.key, lower, upper, uint256(liquidity), uint128(amount0), uint128(amount1),
                access.module(Ids.VAULT), bytes(""));
        } else {
            parameters[0] = abi.encode(id, uint256(liquidity), uint128(amount0), uint128(amount1), bytes(""));
        }
        parameters[1] = abi.encode(c.key.currency0, c.key.currency1);
        posm.modifyLiquidities{value: nativeValue}(
            abi.encode(abi.encodePacked(id == 0 ? MINT : INCREASE, SETTLE_PAIR), parameters), deadline);
        if (address(posm).balance != beforePosmNative || address(this).balance + nativeValue != beforeNative) revert InvalidState();
        _reset(t1);
        uint256 unused0 = address(this).balance - before0;
        uint256 unused1 = IERC20(t1).balanceOf(address(this)) - before1;
        if (unused0 > amount0 || unused1 > amount1) revert InvalidState();
        spent0 = amount0 - unused0;
        spent1 = amount1 - unused1;
        _sendNative(msg.sender, unused0);
        ExactToken.push(t1, msg.sender, unused1);
        // A static hookless mint/increase does not move the pool price. Token
        // approvals, pulls, settlement and refunds can nevertheless call external
        // code. Check the final mark and physical LP only after ALL those calls,
        // so incumbent repricing or a late LP mutation cannot masquerade as new LP.
        if (_policySpot(poolId) != current) revert Slippage();
        (int24 actualLower, int24 actualUpper) = _checkPosition(poolId, tokenId);
        if (actualLower != lower || actualUpper != upper ||
            uint256(posm.getPositionLiquidity(tokenId)) != uint256(previousLiquidity) + liquidity) revert InvalidState();
    }

function mint(bytes32 poolId, int24 lower, int24 upper, uint256 amount0, uint256 amount1,
        uint128 minimumLiquidity, uint256 deadline)
        external payable onlyModule(Ids.VAULT) nonReentrant returns (uint256 tokenId, uint256 spent0, uint256 spent1) {
        return _mintOrIncrease(poolId, 0, lower, upper, amount0, amount1, minimumLiquidity, deadline);
    }

function increase(bytes32 poolId, uint256 id, uint256 amount0, uint256 amount1,
        uint128 minimumLiquidity, uint256 deadline)
        external payable onlyModule(Ids.VAULT) nonReentrant returns (uint256 spent0, uint256 spent1) {
        (int24 lower, int24 upper) = _checkPosition(poolId, id);
        (, spent0, spent1) = _mintOrIncrease(poolId, id, lower, upper, amount0, amount1, minimumLiquidity, deadline);
    }

function collect(bytes32 poolId, uint256 id, uint256 deadline) external onlyModule(Ids.VAULT) nonReentrant {
        _deadline(deadline);
        PoolConfig memory c = _config(poolId, false);
        _checkPosition(poolId, id);
        bytes[] memory parameters = new bytes[](2);
        parameters[0] = abi.encode(id, uint256(0), uint128(0), uint128(0), bytes(""));
        _settleTakePair(c.key, DECREASE, parameters, deadline);
    }

function _settleTakePair(PoolKey memory key, uint8 action, bytes[] memory parameters, uint256 deadline) private {
        uint256 beforeNative = address(this).balance;
        nativeSender = address(poolManager); nativeReceived = 0;
        parameters[1] = abi.encode(key.currency0, key.currency1, address(this));
        uint256 beforeToken1 = IERC20(key.currency1).balanceOf(address(this));
        posm.modifyLiquidities(abi.encode(abi.encodePacked(action, TAKE_PAIR), parameters), deadline);
        _finishNativeCredit(beforeNative, access.module(Ids.VAULT));
        ExactToken.push(key.currency1, access.module(Ids.VAULT), IERC20(key.currency1).balanceOf(address(this)) - beforeToken1);
    }

function close(bytes32 poolId, uint256 id, uint256 deadline) external onlyModule(Ids.VAULT) nonReentrant {
        _deadline(deadline);
        PoolConfig memory c = _config(poolId, false);
        _checkPosition(poolId, id);
        (uint256 expected0, uint256 expected1) = amounts(id);
        uint256 min0 = Math.mulDiv(expected0, 10000 - c.maxSlippageBps, 10000);
        uint256 min1 = Math.mulDiv(expected1, 10000 - c.maxSlippageBps, 10000);
        if (min0 > type(uint128).max || min1 > type(uint128).max) revert InvalidAmount();
        bytes[] memory parameters = new bytes[](2);
        parameters[0] = abi.encode(id, uint128(min0), uint128(min1), bytes(""));
        _settleTakePair(c.key, BURN, parameters, deadline);
    }

function ticks(uint256 id) external view returns (int24 lower, int24 upper) {
        (, uint256 info) = posm.getPoolAndPositionInfo(id);
        return (int24(uint24(info >> 8)), int24(uint24(info >> 32)));
    }

function amounts(uint256 id) public view returns (uint256 amount0, uint256 amount1) {
        return balancingRouter.principalAmounts(id);
    }

function swap(bytes32 poolId, bool zeroForOne, uint256 amountIn, uint256 minimumOut, uint256 deadline)
        external payable nonReentrant returns (uint256 amountOut) {
        if (!access.isSealed() || (msg.sender != access.module(Ids.VAULT) && msg.sender != access.module(Ids.BUYBACK))) revert Unauthorized();
        _deadline(deadline);
        if (amountIn == 0 || amountIn > type(uint128).max) revert InvalidAmount();
        PoolConfig memory c = _config(poolId,true);
        address input = zeroForOne ? c.key.currency0 : c.key.currency1;
        if (msg.value != (input == address(0) ? amountIn : 0)) revert InvalidAmount();
        bytes32 context = _balanceContext(poolId);
        if (input != address(0)) ExactToken.pull(input, msg.sender, amountIn);
        uint256 beforeNative = address(this).balance - msg.value;
        amountOut = _swapExact(poolId,c,zeroForOne,amountIn,minimumOut,msg.sender);
        if (address(this).balance != beforeNative || _balanceContext(poolId) != context) revert InvalidState();
    }

function _swapExact(bytes32 poolId, PoolConfig memory c, bool zeroForOne, uint256 amountIn, uint256 minimumOut,
        address recipient) private returns (uint256 amountOut) {
        _policySpot(poolId);
        address output = zeroForOne ? c.key.currency1 : c.key.currency0;
        if (minimumOut == 0) revert Slippage();
        if(_retains(4)) minimumOut = Math.max(minimumOut,
            _emergencyBudget() == address(0) ? IZZZStrategy(access.module(Ids.STRATEGY)).minimumOutput(poolId,zeroForOne,amountIn) :
            IEmergencyOutput(access.module(Ids.STRATEGY)).minimumOutputForExit(poolId,zeroForOne,amountIn));
        uint256 beforeOutput = _balance(output,recipient);
        bytes memory payload = abi.encode(c.key, zeroForOne, amountIn, minimumOut, recipient);
        pendingSwapHash = keccak256(payload);
        amountOut = abi.decode(poolManager.unlock(payload), (uint256));
        if (pendingSwapHash != bytes32(0) || amountOut < minimumOut ||
            _balance(output,recipient) != beforeOutput+amountOut) revert InvalidState();
        _policySpot(poolId);
    }

function balance(bytes32 targetPool,uint256 existingLpId,uint256 amount0,uint256 amount1,uint256 deadline)
        external payable onlyModule(Ids.VAULT) nonReentrant returns (uint256 balanced0,uint256 balanced1) {
        _deadline(deadline);
        if (amount0 > type(uint128).max || amount1 > type(uint128).max || msg.value != amount0) revert InvalidAmount();
        PoolConfig memory target = _config(targetPool,true);
        // _config already requires native currency0, including in emergencies.
        bytes32 context = _balanceContext(targetPool);
        uint256 nativePrefund = address(this).balance-msg.value;
        uint256 tokenPrefund = IERC20(target.key.currency1).balanceOf(address(this));
        bool emergency = _emergencyBudget() != address(0);
        EmergencyRebalance memory request;
        if(emergency) request = IZZZEmergencyController(access.module(Ids.MIGRATION)).emergencyRequest();
        int24 lower; int24 upper; uint128 priorLiquidity;
        if (existingLpId != 0) {
            (lower,upper) = _checkPosition(targetPool,existingLpId);
            priorLiquidity = posm.getPositionLiquidity(existingLpId);
        } else if(emergency) {
            lower = request.lower; upper = request.upper;
        } else (lower,upper,) = IZZZStrategy(access.module(Ids.STRATEGY)).target(targetPool);
        // Pull before quoting: even a token callback cannot intervene between
        // the simulated route and the actual swap. Refund only this budget.
        ExactToken.pull(target.key.currency1,msg.sender,amount1);
        if (_balanceContext(targetPool) != context) revert InvalidState();
        ZZZLPBalancer.Plan memory p;
        if(emergency) {
            p.poolId = request.swapPool; p.zeroForOne = request.zeroForOne;
            p.amountIn = request.amountIn; p.minimumOut = request.minimumOut;
        } else p = balancingRouter.plan(targetPool,lower,upper,amount0,amount1);
        balanced0 = amount0; balanced1 = amount1;
        uint256 refund0 = amount0; uint256 refund1 = amount1;
        if (p.amountIn != 0) {
            PoolConfig memory venue = _config(p.poolId,true);
            if (venue.key.currency1 != target.key.currency1 ||
                p.amountIn > (p.zeroForOne ? amount0 : amount1)) revert InvalidState();
            uint256 output = _swapExact(p.poolId,venue,p.zeroForOne,p.amountIn,p.minimumOut,msg.sender);
            if (!emergency && (output != p.amountOut || spot(p.poolId) != p.sqrtAfter)) revert Slippage();
            if (p.zeroForOne) { balanced0 -= p.amountIn; balanced1 += output; refund0 -= p.amountIn; }
            else { balanced1 -= p.amountIn; balanced0 += output; refund1 -= p.amountIn; }
        }
        _sendNative(msg.sender,refund0);
        ExactToken.push(target.key.currency1,msg.sender,refund1);
        if (existingLpId != 0) {
            (int24 finalLower,int24 finalUpper) = _checkPosition(targetPool,existingLpId);
            if (lower != finalLower || upper != finalUpper || posm.getPositionLiquidity(existingLpId) != priorLiquidity) revert InvalidState();
        }
        if (address(this).balance != nativePrefund || IERC20(target.key.currency1).balanceOf(address(this)) != tokenPrefund ||
            _balanceContext(targetPool) != context) revert InvalidState();
        if(!emergency && (balancingRouter.executionRevision() != p.revision ||
            balancingRouter.policyFingerprint(targetPool,p.poolId) != p.fingerprint ||
            _policySpot(targetPool) != p.targetSqrtAfter)) revert InvalidState();
        if(emergency) _policySpot(targetPool);
    }

function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager) || pendingSwapHash == bytes32(0) ||
            pendingSwapHash != keccak256(data)) revert Unauthorized();
        pendingSwapHash = bytes32(0);
        (PoolKey memory key, bool zeroForOne, uint256 amountIn, uint256 minOut, address recipient) =
            abi.decode(data, (PoolKey, bool, uint256, uint256, address));
        int256 delta = poolManager.swap(key, IPoolManagerMinimal.SwapParams(zeroForOne, -int256(amountIn),
            zeroForOne ? TickMath.MIN_SQRT_PRICE + 1 : TickMath.MAX_SQRT_PRICE - 1), bytes(""));
        int128 delta0 = int128(delta >> 128);
        int128 delta1 = int128(uint128(uint256(delta)));
        int128 inputDelta = zeroForOne ? delta0 : delta1;
        int128 outputDelta = zeroForOne ? delta1 : delta0;
        if (inputDelta >= 0 || outputDelta <= 0 || uint256(-int256(inputDelta)) != amountIn ||
            uint256(int256(outputDelta)) < minOut) revert Slippage();
        address input = zeroForOne ? key.currency0 : key.currency1;
        address output = zeroForOne ? key.currency1 : key.currency0;
        poolManager.sync(input);
        if (input == address(0)) {
            if (poolManager.settle{value: amountIn}() != amountIn) revert InvalidState();
        } else {
            ExactToken.push(input, address(poolManager), amountIn);
            if (poolManager.settle() != amountIn) revert InvalidState();
        }
        uint256 amountOut = uint256(int256(outputDelta));
        if (output == address(0)) {
            uint256 beforeNative = address(this).balance;
            nativeSender = address(poolManager);
            nativeReceived = 0;
            poolManager.take(output, address(this), amountOut);
            if (nativeReceived != amountOut) revert InvalidState();
            _finishNativeCredit(beforeNative, recipient);
        } else poolManager.take(output, recipient, amountOut);
        return abi.encode(amountOut);
    }

modifier canonicalOnly() {
        if (msg.sender != access.canonicalHandoff()) revert CanonicalState();
        _;
    }

function _canonicalNext(uint256 row) private {
        if (_state() != 2 || canonicalCursor != row) revert CanonicalState();
        ++canonicalCursor;
    }

function settleDust() external onlyModule(Ids.VAULT) economic {
        IZZZVault vault = IZZZVault(access.module(Ids.VAULT));
        IZZZFees fees = IZZZFees(access.module(Ids.FEES));
        IZZZPools pools = IZZZPools(access.module(Ids.POOLS));
        uint256 count = vault.bucketCount();
        if (count > vault.MAX_BUCKETS()) revert InvalidState();
        for (uint256 i; i < count; ++i) {
            uint256 bucket = vault.bucketAt(i);
            Position memory position = vault.group(bucket);
            if (position.status != PositionStatus.Active && position.status != PositionStatus.Outbound &&
                position.status != PositionStatus.Parked) continue;
            // Dust uses immutable admitted currency identities, not a live venue
            // observation. A broken historical venue must not block healthy new
            // entry when its funded dust can still settle exactly. Current-pool
            // execution independently validates accounting and real LP backing.
            PoolConfig memory config = pools.get(position.poolId);
            fees.flushDust(bucket, config.key.currency0);
            fees.flushDust(bucket, config.key.currency1);
            if (IPairVault(address(vault)).migrationBudget().compositionEpoch(bucket) != 0) {
                IPairAssets assets = IPairAssets(access.module(Ids.REWARDS));
                if (assets.assetCount() > 33) revert InvalidState();
                for (uint256 j; j < assets.assetCount(); ++j) {
                    address token = assets.assets(j);
                    if (token != config.key.currency0 && token != config.key.currency1) fees.flushDust(bucket,token);
                }
            }
        }
    }

function activate(uint256 id) external onlyModule(Ids.VAULT) economic {
        if (eligible[id] || IZZZNFT(access.module(Ids.NFT)).ownerOf(id) == address(0)) revert InvalidState();
        // The inactive NFT checkpoints at the current index before its one
        // collective share exists, excluding every previously published reward.
        IZZZRewards(access.module(Ids.REWARDS)).checkpointAll(id);
        eligible[id] = true;
        ++totalEligible;
        emit MembershipActivated(id);
    }

function canonicalCapture() external canonicalOnly {
        if (_state() != 1) revert CanonicalState();
        canonicalNFTs = IZZZMembershipOrdinals(access.module(Ids.NFT)).mintedCount();
        canonicalEligible = totalEligible;
    }

function canonicalExport(uint256 row) external view returns (bytes memory) {
        if ((_state() != 1 && _state() != 3) || row > canonicalNFTs) revert CanonicalState();
        if (row == 0) return abi.encode(canonicalNFTs, totalEligible);
        uint256 id = IZZZMembershipOrdinals(access.module(Ids.NFT)).tokenAtOrdinal(row);
        return abi.encode(id, eligible[id]);
    }

function canonicalImport(uint256 row, bytes calldata record) external canonicalOnly {
        _canonicalNext(row);
        if (row == 0) {
            if (totalEligible != 0) revert CanonicalState();
            (canonicalNFTs, canonicalEligible) = abi.decode(record, (uint256,uint256));
            if (canonicalNFTs > 1000 || canonicalEligible > canonicalNFTs) revert CanonicalState();
            return;
        }
        (uint256 id, bool active) = abi.decode(record, (uint256,bool));
        if (row > canonicalNFTs || id != IZZZMembershipOrdinals(access.module(Ids.NFT)).tokenAtOrdinal(row)) revert CanonicalState();
        eligible[id] = active;
        if (active) ++totalEligible;
    }

function canonicalValidate() external view {
        if (_state() == 2 && (canonicalCursor != canonicalCount() || totalEligible != canonicalEligible)) revert CanonicalState();
    }

function canonicalActivate() external canonicalOnly {
        if (_state() != 2) revert CanonicalState();
    }

constructor(address controller) ZZZModule(controller) {
        validation = new ZZZCustodyValidation(controller);
    }

receive() external payable {
        if(msg.sender != access.module(Ids.VAULT)) revert Unauthorized();
    }

function _vault() private view returns(IHolderExitVault) {
        return IHolderExitVault(access.module(Ids.VAULT));
    }

function _nft() private view returns(IHolderExitNFT) {
        return IHolderExitNFT(access.module(Ids.NFT));
    }

function emergencyRebalance(EmergencyRebalance calldata request)
        external onlyGovernance operating principalOperating nonReentrant {
        _deadline(request.deadline);
        if(!access.isSealed() || !access.paused() || request.checks > 31 || request.bucket == 0 ||
            request.custodyHash != emergencyCustodyHash(request.bucket) ||
            request.amountIn > uint128(type(int128).max) || request.minimumOut > uint128(type(int128).max) ||
            request.minimumLiquidity == 0 || request.lower < TickMath.MIN_TICK || request.upper > TickMath.MAX_TICK ||
            request.lower >= request.upper || request.reviewHash == bytes32(0) ||
            (request.amountIn == 0 ? request.swapPool != bytes32(0) || request.minimumOut != 0 :
                request.swapPool == bytes32(0) || request.minimumOut == 0)) revert InvalidConfiguration();
        ZZZMigrationBudget budget = ZZZMigrationBudget(IZZZEmergencyVault(address(_vault())).migrationBudget());
        emergency = request;
        budget.beginEmergency(request.bucket,request.checks);
        bytes32 context = budget.emergencyFingerprint();
        IZZZEmergencyVault(address(_vault())).emergencyRebalance(request.bucket,request.minimumLiquidity,request.deadline);
        if(budget.emergencyFingerprint() != context) revert InvalidState();
        budget.endEmergency();
        delete emergency;
        emit EmergencyRebalanced(request.bucket,request.checks,
            keccak256(abi.encode(block.chainid,address(this),address(_vault()),request)),request.reviewHash);
    }

function emergencyFingerprint() external view returns(bytes32 result) {
        ZZZMigrationBudget budget = ZZZMigrationBudget(IZZZEmergencyVault(address(_vault())).migrationBudget());
        if(msg.sender != address(budget)) revert Unauthorized();
        EmergencyRebalance memory request = emergency;
        budget.validateEmergency(request.bucket);
        result = keccak256(abi.encode(request,access.governance(),
            IEmergencyRegistryRevision(access.module(Ids.POOLS)).configurationRevision()));
        if((request.checks & 6) != 0) {
            PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(_vault().group(request.bucket).poolId);
            IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
            (,,bytes32 a) = oracle.priceBounds(c.key.currency0); (,,bytes32 b) = oracle.priceBounds(c.key.currency1);
            result = keccak256(abi.encode(result,a,b,IZZZStrategy(access.module(Ids.STRATEGY)).executionQualityRevision()));
        }
    }

function emergencyCustodyHash(uint256 bucket) public view returns(bytes32) {
        IHolderExitVault vault = _vault();
        return keccak256(abi.encode(block.chainid,address(vault),bucket,vault.group(bucket),vault.bucketTotalShares(bucket)));
    }

function configureZZZ(address token,bytes32 codeHash,bytes32 reviewHash) external onlyGovernance nonReentrant {
        if(access.isSealed() || currentZZZ != address(0) || token.code.length == 0 || token.codehash != codeHash ||
            reviewHash == bytes32(0) || !IZZZRewards(access.module(Ids.REWARDS)).isAsset(token)) revert InvalidConfiguration();
        address buyback = access.module(Ids.BUYBACK);
        address source = IExitTokenRegistry(access.module(Ids.POOLS)).activationAssets();
        if(buyback.code.length == 0 || IExitTokenIdentity(buyback).zzz() != token ||
            IExitTokenIdentity(source).zzz() != token) revert InvalidConfiguration();
        currentZZZ = token;
        zzzCodeHash = codeHash;
        emit ZZZConfigured(token,codeHash,reviewHash);
    }

function beginCollectiveExit(bytes32 reviewHash) external onlyGovernance operating nonReentrant {
        if(!access.isSealed() || !access.paused() || access.lpExitStarted() || exitPhase != ExitPhase.Operating ||
            reviewHash == bytes32(0) || currentZZZ == address(0)) revert InvalidState();
        IHolderExitVault vault = _vault();
        uint256 count = vault.bucketCount();
        if(count > vault.MAX_BUCKETS()) revert InvalidState();
        for(uint256 i; i<count; ++i) {
            uint256 bucket = vault.bucketAt(i);
            Position memory p = vault.group(bucket);
            uint256 shares = vault.bucketTotalShares(bucket);
            if(shares == 0) {
                if(p.lpTokenId != 0 || p.idle0 != 0 || p.idle1 != 0 || p.status != PositionStatus.None) revert InvalidState();
                continue;
            }
            if((p.status != PositionStatus.Active && p.status != PositionStatus.Parked) ||
                (p.status == PositionStatus.Active && p.lpTokenId == 0) ||
                (p.status == PositionStatus.Parked && p.lpTokenId != 0)) revert InvalidState();
            PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
            if(c.key.currency0 != address(0) || c.key.currency1 != currentZZZ) revert InvalidConfiguration();
            bucketSettlement[bucket].totalShares = shares;
            settlementBuckets.push(bucket);
        }
        remainingBuckets = settlementBuckets.length;
        exitMintedCount = _nft().mintedCount();
        if(remainingBuckets == 0 || exitMintedCount == 0 || exitMintedCount > 1000) revert InvalidState();
        exitReviewHash = reviewHash;
        exitPhase = ExitPhase.Closing;
        // The nonreentrant Vault barrier rejects a start during any in-flight
        // contribution, LP execution or principal callback before setting Access.
        vault.beginLPExit();
        if(!access.lpExitStarted()) revert InvalidState();
        emit CollectiveExitStarted(reviewHash,exitMintedCount,remainingBuckets);
    }

function closeBucket(uint256 bucket,uint256 minimumETH,uint256 minimumZZZ,uint256 deadline)
        external onlyGovernance operating nonReentrant {
        _deadline(deadline);
        BucketSettlement storage s = bucketSettlement[bucket];
        if(exitPhase != ExitPhase.Closing || !access.lpExitStarted() || !access.paused() ||
            s.totalShares == 0 || s.closed || _vault().bucketTotalShares(bucket) != s.totalShares) revert InvalidState();
        uint256 beforeETH = address(this).balance;
        uint256 beforeZZZ = ExactAsset.balance(currentZZZ,address(this));
        (uint256 ethAmount,uint256 zzzAmount) = _vault().exitBucketToHolders(bucket,minimumETH,minimumZZZ,deadline);
        if(address(this).balance != beforeETH+ethAmount ||
            ExactAsset.balance(currentZZZ,address(this)) != beforeZZZ+zzzAmount ||
            _vault().group(bucket).status != PositionStatus.Exited ||
            _vault().bucketTotalShares(bucket) != s.totalShares) revert InvalidState();
        s.ethAmount = ethAmount; s.zzzAmount = zzzAmount; s.closed = true;
        remainingETH += ethAmount; remainingZZZ += zzzAmount;
        ++custodyEpoch[bucket];
        if(--remainingBuckets == 0) {
            exitPhase = ExitPhase.Allocating;
            allocationCursor = 1;
        }
        emit BucketClosed(bucket,s.totalShares,ethAmount,zzzAmount);
    }

function allocatePrincipal(uint256 maximum) external operating nonReentrant {
        if(exitPhase != ExitPhase.Allocating || maximum == 0 || maximum > MAX_BATCH) revert InvalidState();
        IHolderExitNFT nft = _nft(); IHolderExitVault vault = _vault();
        uint256 end = Math.min(allocationCursor+maximum,exitMintedCount+1);
        for(uint256 ordinal=allocationCursor; ordinal<end; ++ordinal) {
            uint256 id = nft.tokenAtOrdinal(ordinal);
            if(id == 0 || principalOf[id].allocated) revert InvalidState();
            uint256 shares = vault.sharesOf(id); uint256 bucket = vault.nftBucket(id);
            Principal storage p = principalOf[id]; p.allocated = true;
            if(shares == 0) {
                if(bucket != 0) revert InvalidState();
                continue;
            }
            BucketSettlement storage s = bucketSettlement[bucket];
            if(!s.closed || s.totalShares == 0) revert InvalidState();
            uint256 cumulative = s.allocatedShares+shares;
            if(cumulative > s.totalShares) revert InvalidState();
            uint256 ethTotal = Math.mulDiv(s.ethAmount,cumulative,s.totalShares);
            uint256 zzzTotal = Math.mulDiv(s.zzzAmount,cumulative,s.totalShares);
            p.ethAmount = ethTotal-s.allocatedETH; p.zzzAmount = zzzTotal-s.allocatedZZZ;
            s.allocatedShares = cumulative; s.allocatedETH = ethTotal; s.allocatedZZZ = zzzTotal;
            emit PrincipalAllocated(id,bucket,p.ethAmount,p.zzzAmount);
            // Bounded ERC-4906 event only: no receiver callback or price read.
            nft.refreshMetadata(id);
        }
        allocationCursor = end;
        if(end == exitMintedCount+1) {
            for(uint256 i; i<settlementBuckets.length; ++i) {
                BucketSettlement memory s = bucketSettlement[settlementBuckets[i]];
                if(s.allocatedShares != s.totalShares || s.allocatedETH != s.ethAmount || s.allocatedZZZ != s.zzzAmount)
                    revert InvalidState();
            }
            _backed(); exitPhase = ExitPhase.Ready;
            emit PrincipalDistributionReady(remainingETH,remainingZZZ);
        }
    }

function claimablePrincipal(uint256 id) external view returns(uint256 ethAmount,uint256 zzzAmount) {
        Principal memory p = principalOf[id];
        if(exitPhase != ExitPhase.Ready || !p.allocated) revert NotReady();
        return p.paid ? (uint256(0),uint256(0)) : (p.ethAmount,p.zzzAmount);
    }

function distributePrincipal(uint256[] calldata ids) external operating nonReentrant returns(uint256 paid) {
        if(exitPhase != ExitPhase.Ready || ids.length == 0 || ids.length > MAX_BATCH) revert InvalidState();
        for(uint256 i; i<ids.length; ++i) {
            if(gasleft() < PAYOUT_GAS+60000) break;
            Principal memory p = principalOf[ids[i]];
            if(!p.allocated || p.paid || (p.ethAmount == 0 && p.zzzAmount == 0)) continue;
            try this.payCurrentOwner{gas:PAYOUT_GAS}(ids[i]) { ++paid; }
            catch { emit PrincipalDeferred(ids[i]); }
        }
    }

function payCurrentOwner(uint256 id) external {
        if(msg.sender != address(this)) revert Unauthorized();
        _pay(id,_nft().ownerOf(id));
    }

function claimPrincipal(uint256 id,address recipient) external operating nonReentrant {
        if(_nft().ownerOf(id) != msg.sender) revert Unauthorized();
        _pay(id,recipient);
    }

function _pay(uint256 id,address recipient) private {
        Principal storage p = principalOf[id];
        if(exitPhase != ExitPhase.Ready || !p.allocated || p.paid || (p.ethAmount == 0 && p.zzzAmount == 0) ||
            recipient == address(0) || recipient == address(this))
            revert InvalidState();
        address owner = _nft().ownerOf(id);
        _backed();
        p.paid = true;
        remainingETH -= p.ethAmount; remainingZZZ -= p.zzzAmount;
        ExactAsset.push(currentZZZ,recipient,p.zzzAmount);
        ExactAsset.push(address(0),recipient,p.ethAmount);
        _backed();
        emit PrincipalPaid(id,owner,recipient,p.ethAmount,p.zzzAmount);
    }

function _backed() private view {
        if(address(this).balance < remainingETH || ExactAsset.balance(currentZZZ,address(this)) < remainingZZZ) revert InvalidState();
    }

function moveFunds(uint256 id,bytes32 pool,uint128 minimum,uint256 deadline)
        external onlyGovernance live principalOperating nonReentrant {
        _vault().movePool(id,pool,minimum,deadline);
    }

function resume(uint256 id,bytes32 pool,uint128 minimum,uint256 deadline)
        external onlyGovernance live principalOperating nonReentrant {
        _vault().resume(id,pool,minimum,deadline);
    }

function park(ParkingRequest calldata r) external onlyDrainGovernance principalOperating nonReentrant {
        _deadline(r.deadline); IHolderExitVault vault = _vault(); Position memory p = vault.group(r.bucketId);
        validation.validateParking(abi.encode(r)); ++parkingNonce[r.bucketId];
        vault.park(r.bucketId,r.deadline); Position memory afterPosition = vault.group(r.bucketId);
        uint256 a0 = afterPosition.idle0-p.idle0; uint256 a1 = afterPosition.idle1-p.idle1;
        if(afterPosition.status != PositionStatus.Parked || afterPosition.lpTokenId != 0 ||
            a0 < r.minimum0 || a1 < r.minimum1) revert Slippage();
        emit ParkingExecuted(keccak256(abi.encode(block.chainid,address(this),address(vault),r)),r.bucketId,r.nonce,a0,a1);
    }

function invalidateParking(uint256 id) external onlyDrainGovernance principalOperating {
        ++parkingNonce[id]; emit ParkingInvalidated(id,parkingNonce[id]);
    }

constructor(address controller) {
        vault = msg.sender;
        access = IZZZAccess(controller);
    }

function beginEmergency(uint256 bucket,uint8 checks) external nonReentrant {
        if(msg.sender != access.module(Ids.MIGRATION) || emergencyActive || snapshot.value != 0) revert Unauthorized();
        emergencyBucket = bucket; emergencyChecks = checks; emergencyGovernor = access.governance(); emergencyActive = true;
        validateEmergency(bucket);
    }

function endEmergency() external nonReentrant {
        if(msg.sender != access.module(Ids.MIGRATION) || snapshot.value != 0) revert Unauthorized();
        validateEmergency(emergencyBucket);
        delete emergencyBucket; delete emergencyChecks; delete emergencyGovernor; emergencyActive = false;
    }

function validateEmergency(uint256 bucket) public view {
        if(!emergencyActive || emergencyBucket != bucket || access.governance() != emergencyGovernor ||
            !access.isSealed() || !access.paused() || access.preparationActive() ||
            access.canonicalState() != 0 || access.lpExitStarted()) revert InvalidState();
    }

function emergencyFingerprint() external view returns(bytes32 result) {
        validateEmergency(emergencyBucket);
        result = IEmergencyManifest(access.module(Ids.MIGRATION)).emergencyFingerprint();
        // A retained sample requirement must survive callbacks even when the
        // value guard is deliberately disabled. Compare the stable policy/raw
        // record, not readiness against the deliberately replaced LP identity.
        if((emergencyChecks & 16) != 0) result = keccak256(abi.encode(result,
            _confirmationControl(emergencyBucket,IZZZVault(vault).group(emergencyBucket).poolId)));
    }

function setLossLimits(uint16 contribution, uint16 maintenance) external nonReentrant {
        if (!access.canConfigure(msg.sender)) revert Unauthorized();
        if (access.preparationActive()) revert Preparing();
        if (access.canonicalState() != 0) revert CanonicalLocked();
        if (contribution > MAX_LOSS_BPS || maintenance > MAX_LOSS_BPS || snapshot.value != 0) revert InvalidConfiguration();
        emit ContributionLossLimitChanged(contributionLossBps, contribution);
        emit MaintenanceLossLimitChanged(maintenanceLossBps, maintenance);
        contributionLossBps = contribution;
        maintenanceLossBps = maintenance;
    }

function setCompoundInterval(bytes32 poolId,uint32 interval) external nonReentrant {
        if (!access.canConfigure(msg.sender)) revert Unauthorized();
        if (access.preparationActive()) revert Preparing();
        if (access.canonicalState() != 0) revert CanonicalLocked();
        if (interval < 600 || interval > 7 days || snapshot.value != 0) revert InvalidConfiguration();
        _knownPool(poolId);
        uint32 previous = _compoundInterval(poolId);
        compoundIntervals[poolId] = interval;
        emit CompoundIntervalChanged(poolId,previous,interval);
    }

function compoundInterval(bytes32 poolId) external view returns(uint32) {
        _knownPool(poolId);
        return _compoundInterval(poolId);
    }

function _compoundInterval(bytes32 poolId) private view returns(uint32 interval) {
        interval = compoundIntervals[poolId];
        if (interval == 0) interval = DEFAULT_COMPOUND_INTERVAL;
    }

function _knownPool(bytes32 poolId) private view {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).get(poolId);
        if (poolId == bytes32(0) || c.key.tickSpacing <= 0 || keccak256(abi.encode(c.key)) != poolId) revert InvalidConfiguration();
    }

modifier onlyVault() {
        if (msg.sender != vault) revert Unauthorized();
        _;
    }

function recordComposition(uint256 id) external onlyVault {
        ++compositionEpoch[id];
    }

function validateOwner(uint256 id,address caller,bool minted,bool activation) external view onlyVault returns (address entry) {
        return IBudgetVaultValidation(access.module(Ids.VAULT_CANONICAL)).validateOwner(id,caller,minted,activation);
    }

function importComposition(uint256 id, uint64 epoch) external {
        if (msg.sender != access.module(Ids.VAULT_CANONICAL) ||
            IZZZCanonicalAccess(address(access)).canonicalState() != 2 || compositionEpoch[id] != 0) revert Unauthorized();
        compositionEpoch[id] = epoch;
    }

function _balance(address asset) private view returns(uint256) {
        return asset==address(0)?vault.balance:IERC20(asset).balanceOf(vault);
    }

function assertIdle(uint256 id) external view onlyVault {
        (address a,address b) = poolTokens(IZZZVault(vault).group(id).poolId);
        if (_balance(a) < IMigrationIdle(vault).totalIdle(a) ||
            _balance(b) < IMigrationIdle(vault).totalIdle(b)) revert InvalidState();
    }

function validateCanonicalWriter(address caller) external view onlyVault {
        if (caller != access.module(Ids.VAULT_CANONICAL) || IZZZCanonicalAccess(address(access)).canonicalState() != 2) revert Unauthorized();
    }

function compoundReady(uint256 id) public view returns (bool) {
        return _pricing().compoundReady(id);
    }

function checkpoint(uint256 id, uint8 phase) external onlyVault {
        if(emergencyActive) {
            validateEmergency(id);
            if(_skip(4)) return;
        }
        if (phase == 0) _beforeMove(id);
        else if (phase == 1) _includeCompound(id);
        else if (phase == 2) _afterMove(id);
        else if (phase == 3) {
            if (!compoundReady(id)) revert InvalidState();
            _beforeMove(id);
            lastCompound[id] = uint64(block.timestamp);
        }
        else revert InvalidState();
    }

function _beforeMove(uint256 id) private {
        if (snapshot.value != 0) revert InvalidState();
        Position memory p = IZZZVault(vault).group(id);
        Snapshot memory s;
        s.bucketId = id;
        s.lossBps = maintenanceLossBps;
        s.confirmationControl = _confirmationControl(id,p.poolId);
        // Price validates feed/sequencer freshness. Reuse this exact vector after
        // close, swap and mint; callbacks cannot reprice away execution loss.
        ZZZContributionPricing.MaintenanceMark memory mark = _pricing().markMaintenance(id);
        s.price0 = mark.price0; s.price1 = mark.price1; s.scale0 = mark.scale0; s.scale1 = mark.scale1;
        s.idle0 = mark.idle0; s.idle1 = mark.idle1; s.value = mark.value;
        if (s.value == 0) revert InvalidState();
        snapshot = s;
    }

function _includeCompound(uint256 id) private {
        Snapshot memory s = snapshot;
        if (s.value == 0 || s.bucketId != id || compoundIncluded) revert InvalidState();
        Position memory p = IZZZVault(vault).group(id);
        snapshot.value = s.value + _value(p.idle0 - s.idle0, p.idle1 - s.idle1, s);
        compoundIncluded = true;
    }

function _afterMove(uint256 id) private {
        Snapshot memory s = snapshot;
        if (s.value == 0 || s.bucketId != id || !compoundIncluded) revert InvalidState();
        Position memory afterPosition = IZZZVault(vault).group(id);
        (uint256 deployed, uint256 idle) = _pricing().maintenanceValues(id,s.price0,s.price1,s.scale0,s.scale1);
        uint256 retained = deployed + idle;
        // Round the captured retained-value floor up. Later policy changes cannot
        // weaken this operation's aggregate budget. Gas is
        // outside these custody ledgers. Keep the existing 5% idle ceiling under
        // this same vector, including when an admitted feed changes mid-call.
        if (s.confirmationControl != _confirmationControl(id,afterPosition.poolId) ||
            retained < s.value - Math.mulDiv(s.value, s.lossBps, 10000) || deployed == 0 ||
            idle > Math.mulDiv(retained, 500, 10000)) revert Slippage();
        delete snapshot;
        delete compoundIncluded;
        emit MigrationValueChecked(id, s.value, deployed, idle);
    }

function _value(uint256 amount0, uint256 amount1, Snapshot memory s) private pure returns (uint256) {
        return Math.mulDiv(amount0, s.price0, s.scale0) + Math.mulDiv(amount1, s.price1, s.scale1);
    }

function _pricing() private view returns(ZZZContributionPricing) {
        return ZZZContributionPricing(IZZZOracle(access.module(Ids.ORACLE)).contributionPricing());
    }

function valueBucket(uint256 bucket,uint256 amount0,uint256 amount1) external view returns(uint256) {
        return _pricing().valueBucket(bucket,amount0,amount1);
    }

function nav(uint256 id) public view returns(uint256 deployed,uint256 idle) {
        return _pricing().nav(id);
    }

function contributionNav(uint256 id) external onlyVault returns(uint256 deployed,uint256 idle) {
        return _pricing().contributionNav(id);
    }

function assertDeployed(uint256 id) external view {
        if(msg.sender == vault && _skip(4)) return;
        (uint256 deployed, uint256 idle) = nav(id);
        if (deployed == 0 || idle > Math.mulDiv(deployed + idle, 500, 10000)) revert Slippage();
    }

function assertPut(uint256 id, uint256 a0, uint256 a1, uint256 spent0, uint256 spent1,
        uint256 before0, uint256 before1) external view onlyVault {
        Position memory p = IZZZVault(vault).group(id);
        (address token0, address token1) = poolTokens(p.poolId);
        address manager = IZZZLiquidity(access.module(Ids.LIQUIDITY)).positionManager();
        if (spent0 > a0 || spent1 > a1 || _balance(token0) + spent0 != before0 ||
            _balance(token1) + spent1 != before1 ||
            IPositionManagerMinimal(manager).ownerOf(p.lpTokenId) != vault) revert InvalidState();
    }

function validateNativeSender(address sender) external view onlyVault returns (bool liquidityCredit) {
        liquidityCredit = sender == access.module(Ids.LIQUIDITY);
        if (!liquidityCredit && sender != access.module(Ids.FEES) &&
            sender != access.module(Ids.VAULT_CANONICAL)) revert Unauthorized();
    }

function validateLPReceiver(address sender) external view onlyVault {
        address manager = access.module(Ids.LIQUIDITY);
        if (manager == address(0) || sender != IZZZLiquidity(manager).positionManager()) revert Unauthorized();
    }

function mintTarget(uint256 id) external view onlyVault returns (int24,int24,uint160) {
        if(emergencyActive) {
            validateEmergency(id);
            (int24 lower,int24 upper) = IEmergencyManifest(access.module(Ids.MIGRATION)).emergencyTarget();
            return(lower,upper,
                IZZZLiquidity(access.module(Ids.LIQUIDITY)).spot(IZZZVault(vault).group(id).poolId));
        }
        return IZZZStrategy(access.module(Ids.STRATEGY)).target(IZZZVault(vault).group(id).poolId);
    }

function balanceContext(uint256 id) external view onlyVault returns(bytes32) {
        if(emergencyActive) { validateEmergency(id); return this.emergencyFingerprint(); }
        return IZZZLiquidity(access.module(Ids.LIQUIDITY)).balanceContext(IZZZVault(vault).group(id).poolId);
    }

function poolTokens(bytes32 poolId) public view returns (address token0, address token1) {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        return (c.key.currency0, c.key.currency1);
    }

function validateReservation(bytes32 poolId,uint256 bucket) external view onlyVault {
        if (poolId == bytes32(0) || bucket == 0) revert InvalidConfiguration();
        IZZZPools(access.module(Ids.POOLS)).get(poolId);
        uint256 old = IZZZVault(vault).poolBucket(poolId);
        if (old != 0 && old != bucket) revert InvalidState();
    }

function validateMove(uint256 id, bytes32 nextPool, uint128 minimumLiquidity) external view onlyVault {
        PoolConfig memory oldConfig = IZZZPools(access.module(Ids.POOLS)).accounting(IZZZVault(vault).group(id).poolId);
        PoolConfig memory nextConfig = IZZZPools(access.module(Ids.POOLS)).accounting(nextPool);
        if (minimumLiquidity == 0 || oldConfig.key.currency0 != nextConfig.key.currency0 ||
            oldConfig.key.currency1 != nextConfig.key.currency1 || !nextConfig.operationsEnabled) revert InvalidConfiguration();
    }

function validateUnwind(uint256 id) external view onlyVault {
        if(_skip(2)) return;
        IZZZStrategy(access.module(Ids.STRATEGY)).validateExitPrice(IZZZVault(vault).group(id).poolId);
    }

function validateRebalance(uint256 id, uint128 minimumLiquidity) external view onlyVault {
        if(emergencyActive) {
            validateEmergency(id);
            if(!_skip(1) && !IZZZStrategy(access.module(Ids.STRATEGY)).needsRebalance(id)) revert InvalidState();
            if(!_skip(16) && !IConfirmationControl(IZZZStrategy(access.module(Ids.STRATEGY)).rebalanceConfirmation())
                .emergencyReady(id)) revert InvalidState();
            return;
        }
        if (minimumLiquidity == 0 || !IZZZStrategy(access.module(Ids.STRATEGY)).rebalanceReady(id)) revert InvalidState();
    }

function _confirmationControl(uint256 id,bytes32 poolId) private view returns(bytes32) {
        IConfirmationControl confirmation = IConfirmationControl(
            IZZZStrategy(access.module(Ids.STRATEGY)).rebalanceConfirmation());
        // Compare raw evidence, not post-replacement readiness (the new LP
        // deliberately has a different identity). A callback reset must abort.
        return confirmation.observationFingerprint(id,poolId);
    }

function idleValue(uint256 id) public view returns (uint256) {
        if(msg.sender == vault && _skip(4)) return 0; // Internal sentinel, never an external zero USD valuation.
        Position memory p = IZZZVault(vault).group(id);
        (address token0, address token1) = poolTokens(p.poolId);
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        return oracle.value(token0, p.idle0) + oracle.value(token1, p.idle1);
    }

function assertIdleLoss(uint256 id, uint256 beforeValue) external view onlyVault {
        if(_skip(4)) return;
        uint16 slippage = IZZZPools(access.module(Ids.POOLS)).accounting(IZZZVault(vault).group(id).poolId).maxSlippageBps;
        if (beforeValue == 0 || idleValue(id) < Math.mulDiv(beforeValue, 10000 - slippage, 10000)) revert Slippage();
    }

function validateContribution(uint256 id, uint256 bucket, uint256 inputUSD, uint256 inputTotal,
        uint128 minimumLiquidity, bool activation) external onlyVault returns (address token0, address token1, uint32 limits) {
        uint16 captured = contributionLossBps;
        uint16 venue;
        (token0,token1,venue) = IBudgetVaultValidation(access.module(Ids.VAULT_CANONICAL)).validateContribution(
            id,bucket,inputUSD,inputTotal,minimumLiquidity,activation);
        // Carry both limits in the existing third ABI word: low 16 bits are the
        // venue limit; high 16 bits freeze the contribution policy before callbacks.
        limits = uint32(venue) | (uint32(captured) << 16);
        _pricing().begin(id,bucket,inputTotal,inputUSD,limits);
    }

function contributionResult(uint256 bucket,uint256 inputUSD,uint256 supply,uint256 incumbentNAV,
        uint256 incumbentDeployed,uint256 deployed,uint256 idle,uint32 limits)
        external onlyVault returns(uint256 issued,uint256 netUSD) {
        return _pricing().finish(bucket,inputUSD,supply,incumbentNAV,incumbentDeployed,deployed,idle,limits);
    }

function historicalCompoundValue(uint256 id) public view returns(uint256) {
        return _pricing().historicalValue(id);
    }

constructor(address controller, string memory baseURI)
        ERC721("ZZZ Permanent Liquidity Rights", "ZZZLP") ZZZModule(controller) {
        _validateBaseURI(baseURI);
        metadataBase = baseURI;
        metadataConfigured = bytes(baseURI).length != 0;
        royaltyRewards = ZZZRoyaltyFactory(access.royaltyFactory()).create();
        if (royaltyRewards.canonicalController() != controller || royaltyRewards.nft() != address(this)) revert InvalidConfiguration();
        claimRouter = new ZZZClaimRouter(controller, address(this), address(royaltyRewards));
        metadataRenderer = new ZZZNFTMetadata(controller);
    }

function configureRandomness(address coordinator, bytes32 gasLane, uint256 subId, uint16 confirmations,
        uint32 gasLimit, bool payNative) external onlyGovernance {
        if (access.isSealed() || randomnessConfigured || coordinator.code.length == 0 ||
            gasLane == bytes32(0) || subId == 0 || confirmations < 3 || confirmations > 200 ||
            gasLimit < 200000 || gasLimit > 10000000) revert InvalidConfiguration();
        randomnessCoordinator = coordinator; keyHash = gasLane; subscriptionId = subId;
        requestConfirmations = confirmations; callbackGasLimit = gasLimit; nativePayment = payNative;
        randomnessConfigured = true;
        emit RandomnessConfigured(coordinator, gasLane, subId, confirmations, gasLimit, payNative);
    }

function setRandomnessRequestSettings(uint16 confirmations, uint32 gasLimit)
        external onlyGovernance operating nonReentrant {
        if (!randomnessConfigured) revert NotReady();
        if (confirmations < 3 || confirmations > 200 || gasLimit < 200000 || gasLimit > 10000000)
            revert InvalidConfiguration();
        uint16 previousConfirmations = requestConfirmations;
        uint32 previousCallbackGasLimit = callbackGasLimit;
        requestConfirmations = confirmations; callbackGasLimit = gasLimit;
        emit RandomnessRequestSettingsChanged(previousConfirmations, previousCallbackGasLimit, confirmations, gasLimit);
    }

function setMintPaused(bool state) external onlyGovernance {
        mintPaused = state;
        emit MintPauseChanged(state);
    }

function mint(address to, uint256 id) external onlyModule(Ids.VAULT) operating principalOperating nonReentrant {
        if (mintPaused) revert Paused();
        if (!randomnessConfigured) revert NotReady();
        if (mintedCount == MAX_SUPPLY) revert InvalidState();
        address recipient = IZZZVault(msg.sender).mintProceedsRecipient();
        if (recipient == address(royaltyRewards) || recipient == address(this)) revert InvalidConfiguration();
        uint256 ordinal = ++mintedCount;
        mintOrdinalOf[id] = ordinal; tokenAtOrdinal[ordinal] = id;
        // Bind before the ERC721 receiver callback. Official fulfillment is
        // asynchronous; a synchronous coordinator callback is rejected.
        uint256 requestId = IZZZVRFCoordinator(randomnessCoordinator).requestRandomWords(
            IZZZVRFCoordinator.RandomWordsRequest(keyHash, subscriptionId, requestConfirmations,
                callbackGasLimit, 2, abi.encodeWithSelector(bytes4(keccak256("VRF ExtraArgsV1")), nativePayment)));
        bytes32 requestKey = _requestKey(randomnessEpoch, requestId);
        if (requestId == 0 || randomness[requestKey].requested) revert InvalidState();
        randomness[requestKey].nftId = id; randomness[requestKey].requested = true;
        requestEpochOf[id] = randomnessEpoch;
        requestOf[id] = requestId;
        _safeMint(to, id);
        if (mintPaused) revert Paused();
        emit RandomnessRequested(id, requestId, ordinal);
    }

function rawFulfillRandomWords(uint256 requestId, uint256[] calldata words) external {
        if (msg.sender != randomnessCoordinator) revert Unauthorized();
        RandomnessResult storage result = randomness[_requestKey(randomnessEpoch, requestId)];
        if (!result.requested || result.fulfilled || words.length != 2) revert InvalidState();
        result.fulfilled = true; result.rarityWord = words[0]; result.colorWord = words[1];
        emit RandomnessReceived(requestId);
    }

function finalizeTraits(uint256 id) external nonReentrant canonicalAccounting {
        _requireOwned(id);
        RandomnessResult storage result = randomness[_requestKey(requestEpochOf[id], requestOf[id])];
        if (!result.fulfilled || traitsReady[id] || mintOrdinalOf[id] != nextToFinalize || result.nftId != id) {
            revert NotReady();
        }
        uint256 rarityRoll = result.rarityWord % remainingToReveal;
        uint8 rarity = rarityRoll < rarityRemaining[0] ? 0 :
            rarityRoll < uint256(rarityRemaining[0]) + rarityRemaining[1] ? 1 : 2;
        (uint8 palette, uint8 pattern) = _drawArtwork(rarity, result.colorWord, rarityRemaining[rarity]);
        --rarityRemaining[rarity]; --remainingToReveal; ++nextToFinalize;
        rarityOf[id] = rarity; paletteOf[id] = palette; patternOf[id] = pattern;
        colorOf[id] = ZZZArtwork.primaryColor(palette);
        traitsReady[id] = true;
        emit TraitsFinalized(id, rarity, colorOf[id]);
        emit ArtworkFinalized(id, palette, pattern);
        emit MetadataUpdate(id);
    }

function _drawArtwork(uint8 rarity, uint256 word, uint256 remaining) private returns (uint8, uint8) {
        uint256 draw = word % remaining;
        uint16 stored = artworkDraw[rarity][draw];
        uint256 entry = stored == 0 ? draw : uint256(stored) - 1;
        uint256 last = remaining - 1;
        if (draw != last) {
            uint16 replacement = artworkDraw[rarity][last];
            artworkDraw[rarity][draw] = replacement == 0 ? uint16(last + 1) : replacement;
        }
        delete artworkDraw[rarity][last];
        return ZZZArtwork.item(rarity, entry);
    }

function notifyContribution(uint256 id) external onlyModule(Ids.VAULT) operating {
        _requireOwned(id);
        if (!traitsReady[id] || IZZZVault(msg.sender).sharesOf(id) == 0) revert NotReady();
        if (royaltyRewards.weightOf(id) == 0) royaltyRewards.activate(id, uint256(rarityOf[id]) + 1);
        emit MetadataUpdate(id);
    }

function royaltyInfo(uint256, uint256 salePrice) external view returns (address receiver, uint256 royaltyAmount) {
        return (address(royaltyRewards), Math.mulDiv(salePrice, 500, 10000));
    }

function supportsInterface(bytes4 interfaceId) public view override returns (bool) {
        return interfaceId == 0x2a55205a || interfaceId == 0x49064906 || super.supportsInterface(interfaceId);
    }

function currentLPValue(uint256 id) public view returns (bool available, uint256 valueUSD) {
        _requireOwned(id);
        if (royaltyRewards.weightOf(id) == 0) return (true, 0);
        try metadataRenderer.currentValue(id) returns (uint256 value) { return (true, value); }
        catch { return (false, 0); }
    }

function evolution(uint256 id) public view returns (bool available, uint8 stage) {
        uint256 value;
        (available, value) = currentLPValue(id);
        stage = _stage(id, value, royaltyRewards.weightOf(id));
    }

function _stage(uint256 id, uint256 value, uint256 weight) private view returns (uint8) {
        if (weight == 0) return 0;
        if (IZZZVault(access.module(Ids.VAULT)).nftStatus(id) == PositionStatus.Exited) return 4;
        return value >= 10000e18 ? 3 : value >= 1000e18 ? 2 : 1;
    }

function tokenURI(uint256 id) public view override returns (string memory) {
        (bool available, uint256 value) = currentLPValue(id);
        uint8 weight = uint8(royaltyRewards.weightOf(id));
        uint8 stage = _stage(id, value, weight);
        return metadataRenderer.render(NFTMetadataInput(id, rarityOf[id], paletteOf[id], patternOf[id], stage, traitsReady[id],
            available, value, weight, metadataBase));
    }

function refreshMetadataRange(uint256 firstOrdinal, uint256 lastOrdinal) external {
        if (firstOrdinal == 0 || firstOrdinal > lastOrdinal || lastOrdinal > mintedCount ||
            lastOrdinal - firstOrdinal >= MAX_METADATA_REFRESH_BATCH) revert InvalidAmount();
        for (uint256 ordinal = firstOrdinal; ordinal <= lastOrdinal; ++ordinal) {
            uint256 id = tokenAtOrdinal[ordinal];
            _requireOwned(id);
            emit MetadataUpdate(id);
        }
    }

function setBaseURI(string calldata baseURI) external onlyGovernance {
        if (access.isSealed() || metadataConfigured || bytes(baseURI).length == 0) revert InvalidConfiguration();
        _validateBaseURI(baseURI);
        metadataConfigured = true; metadataBase = baseURI;
        emit MetadataBaseChanged(baseURI);
        emit BatchMetadataUpdate(0, type(uint256).max);
    }

function _validateBaseURI(string memory baseURI) private pure {
        bytes memory value = bytes(baseURI);
        if (value.length == 0) return; // Unconfigured draft; production admission requires a reviewed CID.
        bool ipfs = value.length >= 7 && value[0] == "i" && value[1] == "p" && value[2] == "f" &&
            value[3] == "s" && value[4] == ":" && value[5] == "/" && value[6] == "/";
        bool arweave = value.length >= 5 && value[0] == "a" && value[1] == "r" &&
            value[2] == ":" && value[3] == "/" && value[4] == "/";
        if (!ipfs && !arweave) revert InvalidConfiguration();
    }

function _requestKey(uint256 epoch, uint256 requestId) private pure returns (bytes32) {
        return keccak256(abi.encode(epoch, requestId));
    }

function transferFrom(address from, address to, uint256 tokenId) public override canonicalAccounting {
        super.transferFrom(from, to, tokenId);
    }

function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data)
        public override canonicalAccounting {
        super.safeTransferFrom(from, to, tokenId, data);
    }

function _update(address to, uint256 tokenId, address auth) internal override returns (address) {
        uint8 state = IZZZCanonicalAccess(address(access)).canonicalState();
        if (state != 0 && !(state == 2 && canonicalImporting && msg.sender == canonicalModule())) revert InvalidState();
        return super._update(to, tokenId, auth);
    }

modifier onlyCanonicalWriter() {
        if (msg.sender != canonicalModule() || !access.isSealed() || access.canonicalState() != 2) revert Unauthorized();
        _;
    }

function canonicalRandomness(uint256 id) external view returns (uint256,uint256,uint256,bool,bool) {
        RandomnessResult storage result = randomness[_requestKey(requestEpochOf[id], requestOf[id])];
        return (result.nftId,result.rarityWord,result.colorWord,result.requested,result.fulfilled);
    }

function canonicalWriteHeader(uint256 count, uint256 next, uint256 remaining, uint16[3] calldata quotas, uint256 epoch)
        external onlyCanonicalWriter {
        mintedCount = count; nextToFinalize = next; remainingToReveal = remaining;
        rarityRemaining = quotas; randomnessEpoch = epoch;
    }

function canonicalWriteRecord(uint256 row, CanonicalNFTRecord calldata value) external onlyCanonicalWriter {
        bytes32 key = _requestKey(value.requestEpoch, value.requestId);
        if (randomness[key].requested) revert InvalidState();
        randomness[key] = RandomnessResult(value.id, value.rarityWord, value.colorWord, true, true);
        requestOf[value.id] = value.requestId; requestEpochOf[value.id] = value.requestEpoch;
        mintOrdinalOf[value.id] = row; tokenAtOrdinal[row] = value.id;
        rarityOf[value.id] = value.rarity; colorOf[value.id] = value.color;
        paletteOf[value.id] = value.palette; patternOf[value.id] = value.pattern; traitsReady[value.id] = true;
        canonicalImporting = true; _mint(value.owner, value.id); canonicalImporting = false;
    }

function canonicalWriteArtwork(uint8 rarity, uint256 item, uint16 value) external onlyCanonicalWriter {
        artworkDraw[rarity][item] = value;
    }

function canonicalSuccessor() external view returns (address controller, address replacementNFT) {
        if (access.canonicalState() != 3) return (address(0), address(0));
        controller = IZZZNFTSuccessor(access.canonicalHandoff()).destinationController();
        replacementNFT = IZZZAccess(controller).module(Ids.NFT);
    }

function canonicalRetire() external onlyHandoff {
        if (access.canonicalState() != 3) revert InvalidState();
        emit BatchMetadataUpdate(0, type(uint256).max);
    }

constructor(address controller, address collection) ZZZModule(controller) {
        if (collection.code.length == 0 || IZZZNFTCanonicalState(collection).access() != controller) revert InvalidConfiguration();
        nft = IZZZNFTCanonicalState(collection);
    }

function canonicalCapture() external onlyHandoff {
        uint256 count = nft.mintedCount();
        if (nft.nextToFinalize() != count + 1 || nft.remainingToReveal() != 1000 - count ||
            uint256(nft.rarityRemaining(0)) + nft.rarityRemaining(1) + nft.rarityRemaining(2) != nft.remainingToReveal()) revert InvalidState();
    }

function canonicalExport(uint256 row) external view returns (bytes memory) {
        if ((access.canonicalState() != 1 && access.canonicalState() != 3) || row >= canonicalCount()) revert InvalidState();
        if (row == 0) {
            uint16[3] memory quotas = [nft.rarityRemaining(0), nft.rarityRemaining(1), nft.rarityRemaining(2)];
            return abi.encode(CanonicalNFTHeader(nft.mintedCount(),nft.nextToFinalize(),nft.remainingToReveal(),
                quotas,nft.randomnessEpoch(),nft.artworkBaseURI()));
        }
        uint256 count = nft.mintedCount();
        if (row <= count) {
            uint256 id = nft.tokenAtOrdinal(row);
            (uint256 actualId,uint256 rarityWord,uint256 colorWord,bool requested,bool fulfilled) = nft.canonicalRandomness(id);
            if (!nft.traitsReady(id) || !requested || !fulfilled || actualId != id) revert InvalidState();
            return abi.encode(CanonicalNFTRecord(id,nft.ownerOf(id),nft.rarityOf(id),nft.colorOf(id),nft.paletteOf(id),
                nft.patternOf(id),nft.requestOf(id),nft.requestEpochOf(id),rarityWord,colorWord));
        }
        (uint8 rarity, uint256 item) = _inventoryRow(row - count - 1);
        return abi.encode(rarity,item,nft.canonicalArtwork(rarity,item));
    }

function canonicalImport(uint256 row, bytes calldata record) external onlyHandoff {
        if (access.canonicalState() != 2 || row != cursor++) revert InvalidState();
        if (row == 0) {
            if (nft.mintedCount() != 0) revert InvalidState();
            CanonicalNFTHeader memory header = abi.decode(record,(CanonicalNFTHeader));
            if (header.count > 1000 || header.next != header.count + 1 || header.remaining != 1000 - header.count ||
                uint256(header.quotas[0]) + header.quotas[1] + header.quotas[2] != header.remaining ||
                header.quotas[0] > 600 || header.quotas[1] > 300 || header.quotas[2] > 100 ||
                keccak256(bytes(header.base)) != keccak256(bytes(nft.artworkBaseURI()))) revert InvalidState();
            nft.canonicalWriteHeader(header.count,header.next,header.remaining,header.quotas,header.epoch + 1);
            return;
        }
        if (row >= canonicalCount()) revert InvalidState();
        uint256 count = nft.mintedCount();
        if (row <= count) {
            CanonicalNFTRecord memory value = abi.decode(record,(CanonicalNFTRecord));
            if (value.owner == address(0) || value.rarity > 2 || value.palette >= 58 || value.pattern >= 4 ||
                value.color != ZZZArtwork.primaryColor(value.palette) || value.requestId == 0 ||
                value.requestEpoch >= nft.randomnessEpoch()) revert InvalidState();
            nft.canonicalWriteRecord(row,value); return;
        }
        (uint8 rarity,uint256 item,uint16 value) = abi.decode(record,(uint8,uint256,uint16));
        (uint8 expectedRarity,uint256 expectedItem) = _inventoryRow(row - count - 1);
        uint256 limit = rarity == 0 ? 600 : rarity == 1 ? 300 : 100;
        if (rarity != expectedRarity || item != expectedItem || value > limit) revert InvalidState();
        nft.canonicalWriteArtwork(rarity,item,value);
    }

function _inventoryRow(uint256 row) private pure returns (uint8 rarity, uint256 item) {
        if (row < 600) return (0,row);
        if (row < 900) return (1,row - 600);
        return (2,row - 900);
    }

function canonicalValidate() external view {
        if (access.canonicalState() == 2 && cursor != canonicalCount()) revert InvalidState();
    }

function canonicalActivate() external onlyHandoff {
        if (access.canonicalState() != 2) revert InvalidState();
    }

function currentValue(uint256 id) external view returns (uint256 valueUSD) {
        IZZZVault vault = IZZZVault(access.module(Ids.VAULT));
        uint256 bucket = vault.nftBucket(id);
        uint256 shares = vault.sharesOf(id); uint256 supply = vault.bucketTotalShares(bucket);
        Position memory position = vault.group(bucket);
        if (bucket != 0 && shares != 0 && supply >= shares && position.status == PositionStatus.Exited) return 0;
        if (bucket == 0 || shares == 0 || supply < shares || position.status != PositionStatus.Active ||
            position.lpTokenId == 0) revert ValuationUnavailable();
        PoolConfig memory config = IZZZPools(access.module(Ids.POOLS)).accounting(position.poolId);
        // Mark actual concentrated-liquidity amounts only when their spot price
        // agrees with fresh oracle prices. Disabled operations do not invalidate
        // an otherwise honest mark; this view never changes rights or custody.
        IZZZStrategy(access.module(Ids.STRATEGY)).validateExitPrice(position.poolId);
        (uint256 a0, uint256 a1) = IZZZLiquidity(access.module(Ids.LIQUIDITY)).amounts(position.lpTokenId);
        IZZZFees fees = IZZZFees(access.module(Ids.FEES));
        a0 += position.idle0 + fees.compoundBalance(bucket, config.key.currency0);
        a1 += position.idle1 + fees.compoundBalance(bucket, config.key.currency1);
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        uint256 nav = oracle.value(config.key.currency0, a0) + oracle.value(config.key.currency1, a1);
        nav += IHistoricalCompound(address(IPairVault(address(vault)).migrationBudget())).historicalCompoundValue(bucket);
        return Math.mulDiv(nav, shares, supply);
    }

function render(NFTMetadataInput calldata input) external pure returns (string memory) {
        string memory rarity = input.traitsReady ? _rarity(input.rarity) : "Unrevealed";
        string memory state = input.valuationAvailable ? _stage(input.stage) : "Valuation unavailable";
        string memory image;
        if (input.traitsReady) {
            // Activated art is labelled as fallback, never a fabricated Dormant
            // state, when current marked LP valuation cannot be established.
            image = string.concat(input.baseURI, _palette(input.palette, true), "-", _patternFile(input.pattern), "-",
                _rarityFile(input.rarity), "-", _stageFile(input.valuationAvailable ? input.stage : 1), ".svg");
        } else {
            image = string.concat("data:image/svg+xml;base64,", Base64.encode(bytes(
                '<svg xmlns="http://www.w3.org/2000/svg" width="640" height="800"><rect width="640" height="800" fill="#030a1d"/><ellipse cx="320" cy="365" rx="150" ry="210" fill="#08142a" stroke="#46637a"/><text x="320" y="680" fill="#aac7d8" text-anchor="middle" font-size="20">Awaiting verifiable randomness</text></svg>')));
        }
        string memory description = input.stage == 4 ?
            "LP exited. Returned principal entitlement, unclaimed rewards and future royalty rights follow this NFT." :
            !input.traitsReady ? "Dormant NFT. Verifiable rarity, palette and circuit reveal pending." :
            input.valuationAvailable ? "Permanent LP fee rights follow this NFT. Rarity weights only NFT-sale royalties." :
            "Current LP valuation unavailable. Activated artwork is a fallback; royalty eligibility and fee rights remain.";
        bytes memory json = abi.encodePacked('{"name":"PoPL #', Strings.toString(input.id),
            '","description":"', description, '","image":"', Strings.escapeJSON(image),
            '","valuation_available":', input.valuationAvailable ? "true" : "false",
            ',"lp_exited":', input.stage == 4 ? "true" : "false",
            ',"royalty_activated":', input.royaltyWeight != 0 ? "true" : "false",
            ',"lp_value_usd_18":', input.valuationAvailable ? string.concat('"', Strings.toString(input.valueUSD), '"') : "null",
            ',"attributes":[{"trait_type":"Rarity","value":"', rarity,
            '"}', _visualAttributes(input), ',{"trait_type":"Evolution","value":"', state,
            '"},{"trait_type":"NFT-sale royalty weight","value":',
            input.traitsReady ? Strings.toString(uint256(input.rarity) + 1) : '"Unrevealed"', '}]}');
        return string.concat("data:application/json;base64,", Base64.encode(json));
    }

function _rarity(uint8 value) private pure returns (string memory) {
        return value == 0 ? "Commun" : value == 1 ? "Rare" : "Legendary";
    }

function _rarityFile(uint8 value) private pure returns (string memory) {
        return value == 0 ? "commun" : value == 1 ? "rare" : "legendary";
    }

function _color(uint8 value) private pure returns (string memory) {
        string[8] memory labels = ["Cyan", "Blue", "Violet", "Emerald", "Amber", "Crimson", "Ivory", "Onyx"];
        return labels[value];
    }

function _colorFile(uint8 value) private pure returns (string memory) {
        string[8] memory labels = ["cyan", "blue", "violet", "emerald", "amber", "crimson", "ivory", "onyx"];
        return labels[value];
    }

function _palette(uint8 value, bool filename) private pure returns (string memory label) {
        uint8 colors = ZZZArtwork.mask(value);
        for (uint8 i; i < 8; ++i) {
            if ((colors & (uint8(1) << i)) != 0) {
                string memory part = filename ? _colorFile(i) : _color(i);
                label = bytes(label).length == 0 ? part : string.concat(label, filename ? "-" : " / ", part);
            }
        }
    }

function _visualAttributes(NFTMetadataInput calldata input) private pure returns (bytes memory attributes) {
        if (!input.traitsReady) return abi.encodePacked(
            ',{"trait_type":"Color style","value":"Unrevealed"}',
            ',{"trait_type":"Palette","value":"Unrevealed"}',
            ',{"trait_type":"Circuit pattern","value":"Unrevealed"}');
        string memory style = input.palette < 8 ? "Monochrome" : input.palette < 30 ? "Bicolor" : "Tricolor";
        attributes = abi.encodePacked(',{"trait_type":"Color style","value":"', style,
            '"},{"trait_type":"Palette","value":"', _palette(input.palette, false), '"}');
        uint8 colors = ZZZArtwork.mask(input.palette); uint256 number;
        for (uint8 i; i < 8; ++i) {
            if ((colors & (uint8(1) << i)) != 0) {
                attributes = abi.encodePacked(attributes, ',{"trait_type":"Color ', Strings.toString(++number),
                    '","value":"', _color(i), '"}');
            }
        }
        return abi.encodePacked(attributes, ',{"trait_type":"Circuit pattern","value":"', _pattern(input.pattern), '"}');
    }

function _pattern(uint8 value) private pure returns (string memory) {
        string[4] memory labels = ["Flowing arcs", "Segmented panels", "Orbital rings", "Twin circuit routes"];
        return labels[value];
    }

function _patternFile(uint8 value) private pure returns (string memory) {
        string[4] memory labels = ["arcs", "panels", "orbits", "ribs"];
        return labels[value];
    }

function _stage(uint8 value) private pure returns (string memory) {
        if (value == 4) return "LP exited";
        string[4] memory labels = ["Dormant", "Activated", "Enhanced", "Singularity"];
        return labels[value];
    }

function _stageFile(uint8 value) private pure returns (string memory) {
        if (value == 4) return "activated";
        string[4] memory labels = ["dormant", "activated", "enhanced", "singularity"];
        return labels[value];
    }

constructor(address controller, address sequencer) ZZZModule(controller) {
        contributionPricing = new ZZZContributionPricing(controller,address(this));
        if (sequencer != address(0)) {
            bytes32 codeHash = sequencer.codehash;
            _sequencerData(sequencer, codeHash);
            // A deployment admission reference is provenance, not an independent
            // review. Production qualification must separately review this pin.
            bytes32 admissionReference = keccak256(abi.encode("ZZZ_SEQUENCER_BOOTSTRAP_V1", sequencer, codeHash));
            _recordSequencer(SequencerPolicy(sequencer, codeHash, admissionReference, true));
        }
    }

function setSequencerFeed(address source, bytes32 expectedCodeHash, bytes32 reviewHash)
        external onlyGovernance returns (bytes32 id) {
        if (source == address(0) || reviewHash == bytes32(0)) revert InvalidConfiguration();
        _sequencerData(source, expectedCodeHash);
        return _recordSequencer(SequencerPolicy(source, expectedCodeHash, reviewHash, false));
    }

function _recordSequencer(SequencerPolicy memory entry) private returns (bytes32 id) {
        bytes32 previous = activeSequencerPolicy;
        id = keccak256(abi.encode(address(this), sequencerHistory.length, entry));
        sequencerPolicies[id] = entry;
        sequencerHistory.push(id);
        activeSequencerPolicy = id;
        sequencerFeed = entry.source;
        emit SequencerPolicyRecorded(id, entry.source, entry.expectedCodeHash, entry.reviewHash,
            entry.bootstrapAdmission);
        emit SequencerPolicyActivated(previous, id);
    }

function _sequencerData(address source, bytes32 expectedCodeHash) private view
        returns (int256 answer, uint256 startedAt) {
        if (source.code.length == 0 || expectedCodeHash == bytes32(0) || source.codehash != expectedCodeHash ||
            _decimals(source, source) != 0) revert InvalidConfiguration();
        uint256 round; uint256 answeredRound; uint256 updated;
        (round, answer, startedAt, updated, answeredRound) = abi.decode(
            _boundedRead(source, IPriceFeed.latestRoundData.selector, 160, source),
            (uint256, int256, uint256, uint256, uint256));
        if (round == 0 || round > type(uint80).max || answeredRound > type(uint80).max ||
            answeredRound < round || (answer != 0 && answer != 1) || startedAt == 0 ||
            startedAt > block.timestamp || updated < startedAt || updated > block.timestamp) revert InvalidPrice(source);
        // Uptime feeds report status transitions, not periodic price rounds. A
        // healthy unchanged status must not expire based on updatedAt age.
    }

function setDualFeed(address token, SourcePolicy calldata primary, SourcePolicy calldata secondary,
        uint16 maxDeviationBps, bytes32 reviewHash) external onlyGovernance returns (bytes32 id) {
        if (reviewHash == bytes32(0) || maxDeviationBps > MAX_DEVIATION_BPS ||
            primary.source == secondary.source || primary.independenceId == bytes32(0) ||
            primary.independenceId == secondary.independenceId || secondary.independenceId == bytes32(0)) {
            revert InvalidConfiguration();
        }
        uint8 assetDecimals = token == address(0) ? 18 : _decimals(token, token);
        if (assetDecimals > 18) revert InvalidConfiguration();
        DualPolicy memory next = DualPolicy(token, primary, secondary, maxDeviationBps, assetDecimals, reviewHash);
        // Reject an invalid current observation at admission too. Static source
        // calls cannot mutate the policy or its authority during these checks.
        // _round also validates each source policy: do not repeat those calls.
        _readBounds(next);
        bytes32 previous = activePolicy[token];
        id = keccak256(abi.encode(address(this), history.length, next));
        policies[id] = next;
        history.push(id);
        activePolicy[token] = id;
        emit DualPolicyRecorded(id, token, primary.source, secondary.source, primary.independenceId,
            secondary.independenceId, maxDeviationBps, reviewHash);
        emit DualPolicyActivated(token, previous, id);
    }

function _boundedRead(address source, bytes4 selector, uint256 expectedLength, address token)
        private view returns (bytes memory result) {
        bool success;
        uint256 returned;
        uint256 gasLimit = SOURCE_CALL_GAS;
        // Copy only the exact bounded ABI result. A source cannot make the
        // caller allocate arbitrary returndata or disclose its revert payload.
        assembly ("memory-safe") {
            let input := mload(0x40)
            mstore(input, selector)
            success := staticcall(gasLimit, source, input, 4, 0, 0)
            returned := returndatasize()
        }
        if (!success || returned != expectedLength) revert InvalidPrice(token);
        result = new bytes(expectedLength);
        assembly ("memory-safe") { returndatacopy(add(result, 32), 0, expectedLength) }
    }

function _decimals(address source, address token) private view returns (uint8 digits) {
        if (source.code.length == 0) revert InvalidConfiguration();
        uint256 decoded = abi.decode(_boundedRead(source, IPriceFeed.decimals.selector, 32, token), (uint256));
        if (decoded > 18) revert InvalidConfiguration();
        digits = uint8(decoded);
    }

function _validateSource(SourcePolicy memory source, address token) private view {
        if (source.source.code.length == 0 || source.expectedCodeHash == bytes32(0) ||
            source.source.codehash != source.expectedCodeHash || source.maxAge == 0 || source.maxAge > 1 days ||
            source.feedDecimals > 18 || _decimals(source.source, token) != source.feedDecimals) {
            revert InvalidConfiguration();
        }
    }

function _round(SourcePolicy memory source, address token) private view returns (Round memory r, uint256 usd) {
        _validateSource(source, token);
        bytes memory encoded = _boundedRead(source.source, IPriceFeed.latestRoundData.selector, 160, token);
        // Decode wide words first so noncanonical narrow integers produce the
        // same bounded domain error as other malformed source responses.
        (uint256 round, int256 answer, uint256 started, uint256 updated, uint256 answered) =
            abi.decode(encoded, (uint256, int256, uint256, uint256, uint256));
        if (round == 0 || round > type(uint80).max || answered > type(uint80).max || answered < round ||
            answer <= 0 || started == 0 || started > updated || updated == 0 || updated > block.timestamp ||
            block.timestamp - updated > source.maxAge) revert InvalidPrice(token);
        uint256 scale = 10 ** (18 - source.feedDecimals);
        if (uint256(answer) > 1e36 / scale) revert InvalidPrice(token);
        usd = uint256(answer) * scale;
        r = Round(uint80(round), answer, started, updated, uint80(answered));
    }

function _readBounds(DualPolicy memory p)
        private view returns (uint256 lower, uint256 upper, Round memory first, Round memory second) {
        uint256 a;
        uint256 b;
        (first, a) = _round(p.primary, p.token);
        (second, b) = _round(p.secondary, p.token);
        lower = Math.min(a, b);
        upper = Math.max(a, b);
        // The denominator is the lower price. Rounding cannot admit a spread
        // one raw unit above the configured tolerance.
        if (upper - lower > Math.mulDiv(lower, p.maxDeviationBps, 10000)) revert InvalidPrice(p.token);
    }

function _sequencerCheck() private view {
        if (sequencerFeed == address(0)) return;
        SequencerPolicy memory entry = sequencerPolicies[activeSequencerPolicy];
        (int256 answer, uint256 startedAt) = _sequencerData(sequencerFeed, entry.expectedCodeHash);
        if (answer != 0 || block.timestamp - startedAt <= SEQUENCER_GRACE) revert InvalidPrice(sequencerFeed);
    }

function priceBounds(address token) public view returns (uint256 lower, uint256 upper, bytes32 fingerprint) {
        _sequencerCheck();
        bytes32 id = activePolicy[token];
        if (id == bytes32(0)) revert InvalidPrice(token);
        DualPolicy memory p = policies[id];
        if (token != address(0) && _decimals(token, token) != p.assetDecimals) revert InvalidConfiguration();
        Round memory first;
        Round memory second;
        (lower, upper, first, second) = _readBounds(p);
        fingerprint = keccak256(abi.encode(FINGERPRINT_DOMAIN, block.chainid, address(this), id,
            activeSequencerPolicy, first, second));
    }

function price(address token) public view returns (uint256 normalizedUSD) {
        (normalizedUSD,,) = priceBounds(token);
    }

function tokenDecimals(address token) public view returns (uint8) {
        bytes32 id = activePolicy[token];
        if (id == bytes32(0)) revert InvalidPrice(token);
        return policies[id].assetDecimals;
    }

function value(address token, uint256 amount) public view returns (uint256) {
        return Math.mulDiv(amount, price(token), 10 ** tokenDecimals(token));
    }

function quote(address input, address output, uint256 amount) external view returns (uint256) {
        (, uint256 upper,) = priceBounds(input);
        if (input == output) return amount;
        (uint256 lower,,) = priceBounds(output);
        uint256 sourceUSD = Math.mulDiv(amount, upper, 10 ** tokenDecimals(input));
        return Math.mulDiv(sourceUSD, 10 ** tokenDecimals(output), lower);
    }

function referenceX96(address token0, address token1) external view returns (uint160) {
        return ZZZPriceMath.referenceX96(price(token0),price(token1),
            tokenDecimals(token0),tokenDecimals(token1),token0);
    }

constructor(address controller) ZZZModule(controller) {
        activationAssets = ZZZActivationAssets(ZZZActivationAssetsFactory(access.activationAssetsFactory()).create());
        activationEntry = new ZZZActivationEntry(controller, address(this), address(activationAssets));
    }

function configureNative(PoolConfig calldata config) external onlyGovernance principalOperating returns (bytes32 poolId) {
        PoolKey memory key = config.key;
        if (key.currency0 != address(0) || key.currency1 != ZZZ || key.hooks != address(0) || key.fee > 100000 ||
            activationAssets.zzz() != ZZZ) {
            revert InvalidConfiguration();
        }
        _nativeBindings();
        poolId = keccak256(abi.encode(key));
        // Core protocol fees can change independently of the immutable static LP fee.
        // Swaps enforce actual net output; a fee-policy change must not freeze custody.
        (uint160 price,,, uint24 lpFee) = IStateViewMinimal(STATE).getSlot0(poolId);
        if (price == 0 || lpFee != key.fee) revert InvalidConfiguration();
        return _configure(config, address(0), ZZZ);
    }

function disablePool(bytes32 poolId, bool disableDeposits, bool disableOperations) external onlyGovernance {
        if (!exists[poolId] || (!disableDeposits && !disableOperations)) revert InvalidConfiguration();
        PoolConfig storage config = pools[poolId];
        if (disableDeposits) {
            config.depositsEnabled = false;
            if (contributionPool == poolId) _setContributionPool(bytes32(0));
        }
        if (disableOperations) config.operationsEnabled = false;
        ++configurationRevision;
        emit PoolDisabled(poolId, config.depositsEnabled, config.operationsEnabled);
    }

function applyKeeperRange(bytes32 poolId,uint16 width) external onlyModule(Ids.STRATEGY) {
        // The fixed controller's moduleAuthorized already enforces sealed and
        // canonical-operating identity. All remaining calls are static and all
        // writes below are local: there is no callback requiring a second read.
        if (access.paused()) revert Paused();
        if (access.preparationActive()) revert Preparing();
        if (access.lpExitStarted()) revert LPExitLocked();
        PoolConfig storage c = pools[poolId];
        if (!exists[poolId] || !c.operationsEnabled || (width != 2500 && width != 5000) ||
            c.triggerBps >= width || c.maxSpotDeviationBps >= width) revert InvalidConfiguration();
        c.rangeBps = width; // Strategy emits the successful old/new width and review hash.
        ++configurationRevision;
    }

function _configure(PoolConfig calldata config, address token0, address token1) internal returns (bytes32 poolId) {
        PoolKey memory k = config.key;
        poolId = keccak256(abi.encode(k));
        if (poolId == bytes32(0) || (config.depositsEnabled && contributionPool != bytes32(0) &&
            contributionPool != poolId)) revert InvalidConfiguration();
        if (k.tickSpacing <= 0 || k.tickSpacing > 32767 || k.fee > 100000 ||
            config.rangeBps < 100 || config.rangeBps > 5000 || config.triggerBps < 100 ||
            config.triggerBps >= config.rangeBps || config.maxSpotDeviationBps == 0 ||
            config.maxSpotDeviationBps > 500 || config.maxSpotDeviationBps >= config.rangeBps || config.maxSlippageBps == 0 || config.maxSlippageBps > 1000 || k.fee >= uint24(config.maxSlippageBps) * 100 ||
            config.minRebalanceInterval < 600 || config.minRebalanceInterval > 7 days ||
            config.minDepositUSD == 0 || config.maxPositionUSD < config.minDepositUSD) revert InvalidConfiguration();
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        oracle.price(token0);
        oracle.price(token1);
        IZZZRewards rewards = IZZZRewards(access.module(Ids.REWARDS));
        if (!rewards.isAsset(token0) || !rewards.isAsset(token1)) revert InvalidConfiguration();
        activationAssets.admitPoolAsset(token0);
        activationAssets.admitPoolAsset(token1);
        pools[poolId] = config;
        exists[poolId] = true;
        if (config.depositsEnabled) _setContributionPool(poolId);
        else if (contributionPool == poolId) _setContributionPool(bytes32(0));
        ++configurationRevision;
        emit PoolConfigured(poolId, k.currency0, k.currency1);
    }

function _setContributionPool(bytes32 poolId) private {
        bytes32 previous = contributionPool;
        if (previous == poolId) return;
        contributionPool = poolId;
        emit ContributionPoolChanged(previous, poolId);
    }

function get(bytes32 poolId) external view returns (PoolConfig memory) {
        if (!exists[poolId]) revert InvalidConfiguration();
        return pools[poolId];
    }

function accounting(bytes32 poolId) public view returns (PoolConfig memory c) {
        if (!exists[poolId]) revert InvalidConfiguration();
        c = pools[poolId];
        if (c.key.currency0 == address(0)) {
            _nativeBindings();
        }
    }

function contributionValue(bytes32 poolId, uint256 amount0, uint256 amount1) external view returns (uint256) {
        if (msg.sender == access.module(Ids.VAULT)) {
            // Only the immutable child's actual fixed Vault call can carry an
            // original-source valuation. An armed mismatched context reverts.
            uint256 sourceUSD = activationEntry.sourceValue(poolId, amount0, amount1);
            if (sourceUSD != 0) return sourceUSD;
        }
        PoolConfig memory c = accounting(poolId);
        return activationAssets.value(c.key.currency0, amount0) + activationAssets.value(c.key.currency1, amount1);
    }

function isNativePool(bytes32 poolId) public view returns (bool) {
        if (!exists[poolId]) revert InvalidConfiguration();
        if (pools[poolId].key.currency0 != address(0)) return false;
        _nativeBindings();
        return true;
    }

function _nativeBindings() private view {
        if (block.chainid != 4663 ||
            CORE.codehash != 0xbd3881180b547f5fe817545743cfb4343e96b1bc6640dcd70c106b0066e95626 ||
            POSM.codehash != 0xc873e135dc9aaec88489cfbad146b4cb49d6a32e0d80326377784b7ba17670b2 ||
            STATE.codehash != 0x7d9c591e0956fd89d98feb4ffcfe8bf1f7a62bd485edd979fa21d104b49878a6 ||
            PERMIT2.codehash != 0x5208783f52488f7d3493e5e38311ab707c1d75457fe472a19b0b4d57d66a7fca ||
            ZZZ.codehash != 0x3d5ba33c3a94f655c16348011ff2c72f6ce8085239454ce4a6c4bf284e84a597) {
            revert InvalidConfiguration();
        }
        // Native settlement and custody do not call or rely on WETH, its
        // implementation, its admin, or the periphery's optional wrapper getter.
        address manager = access.module(Ids.LIQUIDITY);
        if (IZZZLiquidity(manager).positionManager() != POSM ||
            INativeVenueBindings(manager).poolManager() != CORE || INativeVenueBindings(manager).stateView() != STATE ||
            INativeVenueBindings(manager).permit2() != PERMIT2) {
            revert InvalidConfiguration();
        }
    }

constructor(address source, bytes32 codeHash, bytes32 id, int32 exponent,
        uint32 age, uint16 confidenceBps, bytes32 review) {
        if (source.code.length == 0 || codeHash == bytes32(0) || source.codehash != codeHash ||
            id == bytes32(0) || review == bytes32(0) || exponent < -18 || exponent > 0 ||
            age == 0 || age > 1 days || confidenceBps > MAX_CONFIDENCE_BPS) {
            revert InvalidConfiguration();
        }
        core = source;
        expectedCoreCodeHash = codeHash;
        feedId = id;
        expectedExponent = exponent;
        maxAge = age;
        maxConfidenceBps = confidenceBps;
        decimals = uint8(uint32(-exponent));
        reviewHash = review;
    }

function latestRoundData() external view returns
        (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound) {
        address source = core;
        if (source.codehash != expectedCoreCodeHash) revert InvalidObservation();
        bytes32 id = feedId;
        bytes4 selector = GET_PRICE_UNSAFE;
        bool success;
        uint256 returned;
        uint256 gasLimit = SOURCE_CALL_GAS;
        // Never allocate or copy an upstream's unbounded return/revert data.
        assembly ("memory-safe") {
            let input := mload(0x40)
            mstore(input, selector)
            mstore(add(input, 4), id)
            success := staticcall(gasLimit, source, input, 36, 0, 0)
            returned := returndatasize()
        }
        if (!success || returned != 128) revert InvalidObservation();
        bytes memory data = new bytes(128);
        assembly ("memory-safe") { returndatacopy(add(data, 32), 0, 128) }
        // Decode wide words first so malformed sign extension or high bits
        // produce a bounded domain error instead of being silently truncated.
        uint256 confidence;
        int256 exponent;
        (answer, confidence, exponent, updatedAt) = abi.decode(data, (int256, uint256, int256, uint256));
        if (answer <= 0 || answer > type(int64).max || confidence > type(uint64).max ||
            exponent != int256(expectedExponent) || updatedAt == 0 || updatedAt > type(uint80).max ||
            updatedAt > block.timestamp || block.timestamp - updatedAt > maxAge ||
            confidence * 10_000 > uint256(answer) * maxConfidenceBps) revert InvalidObservation();
        roundId = uint80(updatedAt);
        startedAt = updatedAt;
        answeredInRound = roundId;
    }

function configure(uint32 secondsRequired,uint32 maximumGap,bytes32 reviewed)
        external onlyGovernance operating principalOperating nonReentrant {
        if(secondsRequired < 60 || secondsRequired > MAX_DURATION || maximumGap > secondsRequired/2 ||
            reviewed == bytes32(0)) revert InvalidConfiguration();
        duration = secondsRequired; maxObservationGap = maximumGap; reviewHash = reviewed;
        ++policyRevision;
        emit ConfirmationConfigured(secondsRequired,maximumGap,policyRevision,reviewed);
    }

function setRequireReferenceExit(bool required,bytes32 reviewed)
        external onlyGovernance operating principalOperating nonReentrant {
        if(reviewed == bytes32(0)) revert InvalidConfiguration();
        if(required && IConfirmationStrategy(strategy).activeKeeperRangePolicies() != 0) revert InvalidConfiguration();
        requireReferenceExit = required;
        referenceReviewHash = reviewed;
        ++policyRevision;
        emit ReferenceExitConfigured(required,policyRevision,reviewed);
    }

function invalidatePolicy() external operating {
        if(msg.sender != strategy) revert Unauthorized();
        ++policyRevision;
        emit ConfirmationInvalidated(policyRevision);
    }

function condition(uint256 bucket) public view returns(uint8 side,bytes32 identity,bool manual) {
        return _condition(bucket,false);
    }

function _condition(uint256 bucket,bool pausedEmergency) private view returns(uint8 side,bytes32 identity,bool manual) {
        if(access.module(Ids.STRATEGY) != strategy || !access.isSealed() || (access.paused() && !pausedEmergency) ||
            access.preparationActive() || access.canonicalState() != 0 || access.lpExitStarted()) return(0,bytes32(0),false);
        IConfirmationStrategy policy = IConfirmationStrategy(strategy);
        if(!policy.needsRebalance(bucket)) return(0,bytes32(0),false);
        if(policy.rangeUpdatePending(bucket)) return(0,bytes32(0),true);
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(bucket);
        address registry = access.module(Ids.POOLS);
        PoolConfig memory c = IZZZPools(registry).accounting(p.poolId);
        address manager = access.module(Ids.LIQUIDITY);
        (int24 lower,int24 upper) = IZZZLiquidity(manager).ticks(p.lpTokenId);
        (,int24 tick,,) = IConfirmationLiquidity(manager).stateView().getSlot0(p.poolId);
        side = tick < lower ? 1 : tick >= upper ? 2 : 0;
        if(side == 0) revert InvalidState(); // Raw and current physical observations must agree.
        if(requireReferenceExit) {
            // Compare the identical physical boundaries in raw token1/token0
            // orientation. No inverted display price, rounded tick or target
            // range can turn disagreement into same-side confirmation.
            if(_referenceSide(c,lower,upper) != side) return(0,bytes32(0),false);
        }
        // Normal feed rounds and fresh token balances do not reset the window.
        // Policy IDs/revisions, physical LP identity and both boundaries do.
        bytes32 physical = keccak256(abi.encode(block.chainid,address(this),bucket,p.poolId,p.lpTokenId,
            p.lastRebalance,lower,upper,manager));
        identity = keccak256(abi.encode(physical,keccak256(abi.encode(c)),
            policy.rangeOrientation(p.poolId),_controlFingerprint(c)));
    }

function marketSides(uint256 bucket) external view returns(uint8 physical,uint8 referenceSide) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(bucket);
        if(p.lpTokenId == 0) revert InvalidState();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        address manager = access.module(Ids.LIQUIDITY);
        (int24 lower,int24 upper) = IZZZLiquidity(manager).ticks(p.lpTokenId);
        if(lower < TickMath.MIN_TICK || upper > TickMath.MAX_TICK || lower >= upper) revert InvalidState();
        (,int24 tick,,) = IConfirmationLiquidity(manager).stateView().getSlot0(p.poolId);
        physical = tick < lower ? 1 : tick >= upper ? 2 : 0;
        referenceSide = _referenceSide(c,lower,upper);
    }

function _referenceSide(PoolConfig memory c,int24 lower,int24 upper) private view returns(uint8) {
        uint160 price = IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0,c.key.currency1);
        if(price < TickMath.MIN_SQRT_PRICE || price >= TickMath.MAX_SQRT_PRICE) revert InvalidState();
        return price < TickMath.getSqrtPriceAtTick(lower) ? 1 : price >= TickMath.getSqrtPriceAtTick(upper) ? 2 : 0;
    }

function controlFingerprint(bytes32 poolId) external view returns(bytes32) {
        return _controlFingerprint(IZZZPools(access.module(Ids.POOLS)).accounting(poolId));
    }

function observationFingerprint(uint256 bucket,bytes32 poolId) external view returns(bytes32) {
        Observation memory o=observations[bucket];
        return keccak256(abi.encode(_controlFingerprint(IZZZPools(access.module(Ids.POOLS)).accounting(poolId)),
            o.identity,o.firstSeen,o.lastSeen,o.side));
    }

function _controlFingerprint(PoolConfig memory c) private view returns(bytes32) {
        if(c.key.currency0 != address(0) || c.key.currency1 == address(0)) revert InvalidConfiguration();
        address registry = access.module(Ids.POOLS);
        IConfirmationOracle oracle = IConfirmationOracle(access.module(Ids.ORACLE));
        bytes32 first = oracle.activePolicy(c.key.currency0);
        bytes32 second = oracle.activePolicy(c.key.currency1);
        if(first == bytes32(0) || second == bytes32(0)) revert InvalidState();
        bytes32 sources = keccak256(abi.encode(address(oracle),first,second,oracle.activeSequencerPolicy()));
        return keccak256(abi.encode(registry,IConfirmationRegistry(registry).configurationRevision(),sources,
            IConfirmationStrategy(strategy).executionQualityRevision(),policyRevision));
    }

function ready(uint256 bucket) external view returns(bool) {
        (uint8 side,bytes32 identity,bool manual) = condition(bucket);
        if(manual) return true;
        return _ready(observations[bucket],side,identity);
    }

function emergencyReady(uint256 bucket) external view returns(bool) {
        address budget = IZZZEmergencyVault(access.module(Ids.VAULT)).migrationBudget();
        if(msg.sender != budget || !access.paused()) revert Unauthorized();
        IZZZEmergencyBudget(budget).validateEmergency(bucket);
        (uint8 side,bytes32 identity,bool manual) = _condition(bucket,true);
        return manual || _ready(observations[bucket],side,identity);
    }

function _ready(Observation memory old,uint8 side,bytes32 identity) private view returns(bool) {
        return maxObservationGap != 0 && side != 0 && old.identity == identity && old.side == side &&
            old.firstSeen != 0 && old.firstSeen <= old.lastSeen && old.lastSeen <= block.timestamp &&
            block.timestamp-old.lastSeen <= maxObservationGap && block.timestamp-old.firstSeen >= duration;
    }

function resetObservation(uint256 bucket) external onlyKeeper operating principalOperating nonReentrant {
        delete observations[bucket];
        emit ObservationReset(bucket,5);
    }

function observe(uint256 bucket) external onlyKeeper live operating principalOperating nonReentrant returns(bool) {
        try this.condition(bucket) returns(uint8 side,bytes32 identity,bool manual) {
            if(manual || side == 0 || maxObservationGap == 0) {
                delete observations[bucket];
                emit ObservationReset(bucket,manual ? 4 : side == 0 ? 1 : 3);
                return manual;
            }
            if(block.timestamp == 0 || block.timestamp > type(uint64).max) revert InvalidState();
            Observation memory old = observations[bucket];
            bool restart = old.identity != identity || old.side != side || old.lastSeen > block.timestamp ||
                old.firstSeen == 0 || block.timestamp-old.lastSeen > maxObservationGap;
            Observation memory next = Observation(identity,restart ? uint64(block.timestamp) : old.firstSeen,
                uint64(block.timestamp),side);
            observations[bucket] = next;
            emit Observed(bucket,side,identity,next.firstSeen,next.lastSeen);
            return _ready(next,side,identity);
        } catch {
            delete observations[bucket];
            emit ObservationReset(bucket,2);
            return false;
        }
    }

constructor(address controller) ZZZModule(controller) {
        // Native fees use the same indices as token fees. Already converted
        // credits remain individual balances and never enter those indices again.
        assets.push(address(0)); isAsset[address(0)] = true; emit AssetAdded(address(0));
    }

function bindConverter(address candidate) external onlyGovernance nonReentrant economic {
        if (access.isSealed() || converter != address(0) || candidate.code.length == 0 ||
            ZZZLPRewardConverter(payable(candidate)).ledger() != address(this) ||
            address(ZZZLPRewardConverter(payable(candidate)).access()) != address(access)) revert InvalidConfiguration();
        converter = candidate; emit ConverterBound(candidate);
    }

function addAsset(address token) external onlyGovernance {
        if (token.code.length == 0 || isAsset[token] || assets.length == MAX_ASSETS) revert InvalidConfiguration();
        isAsset[token] = true;
        assets.push(token);
        emit AssetAdded(token);
    }

function _checkpoint(uint256 id, address token) private {
        _checkpoint(id, token, IZZZMembership(access.module(Ids.MEMBERSHIP)).eligible(id) ? 1 : 0);
    }

function _checkpoint(uint256 id, address token, uint256 weight) private {
        uint256 delta = index[token] - paidIndex[id][token];
        if (delta != 0 && weight != 0) {
            uint256 whole = Math.mulDiv(weight, delta, SCALE);
            uint256 remainder = mulmod(weight, delta, SCALE) + fraction[id][token];
            collective[id][token] += whole + remainder / SCALE;
            fraction[id][token] = remainder % SCALE;
        }
        paidIndex[id][token] = index[token];
    }

function checkpointAll(uint256 id) external onlyModule(Ids.MEMBERSHIP) economic {
        // Only static dependency reads and ledger writes occur in this loop.
        // One eligibility snapshot therefore applies to every admitted asset.
        uint256 weight = IZZZMembership(access.module(Ids.MEMBERSHIP)).eligible(id) ? 1 : 0;
        for (uint256 i; i < assets.length; ++i) _checkpoint(id, assets[i], weight);
    }

function _checkpointOwner(uint256 id, address token) private {
        IZZZVault vault = IZZZVault(access.module(Ids.VAULT));
        _checkpointOwner(id, token, vault.nftBucket(id), vault.sharesOf(id));
    }

function _checkpointOwner(uint256 id, address token, uint256 bucket, uint256 shares) private {
        uint256 current = ownerIndex[bucket][token];
        uint256 delta = current - paidOwnerIndex[id][token];
        if (delta != 0 && shares != 0) {
            uint256 whole = Math.mulDiv(shares, delta, SCALE);
            uint256 remainder = mulmod(shares, delta, SCALE) + ownerFraction[id][token];
            individual[id][token] += whole + remainder / SCALE;
            ownerFraction[id][token] = remainder % SCALE;
        }
        paidOwnerIndex[id][token] = current;
    }

function checkpointOwner(uint256 id) external onlyModule(Ids.VAULT) economic {
        IZZZVault vault = IZZZVault(access.module(Ids.VAULT));
        uint256 bucket = vault.nftBucket(id);
        uint256 shares = vault.sharesOf(id);
        // No external mutable call can change the bucket or shares while the
        // per-asset checkpoints settle against this pre-contribution snapshot.
        for (uint256 i; i < assets.length; ++i) _checkpointOwner(id, assets[i], bucket, shares);
    }

function creditPool(uint256 bucketId, address token, uint256 personal, uint256 shared)
        external payable onlyModule(Ids.FEES) nonReentrant economic {
        _creditPool(bucketId, token, personal, shared, false);
    }

function creditCanonicalCutoff(uint256 bucketId, address token, uint256 personal, uint256 shared)
        external payable nonReentrant {
        if (msg.sender != access.module(Ids.FEES) || _state() != 1 || !canonicalCaptured ||
            !IZZZCanonicalAccess(address(access)).canonicalSettling()) revert CanonicalState();
        _creditPool(bucketId, token, personal, shared, true);
        if (_state() != 1 || !IZZZCanonicalAccess(address(access)).canonicalSettling()) revert CanonicalState();
    }

function _creditPool(uint256 bucketId, address token, uint256 personal, uint256 shared, bool cutoff) private {
        if (!isAsset[token] || personal + shared == 0) revert InvalidAmount();
        uint256 supply = IZZZVault(access.module(Ids.VAULT)).bucketTotalShares(bucketId);
        if (supply == 0) revert InvalidState();
        if (token == address(0)) {
            if (msg.value != personal + shared) revert InvalidAmount();
        } else {
            if (msg.value != 0) revert InvalidAmount();
            ExactToken.pull(token, msg.sender, personal + shared);
        }
        if (cutoff) {
            for (uint256 i; i < canonicalAssets.length; ++i) {
                if (canonicalAssets[i] == token) { canonicalAmounts[i] += personal + shared; break; }
            }
        }
        ownerIndex[bucketId][token] += Math.mulDiv(personal, SCALE, supply);
        uint256 weight = IZZZMembership(access.module(Ids.MEMBERSHIP)).totalEligible();
        if (weight == 0) {
            // Never give pre-participation revenue to a future entrant.
            orphaned[token] += shared;
            liabilities[token] += personal;
        } else {
            index[token] += Math.mulDiv(shared, SCALE, weight);
            liabilities[token] += personal + shared;
        }
        if (_canonicalBalance(token) < liabilities[token] + orphaned[token]) revert InvalidState();
        emit PoolRewardsCredited(bucketId, token, personal, shared);
    }

function claim(uint256 id, address token) external nonReentrant economic returns (uint256 amount) {
        return _claim(id, token, msg.sender);
    }

function claimFor(uint256 id, address token, address owner) external nonReentrant economic returns (uint256 amount) {
        if (msg.sender != IZZZNFT(access.module(Ids.NFT)).claimRouter()) revert Unauthorized();
        return _claim(id, token, owner);
    }

function _claim(uint256 id, address token, address owner) private returns (uint256 amount) {
        // Claims are NOT paused when strategy operations are paused.
        if (!access.isSealed() || IZZZNFT(access.module(Ids.NFT)).ownerOf(id) != owner) revert Unauthorized();
        if (!isAsset[token]) revert InvalidConfiguration();
        _checkpoint(id, token);
        _checkpointOwner(id, token);
        amount = individual[id][token] + collective[id][token];
        individual[id][token] = 0;
        collective[id][token] = 0;
        liabilities[token] -= amount;
        if (token == address(0)) {
            if (amount != 0) { (bool ok,) = owner.call{value: amount}(""); if (!ok) revert InvalidState(); }
        } else ExactToken.push(token, owner, amount);
        emit Claimed(id, token, owner, amount);
    }

function claimable(uint256 id, address token) external view returns (uint256) {
        if (_reentrancyGuardEntered()) revert InvalidState();
        uint256 weight = IZZZMembership(access.module(Ids.MEMBERSHIP)).eligible(id) ? 1 : 0;
        uint256 delta = index[token] - paidIndex[id][token];
        IZZZVault vault = IZZZVault(access.module(Ids.VAULT));
        uint256 shares = vault.sharesOf(id);
        uint256 ownerDelta = ownerIndex[vault.nftBucket(id)][token] - paidOwnerIndex[id][token];
        return individual[id][token] + collective[id][token] + Math.mulDiv(weight, delta, SCALE)
            + (mulmod(weight, delta, SCALE) + fraction[id][token]) / SCALE
            + Math.mulDiv(shares, ownerDelta, SCALE)
            + (mulmod(shares, ownerDelta, SCALE) + ownerFraction[id][token]) / SCALE;
    }

function convertBatch(address token, uint256[] calldata ids, bytes32 routeId, uint256 minimumETH, uint256 deadline)
        external onlyKeeper live operating nonReentrant economic returns (uint256 output) {
        if (access.module(Ids.REWARDS) != address(this) || converter == address(0) || token == address(0) ||
            !isAsset[token] || ids.length == 0 || ids.length > MAX_CONVERSION_NFTS) revert InvalidConfiguration();
        uint256[] memory personal = new uint256[](ids.length);
        uint256[] memory shared = new uint256[](ids.length);
        uint256 total;
        for (uint256 i; i < ids.length; ++i) {
            if ((i != 0 && ids[i] <= ids[i-1]) || IZZZNFT(access.module(Ids.NFT)).ownerOf(ids[i]) == address(0))
                revert InvalidConfiguration();
            _checkpoint(ids[i], token); _checkpointOwner(ids[i], token);
            personal[i] = individual[ids[i]][token]; shared[i] = collective[ids[i]][token];
            total += personal[i] + shared[i];
            individual[ids[i]][token] = 0; collective[ids[i]][token] = 0;
        }
        if (total == 0) revert InvalidAmount();
        uint256 sourceBefore = IERC20(token).balanceOf(address(this));
        uint256 nativeBefore = address(this).balance;
        liabilities[token] -= total;
        IERC20(token).forceApprove(converter, total);
        output = ZZZLPRewardConverter(payable(converter)).convert(token,total,routeId,minimumETH,deadline);
        IERC20(token).forceApprove(converter, 0);
        if (IERC20(token).balanceOf(address(this)) != sourceBefore - total ||
            address(this).balance != nativeBefore + output) revert InvalidState();
        liabilities[address(0)] += output;
        uint256 cumulative; uint256 assigned;
        for (uint256 i; i < ids.length; ++i) {
            // Cumulative rounding conserves every output wei across both
            // components and the same NFTs; no current-membership redistribution.
            cumulative += personal[i];
            uint256 next = Math.mulDiv(output,cumulative,total);
            uint256 ownETH = next - assigned; assigned = next;
            cumulative += shared[i]; next = Math.mulDiv(output,cumulative,total);
            uint256 sharedETH = next - assigned; assigned = next;
            individual[ids[i]][address(0)] += ownETH; collective[ids[i]][address(0)] += sharedETH;
            emit LPRewardsConverted(ids[i],token,personal[i],shared[i],ownETH,sharedETH);
        }
        if (!access.keeperAuthorized(msg.sender) || access.paused()) revert Unauthorized();
    }

function canonicalCapture() external canonicalOnly {
        _canonicalBeginCapture();
        canonicalNFTs = IZZZRewardNFTOrdinals(access.module(Ids.NFT)).mintedCount();
        canonicalBuckets = IZZZVault(access.module(Ids.VAULT)).bucketCount();
        canonicalAssetTotal = assets.length;
        for (uint256 i; i < assets.length; ++i) {
            address token = assets[i];
            uint256 amount = _canonicalBalance(token);
            if (amount < liabilities[token] + orphaned[token]) revert CanonicalState();
            _canonicalAdd(token, amount, 0);
        }
    }

function canonicalCount() public view returns (uint256) {
        return 1 + canonicalAssetTotal * (1 + canonicalBuckets + canonicalNFTs);
    }

function canonicalExport(uint256 row) external view returns (bytes memory) {
        if ((_state() != 1 && _state() != 3) || row >= canonicalCount()) revert CanonicalState();
        if (row == 0) return abi.encode(canonicalAssetTotal, canonicalBuckets, canonicalNFTs);
        --row;
        if (row < canonicalAssetTotal) {
            address token = assets[row];
            return abi.encode(token, index[token], liabilities[token], orphaned[token], canonicalAmounts[row]);
        }
        row -= canonicalAssetTotal;
        address asset = assets[row % canonicalAssetTotal];
        uint256 ordinal = row / canonicalAssetTotal;
        if (ordinal < canonicalBuckets) {
            uint256 bucket = IZZZVault(access.module(Ids.VAULT)).bucketAt(ordinal);
            return abi.encode(bucket, asset, ownerIndex[bucket][asset]);
        }
        uint256 id = IZZZRewardNFTOrdinals(access.module(Ids.NFT)).tokenAtOrdinal(ordinal - canonicalBuckets + 1);
        return abi.encode(id, asset, individual[id][asset], collective[id][asset], paidIndex[id][asset],
            fraction[id][asset], paidOwnerIndex[id][asset], ownerFraction[id][asset]);
    }

function canonicalImport(uint256 row, bytes calldata record) external canonicalOnly {
        _canonicalNext(row);
        if (row == 0) {
            (canonicalAssetTotal, canonicalBuckets, canonicalNFTs) = abi.decode(record, (uint256,uint256,uint256));
            if (canonicalAssetTotal == 0 || canonicalAssetTotal > MAX_ASSETS || canonicalBuckets > 4 || canonicalNFTs > 1000 ||
                (assets.length != 1 && assets.length != canonicalAssetTotal)) revert CanonicalState();
            return;
        }
        if (row >= canonicalCount()) revert CanonicalState();
        --row;
        if (row < canonicalAssetTotal) {
            (address token, uint256 ix, uint256 liability, uint256 orphan, uint256 backing) =
                abi.decode(record, (address,uint256,uint256,uint256,uint256));
            if ((row == 0 ? token != address(0) : token == address(0) || token.code.length == 0) ||
                liabilities[token] != 0 || orphaned[token] != 0 || index[token] != 0 ||
                backing < liability + orphan) revert CanonicalState();
            if (assets.length == row) { if (isAsset[token]) revert CanonicalState(); assets.push(token); isAsset[token] = true; }
            if (assets[row] != token) revert CanonicalState();
            _canonicalAdd(token, backing, _canonicalBalance(token));
            index[token] = ix; liabilities[token] = liability; orphaned[token] = orphan;
            return;
        }
        row -= canonicalAssetTotal;
        address expected = assets[row % canonicalAssetTotal];
        uint256 ordinal = row / canonicalAssetTotal;
        if (ordinal < canonicalBuckets) {
            (uint256 bucket, address token, uint256 ix) = abi.decode(record, (uint256,address,uint256));
            if (token != expected ||
                bucket != IZZZVault(access.module(Ids.VAULT)).bucketAt(ordinal)) revert CanonicalState();
            ownerIndex[bucket][token] = ix; return;
        }
        (uint256 id, address asset, uint256 personal, uint256 shared, uint256 paid, uint256 frac,
            uint256 ownerPaid, uint256 ownerFrac) = abi.decode(record,(uint256,address,uint256,uint256,uint256,uint256,uint256,uint256));
        if (asset != expected || id != IZZZRewardNFTOrdinals(access.module(Ids.NFT)).tokenAtOrdinal(ordinal - canonicalBuckets + 1) ||
            frac >= SCALE || ownerFrac >= SCALE || paid > index[asset] ||
            ownerPaid > ownerIndex[IZZZVault(access.module(Ids.VAULT)).nftBucket(id)][asset]) revert CanonicalState();
        individual[id][asset] = personal; collective[id][asset] = shared; paidIndex[id][asset] = paid;
        fraction[id][asset] = frac; paidOwnerIndex[id][asset] = ownerPaid; ownerFraction[id][asset] = ownerFrac;
    }

function canonicalValidate() external view {
        if (_state() == 2 && canonicalCursor != canonicalCount()) revert CanonicalState();
        _canonicalValidateBacking();
    }

function create() external returns (ZZZRoyaltyRewards receiver) {
        receiver = new ZZZRoyaltyRewards(msg.sender);
        receiver.bindCanonicalController(controller);
    }

constructor(address nftController) {
        // The NFT may deploy this receiver from its own constructor.
        if (nftController == address(0)) revert InvalidConfiguration();
        nft = nftController;
        creator = msg.sender;
        isAsset[address(0)] = true;
        assets.push(address(0));
        accounted[address(0)] = address(this).balance;
        orphaned[address(0)] = address(this).balance;
        emit AssetAdded(address(0), address(this).balance);
    }

function bindCanonicalController(address controller) external {
        if (msg.sender != creator || canonicalController != address(0) || controller.code.length == 0) revert Unauthorized();
        canonicalController = controller;
    }

modifier onlyNFT() {
        if (msg.sender != nft) revert Unauthorized();
        _;
    }

function bindConverter(address candidate) external nonReentrant economic {
        IZZZAccess control = IZZZAccess(canonicalController);
        if (!control.canConfigure(msg.sender) || control.isSealed() || converter != address(0) ||
            candidate.code.length == 0 || IZZZRoyaltyConverter(candidate).ledger() != address(this) ||
            address(IZZZRoyaltyConverter(candidate).access()) != canonicalController) revert Unauthorized();
        converter = candidate;
        emit ConverterBound(candidate);
    }

function convertBatch(address asset, uint256[] calldata ids, bytes32 routeId, uint256 minimumETH, uint256 deadline)
        external nonReentrant economic returns (uint256 output) {
        IZZZAccess control = IZZZAccess(canonicalController);
        if (!control.keeperAuthorized(msg.sender) || !control.isSealed() || control.paused() ||
            control.preparationActive() || control.module(Ids.NFT) != nft || converter == address(0)) revert Unauthorized();
        if (asset == address(0) || !isAsset[asset] || ids.length == 0 || ids.length > MAX_CONVERSION_NFTS) revert InvalidConfiguration();
        _sync(address(0)); _sync(asset);
        uint256[] memory amounts = new uint256[](ids.length);
        uint256 total;
        for (uint256 i; i < ids.length; ++i) {
            if ((i != 0 && ids[i] <= ids[i - 1]) || weightOf[ids[i]] == 0) revert InvalidConfiguration();
            _checkpoint(ids[i], asset);
            amounts[i] = accrued[ids[i]][asset]; total += amounts[i];
            accrued[ids[i]][asset] = 0;
        }
        if (total == 0) revert InvalidConfiguration();
        accounted[asset] -= total; liabilities[asset] -= total;
        uint256 beforeSource = _canonicalBalance(asset);
        uint256 beforeNative = address(this).balance;
        IERC20(asset).forceApprove(converter, total);
        output = IZZZRoyaltyConverter(converter).convert(asset, total, routeId, minimumETH, deadline);
        IERC20(asset).forceApprove(converter, 0);
        if (output == 0 || _canonicalBalance(asset) + total != beforeSource ||
            address(this).balance != beforeNative + output) revert InvalidState();
        accounted[address(0)] += output; liabilities[address(0)] += output;
        uint256 cumulative; uint256 assigned;
        for (uint256 i; i < ids.length; ++i) {
            cumulative += amounts[i];
            uint256 next = Math.mulDiv(output, cumulative, total);
            uint256 part = next - assigned; assigned = next;
            accrued[ids[i]][address(0)] += part;
            emit RoyaltyConverted(ids[i], asset, amounts[i], part);
        }
        // Cumulative rounding allocates every received wei; source fractions and
        // global division dust remain backed in the original currency.
        if (!control.keeperAuthorized(msg.sender) || control.paused() || control.preparationActive()) revert Unauthorized();
    }

function addAsset(address token) external onlyNFT nonReentrant economic {
        if (token == address(0) || token.code.length == 0 || isAsset[token] || assets.length == MAX_ASSETS) {
            revert InvalidConfiguration();
        }
        uint256 balance = IERC20(token).balanceOf(address(this));
        isAsset[token] = true;
        assets.push(token);
        accounted[token] = balance;
        orphaned[token] = balance;
        eligibleCount[token] = activationCount; eligibleWeight[token] = totalWeight;
        emit AssetAdded(token, balance);
    }

function activate(uint256 id, uint256 weight) external onlyNFT nonReentrant economic {
        if (weight == 0 || weight > 3 || weightOf[id] != 0) revert InvalidConfiguration();
        if (IZZZRoyaltyNFTOwner(nft).ownerOf(id) == address(0)) revert InvalidState();
        if (activationCount == 1000) revert InvalidConfiguration();
        uint256 successful;
        for (uint256 i; i < assets.length; ++i) {
            address asset = assets[i];
            bool ok = true;
            if (asset == address(0)) _sync(asset);
            else {
                // Reserve enough gas for the complete isolated call and tail.
                // Caller underfunding cannot deliberately defer a healthy read.
                if (gasleft() < ACTIVATION_SYNC_GAS + 120_000) revert InvalidState();
                bytes memory data = abi.encodeCall(this.syncForActivation, (asset));
                uint256 budget = ACTIVATION_SYNC_GAS;
                assembly ("memory-safe") { ok := call(budget, address(), 0, add(data, 32), mload(data), 0, 0) }
            }
            if (ok) { _checkpoint(id, asset); successful |= uint256(1) << i; }
            else emit RoyaltyAssetDeferred(id, asset);
        }
        weightOf[id] = weight;
        totalWeight += weight;
        activationOrdinal[id] = ++activationCount;
        for (uint256 i; i < assets.length; ++i) if ((successful & (uint256(1) << i)) != 0) {
            eligibleCount[assets[i]] = activationCount; eligibleWeight[assets[i]] = totalWeight;
        }
        emit Activated(id, weight);
    }

function syncForActivation(address asset) external {
        if (msg.sender != address(this)) revert Unauthorized();
        _sync(asset);
    }

function eligibleFor(uint256 id, address asset) public view returns (bool) {
        return isAsset[asset] && activationOrdinal[id] != 0 && activationOrdinal[id] <= eligibleCount[asset];
    }

function _enrollWaiting(address asset) private {
        uint256 old = eligibleCount[asset];
        if (old == activationCount) return;
        deferredJoins[asset].push(Join(old + 1, activationCount, index[asset]));
        eligibleCount[asset] = activationCount; eligibleWeight[asset] = totalWeight;
        emit RoyaltyEligibilityRecovered(asset, old + 1, activationCount);
    }

function _paid(uint256 id, address asset) private view returns (uint256 paid) {
        paid = paidIndex[id][asset];
        uint256 ordinal = activationOrdinal[id];
        Join[] storage joins = deferredJoins[asset];
        uint256 low; uint256 high = joins.length;
        while (low < high) { uint256 mid = (low + high) / 2;
            if (joins[mid].last < ordinal) low = mid + 1; else high = mid;
        }
        if (low < joins.length && ordinal >= joins[low].first) paid = Math.max(paid, joins[low].baseline);
    }

function pending(address asset) external view returns (uint256) {
        if (_reentrancyGuardEntered()) revert InvalidState();
        if (!isAsset[asset]) revert InvalidConfiguration();
        uint256 balance = _canonicalBalance(asset);
        if (balance < accounted[asset]) revert InvalidState();
        return balance - accounted[asset];
    }

function _sync(address asset) private returns (uint256 amount) {
        uint256 balance = _canonicalBalance(asset);
        if (balance < accounted[asset]) revert InvalidState();
        amount = balance - accounted[asset];
        if (amount == 0) { _enrollWaiting(asset); return 0; }
        accounted[asset] = balance;
        uint256 supply = eligibleWeight[asset];
        if (supply == 0) {
            orphaned[asset] += amount;
        } else {
            index[asset] += Math.mulDiv(amount, SCALE, supply);
            liabilities[asset] += amount;
        }
        emit RoyaltiesReceived(asset, amount, supply != 0);
        _enrollWaiting(asset);
    }

function sync(address asset) external nonReentrant economic returns (uint256 amount) {
        if (!isAsset[asset]) revert InvalidConfiguration();
        return _sync(asset);
    }

function syncAll() external nonReentrant economic {
        for (uint256 i; i < assets.length; ++i) _sync(assets[i]);
    }

function fund(address asset, uint256 amount) external nonReentrant economic {
        if (asset == address(0) || !isAsset[asset] || amount == 0) revert InvalidConfiguration();
        _sync(asset);
        ExactToken.pull(asset, msg.sender, amount);
        _sync(asset);
    }

function _checkpoint(uint256 id, address asset) private {
        uint256 delta = index[asset] - _paid(id, asset);
        uint256 weight = eligibleFor(id, asset) ? weightOf[id] : 0;
        if (delta != 0 && weight != 0) {
            uint256 remainder = mulmod(weight, delta, SCALE) + fraction[id][asset];
            accrued[id][asset] += Math.mulDiv(weight, delta, SCALE) + remainder / SCALE;
            fraction[id][asset] = remainder % SCALE;
        }
        paidIndex[id][asset] = index[asset];
    }

function claim(uint256 id, address asset) external nonReentrant economic returns (uint256 amount) {
        return _claim(id, asset, msg.sender);
    }

function claimFor(uint256 id, address asset, address owner) external nonReentrant economic returns (uint256 amount) {
        if (msg.sender != IZZZRoyaltyNFTOwner(nft).claimRouter()) revert Unauthorized();
        return _claim(id, asset, owner);
    }

function _claim(uint256 id, address asset, address owner) private returns (uint256 amount) {
        if (IZZZRoyaltyNFTOwner(nft).ownerOf(id) != owner) revert Unauthorized();
        if (!isAsset[asset]) revert InvalidConfiguration();
        _sync(asset);
        _checkpoint(id, asset);
        amount = accrued[id][asset];
        accrued[id][asset] = 0;
        liabilities[asset] -= amount;
        accounted[asset] -= amount;
        if (asset == address(0)) {
            if (amount != 0) {
                (bool success,) = payable(owner).call{value: amount}("");
                if (!success) revert NativeTransferFailed();
            }
        } else {
            ExactToken.push(asset, owner, amount);
        }
        // A receiver can return native ETH during its callback; that new inbox
        // payment remains pending. Existing backing must never decrease further.
        if (_canonicalBalance(asset) < accounted[asset]) revert InvalidState();
        emit Claimed(id, asset, owner, amount);
    }

function claimable(uint256 id, address asset) external view returns (uint256) {
        // External consumers must not value an intermediate conversion/payment
        // balance during a token, router or recipient callback.
        if (_reentrancyGuardEntered()) revert InvalidState();
        if (!isAsset[asset]) revert InvalidConfiguration();
        uint256 balance = _canonicalBalance(asset);
        if (balance < accounted[asset]) revert InvalidState();
        uint256 currentIndex = index[asset];
        if (!eligibleFor(id, asset)) return accrued[id][asset];
        uint256 supply = eligibleWeight[asset];
        if (supply != 0 && _state() == 0) currentIndex += Math.mulDiv(balance - accounted[asset], SCALE, supply);
        uint256 delta = currentIndex - _paid(id, asset);
        uint256 weight = weightOf[id];
        return accrued[id][asset] + Math.mulDiv(weight, delta, SCALE)
            + (mulmod(weight, delta, SCALE) + fraction[id][asset]) / SCALE;
    }

function canonicalCapture() external canonicalOnly {
        _canonicalBeginCapture();
        delete canonicalPending;
        canonicalCutoffSettled = false;
        canonicalNFTs = IZZZRoyaltyOrdinals(nft).mintedCount();
        canonicalAssetTotal = assets.length;
        canonicalWeight = totalWeight;
        for (uint256 i; i < assets.length; ++i) {
            address asset = assets[i];
            uint256 balance = _canonicalBalance(asset);
            if (balance < accounted[asset]) revert CanonicalState();
            canonicalPending.push(balance - accounted[asset]);
            _canonicalAdd(asset, balance, 0);
        }
    }

function canonicalSettle() external canonicalOnly {
        if (_state() != 1 || canonicalCutoffSettled) revert CanonicalState();
        canonicalCutoffSettled = true;
        for (uint256 i; i < assets.length; ++i) {
            address asset = assets[i]; uint256 amount = canonicalPending[i];
            accounted[asset] += amount;
            uint256 supply = eligibleWeight[asset];
            if (supply == 0) orphaned[asset] += amount;
            else { index[asset] += Math.mulDiv(amount, SCALE, supply); liabilities[asset] += amount; }
            _enrollWaiting(asset);
            emit RoyaltiesReceived(asset, amount, supply != 0);
        }
    }

function canonicalCount() public view returns (uint256) {
        return 1 + canonicalAssetTotal + canonicalNFTs * (1 + canonicalAssetTotal);
    }

function canonicalExport(uint256 row) external view returns (bytes memory) {
        if ((_state() != 1 && _state() != 3) || !canonicalCutoffSettled || row >= canonicalCount()) revert CanonicalState();
        if (row == 0) return abi.encode(canonicalAssetTotal, canonicalNFTs, totalWeight);
        --row;
        if (row < canonicalAssetTotal) {
            address asset = assets[row];
            return abi.encode(asset, index[asset], accounted[asset], liabilities[asset], orphaned[asset], canonicalAmounts[row]);
        }
        row -= canonicalAssetTotal;
        uint256 id = IZZZRoyaltyOrdinals(nft).tokenAtOrdinal(row / (1 + canonicalAssetTotal) + 1);
        uint256 subrow = row % (1 + canonicalAssetTotal);
        if (subrow == 0) return abi.encode(id, weightOf[id]);
        address token = assets[subrow - 1];
        // Flatten deferred-join baselines into the existing portable row format.
        return abi.encode(id, token, accrued[id][token], _paid(id, token), fraction[id][token]);
    }

function canonicalImport(uint256 row, bytes calldata record) external canonicalOnly {
        _canonicalNext(row);
        if (row == 0) {
            if (totalWeight != 0) revert CanonicalState();
            (canonicalAssetTotal, canonicalNFTs, canonicalWeight) = abi.decode(record, (uint256,uint256,uint256));
            if (canonicalAssetTotal == 0 || canonicalAssetTotal > MAX_ASSETS || canonicalNFTs > 1000 ||
                canonicalWeight > 3 * canonicalNFTs || (assets.length != 1 && assets.length != canonicalAssetTotal)) revert CanonicalState();
            return;
        }
        if (row >= canonicalCount()) revert CanonicalState();
        --row;
        if (row < canonicalAssetTotal) {
            (address asset,uint256 ix,uint256 acc,uint256 liability,uint256 orphan,uint256 backing) =
                abi.decode(record,(address,uint256,uint256,uint256,uint256,uint256));
            if ((row == 0) != (asset == address(0)) || (asset != address(0) && asset.code.length == 0) ||
                liabilities[asset] != 0 || index[asset] != 0 || acc != liability + orphan || backing != acc) revert CanonicalState();
            if (assets.length == row) { if (isAsset[asset]) revert CanonicalState(); assets.push(asset); isAsset[asset] = true; }
            if (assets[row] != asset) revert CanonicalState();
            uint256 prefund = _canonicalBalance(asset);
            _canonicalAdd(asset, backing, prefund);
            index[asset] = ix; liabilities[asset] = liability;
            accounted[asset] = acc + prefund; orphaned[asset] = orphan + prefund;
            return;
        }
        row -= canonicalAssetTotal;
        uint256 expected = IZZZRoyaltyOrdinals(nft).tokenAtOrdinal(row / (1 + canonicalAssetTotal) + 1);
        uint256 subrow = row % (1 + canonicalAssetTotal);
        if (subrow == 0) {
            (uint256 id,uint256 weight) = abi.decode(record,(uint256,uint256));
            if (id != expected || weightOf[id] != 0 || weight > 3 ||
                (weight != 0 && weight != uint256(IZZZRoyaltyOrdinals(nft).rarityOf(id)) + 1)) revert CanonicalState();
            weightOf[id] = weight; totalWeight += weight;
            if (weight != 0) activationOrdinal[id] = ++activationCount;
            return;
        }
        (uint256 nftId,address token,uint256 amount,uint256 paid,uint256 frac) = abi.decode(record,(uint256,address,uint256,uint256,uint256));
        if (nftId != expected || token != assets[subrow - 1] || frac >= SCALE || paid > index[token]) revert CanonicalState();
        accrued[nftId][token] = amount; paidIndex[nftId][token] = paid; fraction[nftId][token] = frac;
    }

function canonicalValidate() external view {
        if (_state() == 2 && (canonicalCursor != canonicalCount() || totalWeight != canonicalWeight)) revert CanonicalState();
        _canonicalValidateBacking();
    }

function canonicalActivate() external override canonicalOnly {
        if (_state() != 2) revert CanonicalState();
        for (uint256 i; i < assets.length; ++i) {
            address asset = assets[i];
            uint256 extra = _canonicalBalance(asset) - accounted[asset];
            accounted[asset] += extra; orphaned[asset] += extra; canonicalPrefunds[i] += extra;
            eligibleCount[asset] = activationCount; eligibleWeight[asset] = totalWeight;
        }
    }

function forwardLate(address asset) external nonReentrant returns (uint256 amount) {
        if (_state() != 3 || !isAsset[asset]) revert CanonicalState();
        address handoff = IZZZCanonicalAccess(canonicalController).canonicalHandoff();
        address destination = IZZZRoyaltySuccessor(handoff).destinationController();
        address receiver = IZZZRoyaltyOrdinals(IZZZAccess(destination).module(Ids.NFT)).royaltyRewards();
        if (receiver == address(0) || receiver == address(this)) revert CanonicalState();
        amount = _canonicalBalance(asset);
        if (asset == address(0)) {
            if (amount != 0) { (bool ok,) = payable(receiver).call{value: amount}(""); if (!ok) revert NativeTransferFailed(); }
        } else ExactToken.push(asset, receiver, amount);
        emit LateRoyaltiesForwarded(asset, receiver, amount);
    }

constructor(address controller) ZZZModule(controller) {
        rebalanceConfirmation = new ZZZRebalanceConfirmation(controller);
    }

function rebalanceObservation(uint256 id) external view returns(uint8 side,bytes32 identity,bool manual) {
        return rebalanceConfirmation.condition(id);
    }

function setAdditionalLossBps(uint16 limit,bytes32 reviewHash) external onlyGovernance operating {
        if (limit > MAX_ADDITIONAL_LOSS_BPS || reviewHash == bytes32(0)) revert InvalidConfiguration();
        uint16 previous = additionalLossBps;
        additionalLossBps = limit;
        ++executionQualityRevision;
        emit AdditionalLossLimitChanged(previous,limit,executionQualityRevision,reviewHash);
    }

function minimumOutput(bytes32 poolId,bool direction,uint256 amount) external view returns(uint256) {
        return _minimumOutput(poolId,direction,amount,true);
    }

function minimumOutputForExit(bytes32 poolId,bool direction,uint256 amount) external view returns(uint256) {
        return _minimumOutput(poolId,direction,amount,false);
    }

function _minimumOutput(bytes32 poolId,bool direction,uint256 amount,bool requireOperations) private view returns(uint256) {
        if (amount == 0 || amount > type(uint128).max) revert InvalidAmount();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (requireOperations && !c.operationsEnabled) revert InvalidState();
        PairPrices memory prices = _pairPrices(c);
        return _minimum(prices,direction,amount,c.maxSlippageBps,_swapFee(poolId,c,direction));
    }

function _swapFee(bytes32 poolId,PoolConfig memory c,bool direction) private view returns(uint256) {
        (,,uint24 protocol,uint24 fee) = IV4FeeState(access.module(Ids.LIQUIDITY)).stateView().getSlot0(poolId);
        if (c.key.hooks != address(0) || fee != c.key.fee || fee > 100000 ||
            (protocol & 0xfff) > 1000 || protocol >> 12 > 1000) revert InvalidConfiguration();
        uint256 selected = direction ? protocol & 0xfff : protocol >> 12;
        return selected+fee-Math.mulDiv(selected,fee,1_000_000);
    }

function _quoted(PairPrices memory prices,bool direction,uint256 amount) private pure returns(uint256) {
        AssetPrice memory input = direction ? prices.first : prices.second;
        AssetPrice memory output = direction ? prices.second : prices.first;
        return Math.mulDiv(Math.mulDiv(amount,input.upper,input.scale),output.scale,output.lower);
    }

function _minimum(PairPrices memory prices,bool direction,uint256 amount,uint16 grossLoss,uint256 fee)
        private view returns(uint256) {
        uint256 gross = Math.mulDiv(_quoted(prices,direction,amount),10000-grossLoss,10000);
        uint256 net = Math.mulDiv(amount,1_000_000-fee,1_000_000);
        return Math.max(gross,Math.mulDiv(_quoted(prices,direction,net),10000-additionalLossBps,10000,Math.Rounding.Ceil));
    }

function _floor(int24 tick, int24 spacing) private pure returns (int24) {
        int24 quotient = tick / spacing;
        if (tick < 0 && tick % spacing != 0) --quotient;
        return quotient * spacing;
    }

function target(bytes32 poolId) public view returns (int24 lower, int24 upper, uint160 referenceX96) {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (!c.operationsEnabled) revert InvalidState();
        referenceX96 = IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0, c.key.currency1);
        (lower, upper) = _range(c, referenceX96);
    }

function _range(PoolConfig memory c, uint160 referenceX96) private view returns (int24 lower, int24 upper) {
        uint256 below = Math.sqrt(uint256(10000 - c.rangeBps) * 1e28);
        uint256 above = Math.sqrt(uint256(10000 + c.rangeBps) * 1e28);
        bool inverse = rangeOrientation[keccak256(abi.encode(c.key))] == 1;
        uint256 lowerRoot = inverse ? Math.mulDiv(referenceX96,1e16,
            Math.sqrt(uint256(10000+c.rangeBps)*1e28,Math.Rounding.Ceil)) : Math.mulDiv(referenceX96,below,1e16);
        uint256 upperRoot = inverse ? Math.mulDiv(referenceX96,1e16,below,Math.Rounding.Ceil) : Math.mulDiv(referenceX96,above,1e16);
        if (lowerRoot <= TickMath.MIN_SQRT_PRICE || upperRoot >= TickMath.MAX_SQRT_PRICE) revert InvalidConfiguration();
        lower = _floor(TickMath.getTickAtSqrtPrice(uint160(lowerRoot)), c.key.tickSpacing);
        // Always round the upper limit outward, including an exact tick boundary.
        upper = _floor(TickMath.getTickAtSqrtPrice(uint160(upperRoot)), c.key.tickSpacing) + c.key.tickSpacing;
        if (lower < TickMath.MIN_TICK || upper > TickMath.MAX_TICK || lower >= upper) revert InvalidConfiguration();
    }

function setRangeOrientation(bytes32 poolId,uint8 orientation) external onlyGovernance operating {
        uint8 previous = rangeOrientation[poolId];
        if (orientation > 1 || previous == orientation) revert InvalidConfiguration();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        rangeOrientation[poolId] = orientation;
        _range(c,IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0,c.key.currency1));
        KeeperRangePolicy storage policy = keeperRangePolicy[poolId];
        if (policy.enabled) {
            policy.enabled = false;
            --activeKeeperRangePolicies;
            emit KeeperRangePolicyChanged(poolId,false,policy.configurationHash,policy.reviewHash);
        }
        rebalanceConfirmation.invalidatePolicy();
        emit RangeOrientationChanged(poolId,previous,orientation);
    }

function setKeeperRangePolicy(bytes32 poolId,bool enabled,uint16 narrowTriggerBps,uint16 widenTriggerBps,
        uint32 minInterval,bytes32 reviewHash) external onlyGovernance operating {
        if (poolId == bytes32(0)) revert InvalidConfiguration();
        KeeperRangePolicy storage policy = keeperRangePolicy[poolId];
        if (!enabled) {
            if(policy.enabled) --activeKeeperRangePolicies;
            policy.enabled = false;
            emit KeeperRangePolicyChanged(poolId,false,policy.configurationHash,policy.reviewHash);
            return;
        }
        // A keeper-selected width would otherwise use the deliberate-width
        // exception. It cannot silently bypass same-side reference protection.
        if(rebalanceConfirmation.requireReferenceExit()) revert InvalidConfiguration();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (rangeOrientation[poolId] != 1 || (c.rangeBps != 2500 && c.rangeBps != 5000) ||
            c.triggerBps >= 2500 || c.maxSpotDeviationBps >= 2500 || narrowTriggerBps >= widenTriggerBps ||
            widenTriggerBps >= 2500 || minInterval < 600 || minInterval < c.minRebalanceInterval ||
            minInterval > 7 days || reviewHash == bytes32(0)) revert InvalidConfiguration();
        _range(c,IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0,c.key.currency1));
        bytes32 fingerprint = _rangeConfiguration(c);
        if(!policy.enabled) ++activeKeeperRangePolicies;
        keeperRangePolicy[poolId] = KeeperRangePolicy(true,narrowTriggerBps,widenTriggerBps,minInterval,
            uint64(block.timestamp),fingerprint,reviewHash);
        emit KeeperRangePolicyChanged(poolId,true,fingerprint,reviewHash);
    }

function _rangeConfiguration(PoolConfig memory c) private view returns(bytes32 fingerprint) {
        uint16 width = c.rangeBps;
        c.rangeBps = 0;
        fingerprint = keccak256(abi.encode(c,rangeOrientation[keccak256(abi.encode(c.key))]));
        c.rangeBps = width;
    }

function _displacement(bytes32 poolId,uint160 center,uint160 referenceX96) private view returns(uint256) {
        uint256 root = rangeOrientation[poolId] == 1 ? Math.mulDiv(center,1e18,referenceX96) :
            Math.mulDiv(referenceX96,1e18,center);
        uint256 ratio = Math.mulDiv(root,root,1e18);
        return ratio > 1e18 ? ratio-1e18 : 1e18-ratio;
    }

function keeperRangeTarget(bytes32 poolId) public view returns(uint16 next) {
        KeeperRangePolicy memory policy = keeperRangePolicy[poolId];
        if (!policy.enabled || !access.isSealed() || access.paused() || access.preparationActive() ||
            access.canonicalState() != 0 || rangeOrientation[poolId] != 1 ||
            block.timestamp < uint256(policy.lastChange)+policy.minInterval) return 0;
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (!c.operationsEnabled || _rangeConfiguration(c) != policy.configurationHash ||
            (c.rangeBps != 2500 && c.rangeBps != 5000)) return 0;
        IZZZVault vault = IZZZVault(access.module(Ids.VAULT));
        uint256 bucket = vault.poolBucket(poolId);
        if (bucket == 0) return 0;
        Position memory p = vault.group(bucket);
        if (p.poolId != poolId || p.status != PositionStatus.Active || p.lpTokenId == 0 || p.centerX96 == 0 ||
            block.timestamp < uint256(p.lastRebalance)+c.minRebalanceInterval || _rangeUpdatePending(p,c)) return 0;
        uint160 ref = IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0,c.key.currency1);
        uint256 movement = _displacement(poolId,p.centerX96,ref);
        if (c.rangeBps == 2500 && movement >= uint256(policy.widenTriggerBps)*1e14) next = 5000;
        else if (c.rangeBps == 5000 && movement <= uint256(policy.narrowTriggerBps)*1e14) next = 2500;
        if (next != 0) { c.rangeBps = next; _range(c,ref); }
    }

function applyKeeperRange(bytes32 poolId) external onlyKeeper live operating principalOperating returns(uint16 next) {
        next = keeperRangeTarget(poolId);
        if (next == 0) revert InvalidState();
        uint16 previous = IZZZPools(access.module(Ids.POOLS)).get(poolId).rangeBps;
        keeperRangePolicy[poolId].lastChange = uint64(block.timestamp);
        IRangeRegistry(access.module(Ids.POOLS)).applyKeeperRange(poolId,next);
        emit KeeperRangeSelected(poolId,previous,next,keeperRangePolicy[poolId].reviewHash);
    }

function validatePrice(bytes32 poolId) public view returns (uint160 spotX96) {
        return _validatePrice(poolId, true);
    }

function validateExitPrice(bytes32 poolId) public view returns (uint160 spotX96) {
        return _validatePrice(poolId, false);
    }

function _validatePrice(bytes32 poolId, bool requireOperations) private view returns (uint160 spotX96) {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (requireOperations && !c.operationsEnabled) revert InvalidState();
        uint160 referenceX96 = IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0, c.key.currency1);
        return _checkedSpot(poolId, c, referenceX96);
    }

function _checkedSpot(bytes32 poolId, PoolConfig memory c, uint160 referenceX96) private view returns (uint160 spotX96) {
        spotX96 = IZZZLiquidity(access.module(Ids.LIQUIDITY)).spot(poolId);
        if (spotX96 == 0) revert InvalidState();
        uint256 relativeRoot = Math.mulDiv(spotX96, 1e18, referenceX96);
        uint256 relativePrice = Math.mulDiv(relativeRoot, relativeRoot, 1e18);
        uint256 difference = relativePrice > 1e18 ? relativePrice - 1e18 : 1e18 - relativePrice;
        if (difference > uint256(c.maxSpotDeviationBps) * 1e14) revert Slippage();
    }

function needsRebalance(uint256 id) external view returns (bool) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(id);
        if (p.status != PositionStatus.Active || p.centerX96 == 0 || p.lpTokenId == 0) return false;
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        if (!c.operationsEnabled || block.timestamp < p.lastRebalance + c.minRebalanceInterval) return false;
        uint160 ref = IZZZOracle(access.module(Ids.ORACLE)).referenceX96(c.key.currency0, c.key.currency1);
        _checkedSpot(p.poolId,c,ref);
        (int24 lower,int24 upper) = IZZZLiquidity(access.module(Ids.LIQUIDITY)).ticks(p.lpTokenId);
        if (lower < TickMath.MIN_TICK || upper > TickMath.MAX_TICK || lower >= upper) revert InvalidState();
        int24 tick = _checkedPoolTick(p.poolId,c);
        // A true range exit cannot bypass the governed minimum interval. A
        // deliberate width/orientation change may still apply while in range.
        return tick < lower || tick >= upper || _rangeUpdatePending(p,c);
    }

function _checkedPoolTick(bytes32 poolId,PoolConfig memory c) private view returns(int24 tick) {
        uint160 price; uint24 protocol; uint24 fee;
        (price,tick,protocol,fee) = IV4FeeState(access.module(Ids.LIQUIDITY)).stateView().getSlot0(poolId);
        if (price < TickMath.MIN_SQRT_PRICE || price >= TickMath.MAX_SQRT_PRICE ||
            tick < TickMath.MIN_TICK || tick >= TickMath.MAX_TICK || fee != c.key.fee ||
            (protocol & 0xfff) > 1000 || protocol >> 12 > 1000) revert InvalidState();
        if (price < TickMath.getSqrtPriceAtTick(tick) || price > TickMath.getSqrtPriceAtTick(tick+1)) revert InvalidState();
    }

function rangeUpdatePending(uint256 id) external view returns (bool) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(id);
        if (p.status != PositionStatus.Active || p.centerX96 == 0 || p.lpTokenId == 0) return false;
        return _rangeUpdatePending(p, IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId));
    }

function _rangeUpdatePending(Position memory p, PoolConfig memory c) private view returns (bool) {
        (int24 expectedLower, int24 expectedUpper) = _range(c, p.centerX96);
        (int24 lower, int24 upper) = IZZZLiquidity(access.module(Ids.LIQUIDITY)).ticks(p.lpTokenId);
        if (lower >= upper) revert InvalidState();
        return lower != expectedLower || upper != expectedUpper;
    }

function swapPlan(bytes32 poolId, uint256 amount0, uint256 amount1)
        external view returns (bool zeroForOne, uint256 amountIn, uint256 minimumOut) {
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(poolId);
        if (!c.operationsEnabled) revert InvalidState();
        PairPrices memory prices = _pairPrices(c);
        (int24 lower, int24 upper) = _range(c, prices.referenceX96);
        return _plan(poolId, c, prices, lower, upper, amount0, amount1);
    }

function compoundPlan(uint256 id, uint256 amount0, uint256 amount1)
        external view returns (bool, uint256, uint256) {
        Position memory p = IZZZVault(access.module(Ids.VAULT)).group(id);
        (int24 lower, int24 upper) = IZZZLiquidity(access.module(Ids.LIQUIDITY)).ticks(p.lpTokenId);
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        if (!c.operationsEnabled) revert InvalidState();
        return _plan(p.poolId, c, _pairPrices(c), lower, upper, amount0, amount1);
    }

function _pairPrices(PoolConfig memory c) private view returns (PairPrices memory p) {
        IZZZOracle oracle = IZZZOracle(access.module(Ids.ORACLE));
        (p.first.lower,p.first.upper,) = oracle.priceBounds(c.key.currency0);
        (p.second.lower,p.second.upper,) = oracle.priceBounds(c.key.currency1);
        uint8 d0 = oracle.tokenDecimals(c.key.currency0);
        uint8 d1 = oracle.tokenDecimals(c.key.currency1);
        p.first.scale = 10 ** d0; p.second.scale = 10 ** d1;
        p.referenceX96 = ZZZPriceMath.referenceX96(p.first.lower,p.second.lower,d0,d1,c.key.currency0);
    }

function _value(AssetPrice memory p, uint256 amount) private pure returns (uint256) {
        return Math.mulDiv(amount,p.lower,p.scale);
    }

function _plan(bytes32 poolId, PoolConfig memory c, PairPrices memory prices,
        int24 lower, int24 upper, uint256 amount0, uint256 amount1)
        private view returns (bool zeroForOne, uint256 amountIn, uint256 minimumOut) {
        uint160 spotX96 = _checkedSpot(poolId,c,prices.referenceX96);
        uint160 a = TickMath.getSqrtPriceAtTick(lower);
        uint160 b = TickMath.getSqrtPriceAtTick(upper);
        uint256 unit0;
        uint256 unit1;
        if (spotX96 <= a) unit0 = SqrtPriceMath.getAmount0Delta(a, b, uint128(1e18), false);
        else if (spotX96 >= b) unit1 = SqrtPriceMath.getAmount1Delta(a, b, uint128(1e18), false);
        else {
            unit0 = SqrtPriceMath.getAmount0Delta(spotX96, b, uint128(1e18), false);
            unit1 = SqrtPriceMath.getAmount1Delta(a, spotX96, uint128(1e18), false);
        }
        uint256 v0 = _value(prices.first, amount0);
        uint256 v1 = _value(prices.second, amount1);
        uint256 u0 = _value(prices.first, unit0);
        uint256 u1 = _value(prices.second, unit1);
        if (u0 + u1 == 0) revert InvalidAmount();
        uint256 desired0 = Math.mulDiv(v0 + v1, u0, u0 + u1);
        zeroForOne = v0 > desired0;
        AssetPrice memory input = zeroForOne ? prices.first : prices.second;
        uint256 excess = zeroForOne ? v0 - desired0 : desired0 - v0;
        uint256 fee = _swapFee(poolId,c,zeroForOne);
        {
            // Every admitted v4 pool is static, hookless and native ETH/fixed ZZZ.
            // Size the net pair after its actual directional protocol + LP fee.
            uint256 inputWeight = Math.mulDiv(zeroForOne ? u0 : u1, 1e18, u0 + u1);
            excess = Math.mulDiv(excess, 1e18, 1e18 - Math.mulDiv(inputWeight, fee, 1_000_000));
        }
        amountIn = Math.mulDiv(excess, input.scale, input.lower);
        if (amountIn > (zeroForOne ? amount0 : amount1)) revert InvalidState();
        // Preserve Oracle.quote's two floor operations exactly: upper-valued
        // source USD first, then lower-valued output raw units.
        minimumOut = _minimum(prices,zeroForOne,amountIn,c.maxSlippageBps,fee);
        if (minimumOut == 0) amountIn = 0;
    }

receive() external payable {
        if (msg.sender != nativeSender || nativeSender == address(0)) revert Unauthorized();
        nativeReceived += msg.value;
    }

function addRoute(Policy calldata policy) external onlyParent nonReentrant returns (bytes32 id) {
        _check(policy); id = _id(policy);
        if (routeExists[id]) revert InvalidConfiguration();
        policies[id] = policy; routeExists[id] = true; routeEnabled[id] = true;
        emit RouteRecorded(id, policy.source, policy.output, policy.reviewHash); emit RouteEnabled(id, true);
    }

function setRouteEnabled(bytes32 id, bool enabled) external onlyParent nonReentrant {
        if (!routeExists[id]) revert InvalidConfiguration();
        if (enabled) { if (_id(policies[id]) != id) revert InvalidConfiguration(); _check(policies[id]); }
        routeEnabled[id] = enabled; emit RouteEnabled(id, enabled);
    }

function route(bytes32 id) external view returns (Policy memory) {
        if (!routeExists[id]) revert InvalidConfiguration(); return policies[id];
    }

function _validated(bytes32 id) private view returns (Policy memory p) {
        if (!routeExists[id] || !routeEnabled[id]) revert InvalidConfiguration();
        p = policies[id];
        if (_id(p) != id) revert InvalidConfiguration();
        _check(p);
    }

function _id(Policy memory p) private view returns (bytes32) {
        return keccak256(abi.encode(ROUTE_DOMAIN, block.chainid, address(this), parent, p));
    }

function _pin(address target, bytes32 codeHash) private view {
        if (target == address(0) || codeHash == bytes32(0) || target.code.length == 0 || target.codehash != codeHash)
            revert InvalidConfiguration();
    }

function _asset(address asset, bytes32 codeHash) private view {
        if (asset == address(0)) { if (codeHash != NATIVE_ASSET_CODE_HASH) revert InvalidConfiguration(); }
        else _pin(asset, codeHash);
    }

function _check(Policy memory p) private view {
        PoolKey memory k = p.key;
        if (p.source == p.output || k.currency0 >= k.currency1 || k.hooks != address(0) ||
            k.fee >= 1000000 || k.tickSpacing < 1 || k.tickSpacing > 32767 || p.reviewHash == bytes32(0) ||
            !((p.source == k.currency0 && p.output == k.currency1) ||
                (p.source == k.currency1 && p.output == k.currency0))) revert InvalidConfiguration();
        _asset(p.source, p.sourceCodeHash); _asset(p.output, p.outputCodeHash);
        _pin(p.poolManager, p.poolManagerCodeHash); _pin(p.stateView, p.stateViewCodeHash);
        IStateViewMinimal view_ = IStateViewMinimal(p.stateView);
        if (view_.poolManager() != p.poolManager) revert InvalidConfiguration();
        (uint160 price,,, uint24 lpFee) = view_.getSlot0(keccak256(abi.encode(k)));
        if (price < TickMath.MIN_SQRT_PRICE || price >= TickMath.MAX_SQRT_PRICE || lpFee != k.fee)
            revert InvalidConfiguration();
    }

function execute(bytes32 id, uint256 amountIn, uint256 minimumOut, uint256 deadline)
        external payable onlyParent nonReentrant returns (uint256 amountOut) {
        if (deadline < block.timestamp || deadline > block.timestamp + 10 minutes) revert Expired();
        if (amountIn == 0 || amountIn > uint256(uint128(type(int128).max)) || minimumOut == 0 ||
            minimumOut > uint256(uint128(type(int128).max))) revert InvalidAmount();
        Policy memory p = _validated(id);
        if (msg.value != (p.source == address(0) ? amountIn : 0)) revert InvalidAmount();
        uint256 nativeBefore = address(this).balance - msg.value;
        uint256 sourceBefore = ExactAsset.balance(p.source, address(this)) - msg.value;
        uint256 outputBefore = ExactAsset.balance(p.output, address(this));
        if (p.source != address(0)) ExactToken.pull(p.source, parent, amountIn);
        // An ERC20 callback cannot inject ETH and disguise it as swap output,
        // or let prefunded ETH subsidize the exact declared native budget.
        if (address(this).balance != nativeBefore + msg.value) revert InvalidState();
        bytes memory payload = abi.encode(p.key, p.source, p.output, amountIn, minimumOut);
        pendingHash = keccak256(payload); pendingManager = p.poolManager;
        amountOut = abi.decode(IPoolManagerMinimal(p.poolManager).unlock(payload), (uint256));
        if (pendingHash != bytes32(0) || pendingManager != address(0) || nativeSender != address(0) ||
            nativeReceived != 0 || amountOut < minimumOut ||
            ExactAsset.balance(p.source, address(this)) != sourceBefore ||
            ExactAsset.balance(p.output, address(this)) != outputBefore + amountOut ||
            address(this).balance != nativeBefore + (p.output == address(0) ? amountOut : 0)) revert InvalidState();
        _check(p);
        uint256 parentBefore = ExactAsset.balance(p.output, parent);
        ExactAsset.push(p.output, parent, amountOut);
        if (ExactAsset.balance(p.source, address(this)) != sourceBefore ||
            ExactAsset.balance(p.output, address(this)) != outputBefore || address(this).balance != nativeBefore ||
            ExactAsset.balance(p.output, parent) != parentBefore + amountOut) revert InvalidState();
        _check(p);
        emit Executed(id, amountIn, amountOut);
    }

function unlockCallback(bytes calldata payload) external returns (bytes memory) {
        if (msg.sender != pendingManager || pendingHash == bytes32(0) || pendingHash != keccak256(payload))
            revert Unauthorized();
        pendingHash = bytes32(0); pendingManager = address(0);
        (PoolKey memory key, address source, address output, uint256 amountIn, uint256 minimumOut) =
            abi.decode(payload, (PoolKey, address, address, uint256, uint256));
        IPoolManagerMinimal manager = IPoolManagerMinimal(msg.sender);
        bool zeroForOne = source == key.currency0;
        int256 delta = manager.swap(key, IPoolManagerMinimal.SwapParams(zeroForOne, -int256(amountIn),
            zeroForOne ? TickMath.MIN_SQRT_PRICE + 1 : TickMath.MAX_SQRT_PRICE - 1), bytes(""));
        int128 delta0 = int128(delta >> 128); int128 delta1 = int128(uint128(uint256(delta)));
        int128 inputDelta = zeroForOne ? delta0 : delta1;
        int128 outputDelta = zeroForOne ? delta1 : delta0;
        if (inputDelta >= 0 || outputDelta <= 0 || uint256(-int256(inputDelta)) != amountIn ||
            uint256(int256(outputDelta)) < minimumOut) revert Slippage();
        manager.sync(source);
        if (source == address(0)) {
            if (manager.settle{value: amountIn}() != amountIn) revert InvalidState();
        } else {
            ExactToken.push(source, msg.sender, amountIn);
            if (manager.settle() != amountIn) revert InvalidState();
        }
        uint256 amountOut = uint256(int256(outputDelta));
        uint256 beforeOutput = ExactAsset.balance(output, address(this));
        if (output == address(0)) { nativeSender = msg.sender; nativeReceived = 0; }
        manager.take(output, address(this), amountOut);
        if (output == address(0)) {
            if (nativeReceived != amountOut) revert InvalidState();
            nativeSender = address(0); nativeReceived = 0;
        }
        if (ExactAsset.balance(output, address(this)) != beforeOutput + amountOut) revert InvalidState();
        return abi.encode(amountOut);
    }

constructor(address controller, uint256 nftHomeChain, address payable mintRecipient) ZZZModule(controller) {
        if (nftHomeChain == 0 || mintRecipient == address(0) || mintRecipient == address(this)) {
            revert InvalidConfiguration();
        }
        canonicalChainId = nftHomeChain;
        mintProceedsRecipient = mintRecipient;
        migrationBudget = new ZZZMigrationBudget(controller);
    }

receive() external payable {
        if (migrationBudget.validateNativeSender(msg.sender)) nativeReceived += msg.value;
    }

function nftStatus(uint256 id) external view returns (PositionStatus) {
        if (!minted[id]) return PositionStatus.None;
        uint256 bucket = nftBucket[id];
        return bucket == 0 ? PositionStatus.Dormant : positions[bucket].status;
    }

function group(uint256 bucket) external view returns (Position memory) {
        return positions[bucket];
    }

function bucketCount() external view returns (uint256) {
        return buckets.length;
    }

function bucketAt(uint256 index) external view returns (uint256) {
        return buckets[index];
    }

function canonicalModule() public view returns (ZZZVaultCanonical) {
        return ZZZVaultCanonical(payable(access.module(Ids.VAULT_CANONICAL)));
    }

function _registerBucket(uint256 bucketId) private {
        if (registeredBucket[bucketId]) return;
        if (buckets.length == MAX_BUCKETS) revert InvalidState();
        registeredBucket[bucketId] = true;
        buckets.push(bucketId);
    }

function reservePool(bytes32 pool, uint256 bucket) external onlyGovernance principalOperating {
        _reserve(pool, bucket);
    }

function _reserve(bytes32 pool, uint256 bucketId) private {
        migrationBudget.validateReservation(pool, bucketId);
        _registerBucket(bucketId);
        poolBucket[pool] = bucketId;
        canonicalModule().registerAlias(pool, bucketId);
        emit PoolReserved(pool, bucketId);
    }

function _tokens(uint256 bucketId) private view returns (address token0, address token1) {
        return migrationBudget.poolTokens(positions[bucketId].poolId);
    }

function _nft() private view returns (IZZZNFT) {
        return IZZZNFT(access.module(Ids.NFT));
    }

function _requireOwner(uint256 nftId, bool activation) private view {
        address entry = migrationBudget.validateOwner(nftId, msg.sender, minted[nftId], activation);
        if (entry != address(0)) IZZZActivationEntry(entry).validateOwner(nftId, keccak256(msg.data));
    }

function _active(uint256 bucketId) private view {
        if (positions[bucketId].status != PositionStatus.Active) revert InvalidState();
    }

function _tokenBalance(address token) private view returns (uint256) {
        return ExactAsset.balance(token, address(this));
    }

function _receiveAssets(address token0, address token1, uint256 amount0, uint256 amount1) private {
        // Registry admission fixes venue ordering: native can only be slot 0.
        if (msg.value != (token0 == address(0) ? amount0 : 0)) revert InvalidAmount();
        if (token0 != address(0)) ExactToken.pull(token0, msg.sender, amount0);
        ExactToken.pull(token1, msg.sender, amount1);
    }

function _idle(uint256 bucketId, uint256 new0, uint256 new1) private {
        if ((new0 | new1) > type(uint128).max) revert InvalidAmount();
        Position storage p = positions[bucketId];
        (address token0, address token1) = _tokens(bucketId);
        totalIdle[token0] = totalIdle[token0] - p.idle0 + new0;
        totalIdle[token1] = totalIdle[token1] - p.idle1 + new1;
        p.idle0 = new0;
        p.idle1 = new1;
        migrationBudget.assertIdle(bucketId);
    }

function _valueBucket(uint256 bucketId, uint256 amount0, uint256 amount1) private view returns (uint256) {
        return migrationBudget.valueBucket(bucketId, amount0, amount1);
    }

function _put(uint256 bucketId, bool create, uint128 minimumLiquidity, uint256 deadline,
        uint256 a0, uint256 a1) private {
        ZZZMigrationBudget budget = migrationBudget;
        Position storage p = positions[bucketId];
        (address token0, address token1) = _tokens(bucketId);
        IZZZLiquidity manager = IZZZLiquidity(_moduleLiquidity());
        // A contribution can deploy only its own post-swap amounts. Incumbent
        // idle and released compound remain attributed for guarded maintenance.
        if (a0 > p.idle0 || a1 > p.idle1) revert InvalidAmount();
        uint256 before0 = _tokenBalance(token0);
        uint256 before1 = _tokenBalance(token1);
        ExactAsset.approve(token0, address(manager), a0);
        ExactAsset.approve(token1, address(manager), a1);
        uint256 nativeValue = token0 == address(0) ? a0 : 0;
        uint256 spent0;
        uint256 spent1;
        if (create) {
            (int24 lower, int24 upper, uint160 ref) = budget.mintTarget(bucketId);
            (p.lpTokenId, spent0, spent1) =
                manager.mint{value: nativeValue}(p.poolId, lower, upper, a0, a1, minimumLiquidity, deadline);
            IPositionManagerMinimal(manager.positionManager()).approve(address(manager), p.lpTokenId);
            p.centerX96 = ref;
            p.lastRebalance = uint64(block.timestamp);
        } else {
            (spent0, spent1) =
                manager.increase{value: nativeValue}(p.poolId, p.lpTokenId, a0, a1, minimumLiquidity, deadline);
        }
        ExactAsset.approve(token0, address(manager), 0);
        ExactAsset.approve(token1, address(manager), 0);
        budget.assertPut(bucketId, a0, a1, spent0, spent1, before0, before1);
        _idle(bucketId, p.idle0 - spent0, p.idle1 - spent1);
        budget.assertDeployed(bucketId);
    }

function mintDormant() external payable live operating principalOperating nonReentrant returns (uint256 id) {
        // Companion preserves the exact price and home-chain issuance checks.
        id = canonicalModule().validateMint(msg.value, ++sequence);
        if (minted[id]) revert InvalidState();
        minted[id] = true;
        _nft().mint(msg.sender, id);
        (bool paid,) = mintProceedsRecipient.call{value: msg.value}("");
        if (!paid) revert InvalidState();
        emit DormantMinted(id, msg.sender, msg.value);
    }

function activate(
        uint256 id,
        bytes32 poolId,
        uint256 amount0,
        uint256 amount1,
        uint128 minimumLiquidity,
        uint256 deadline
    ) external payable live operating principalOperating nonReentrant {
        _requireOwner(id, true);
        uint256 bucket = poolBucket[poolId];
        if (bucket == 0 || positions[bucket].status == PositionStatus.None) {
            uint256 canonicalBucket = canonicalModule().bucketIdentity(poolId);
            if (bucket != 0 && bucket != canonicalBucket) revert InvalidState();
            bucket = canonicalBucket;
            _reserve(poolId, bucket);
            homePoolId[bucket] = poolId;
            Position storage p = positions[bucket];
            p.poolId = poolId;
            p.status = PositionStatus.Active;
        }
        if (positions[bucket].poolId != poolId) revert InvalidState();
        nftBucket[id] = bucket; // Set the fee-index domain BEFORE checkpointing zero shares.
        _join(id, bucket, amount0, amount1, minimumLiquidity, deadline, true);
        emit Activated(id, _nft().ownerOf(id), poolId, amount0, amount1);
    }

function increase(uint256 id, uint256 amount0, uint256 amount1, uint128 minimumLiquidity, uint256 deadline)
        external
        payable
        live
        operating
        principalOperating
        nonReentrant
    {
        _requireOwner(id, false);
        uint256 bucket = nftBucket[id];
        if (bucket == 0) revert InvalidState();
        _join(id, bucket, amount0, amount1, minimumLiquidity, deadline, false);
        emit LiquidityAdded(id, amount0, amount1);
    }

function _nav(uint256 bucketId) private returns (uint256 deployed, uint256 idleValue) {
        return migrationBudget.contributionNav(bucketId);
    }

function _join(
        uint256 nftId,
        uint256 bucketId,
        uint256 amount0,
        uint256 amount1,
        uint128 minimumLiquidity,
        uint256 deadline,
        bool activation
    ) private {
        _deadline(deadline);
        Position storage p = positions[bucketId];
        IZZZFees fees = IZZZFees(_moduleFees());
        uint256 inputUSD = IZZZPools(_modulePools()).contributionValue(p.poolId, amount0, amount1);
        (address token0, address token1, uint32 limits) = migrationBudget.validateContribution(
            nftId, bucketId, inputUSD, amount0 | (amount1 << 128), minimumLiquidity, activation
        );
        uint256 supply = bucketTotalShares[bucketId];
        // Settle all already-funded collective dust before eligibility changes.
        // Only this nonreentrant Vault can allocate new LP fee receipts.
        IZZZMembership(access.module(Ids.MEMBERSHIP)).settleDust();
        if (supply != 0) {
            _harvest(bucketId, deadline);
            fees.flushDust(bucketId, token0);
            fees.flushDust(bucketId, token1);
            _pullCompound(bucketId);
        }
        (uint256 oldLP, uint256 oldIdle) = _nav(bucketId);
        uint256 incumbentNAV = oldLP + oldIdle;
        if (supply != 0 && incumbentNAV == 0) revert InvalidState();
        _receiveAssets(token0, token1, amount0, amount1);
        _idle(bucketId, p.idle0 + amount0, p.idle1 + amount1);
        (amount0, amount1) = _balanceUsing(bucketId, deadline, amount0, amount1);
        uint256 freshCompound;
        if (supply != 0) {
            // Fees earned by the entry swap belong to pre-entry membership.
            _harvest(bucketId, deadline);
            fees.flushDust(bucketId, token0);
            fees.flushDust(bucketId, token1);
            (uint256 f0, uint256 f1) = _pullCompound(bucketId);
            freshCompound = _valueBucket(bucketId, f0, f1);
        }
        // Concentrated LP amounts reprice during the entry swap. Preserve that
        // gain/loss for incumbents; only net new assets buy the entrant's shares.
        (oldLP,) = _nav(bucketId);
        incumbentNAV = oldLP + oldIdle + freshCompound;
        if (supply != 0 && incumbentNAV == 0) revert InvalidState();
        _put(bucketId, supply == 0, minimumLiquidity, deadline, amount0, amount1);
        (uint256 late0, uint256 late1) = _pullCompound(bucketId);
        incumbentNAV += _valueBucket(bucketId, late0, late1);
        (uint256 newLP, uint256 newIdle) = _nav(bucketId);
        // Unclassified donations during callbacks cannot become LP fee income.
        IZZZRewards(access.module(Ids.REWARDS)).checkpointOwner(nftId);
        // The captured governed contribution limit applies to activation and
        // growth. Network gas is separate; later callbacks cannot widen this budget.
        // Incumbent idle/compound assets cannot subsidize this contribution.
        (uint256 issued, uint256 netUSD) = migrationBudget.contributionResult(
            bucketId, inputUSD, supply, incumbentNAV, oldLP, newLP, newIdle, limits
        );
        sharesOf[nftId] += issued;
        bucketTotalShares[bucketId] = supply + issued;
        contributionUSD[nftId] += inputUSD;
        p.depositUSD += inputUSD;
        if (activation) IZZZMembership(access.module(Ids.MEMBERSHIP)).activate(nftId);
        _nft().notifyContribution(nftId);
        emit SharesAdded(nftId, bucketId, issued, netUSD);
    }

function _allocate(uint256 bucketId, address token, uint256 amount) private {
        if (amount == 0) return;
        address fees = _moduleFees();
        ExactAsset.approve(token, fees, amount);
        IZZZFees(fees).allocate{value: token == address(0) ? amount : 0}(bucketId, token, amount);
        ExactAsset.approve(token, fees, 0);
    }

function _harvest(uint256 bucketId, uint256 deadline) private {
        _harvestVenue(bucketId, deadline);
    }

function _harvestVenue(uint256 bucketId, uint256 deadline) private {
        Position storage p = positions[bucketId];
        (address token0, address token1) = _tokens(bucketId);
        uint256 before0 = _tokenBalance(token0);
        uint256 before1 = _tokenBalance(token1);
        uint256 received = nativeReceived;
        IZZZLiquidity(_moduleLiquidity()).collect(p.poolId, p.lpTokenId, deadline);
        uint256 fee0 = _tokenBalance(token0) - before0;
        uint256 fee1 = _tokenBalance(token1) - before1;
        if (token0 == address(0) && fee0 != nativeReceived - received) revert InvalidState();
        _allocate(bucketId, token0, fee0);
        _allocate(bucketId, token1, fee1);
        emit FeesCollected(bucketId, fee0, fee1);
    }

function collectFees(uint256 id, uint256 deadline) external live nonReentrant canonicalAccounting principalOperating {
        _deadline(deadline);
        _active(id);
        _harvest(id, deadline);
    }

function _pullCompound(uint256 bucketId) private returns (uint256 amount0, uint256 amount1) {
        (address token0, address token1) = _tokens(bucketId);
        Position storage p = positions[bucketId];
        IZZZFees fees = IZZZFees(_moduleFees());
        amount0 = fees.releaseCompound(bucketId, token0);
        amount1 = fees.releaseCompound(bucketId, token1);
        _idle(bucketId, p.idle0 + amount0, p.idle1 + amount1);
    }

function compound(uint256 id, uint128 minimumLiquidity, uint256 deadline)
        external
        onlyModule(Ids.COMPOUNDER)
        live
        operating
        principalOperating
        nonReentrant
    {
        _deadline(deadline);
        _active(id);
        _migrationCheckpoint(id, 3);
        _harvest(id, deadline);
        (uint256 amount0, uint256 amount1) = _pullCompound(id);
        _migrationCheckpoint(id, 1);
        _redeploy(id, minimumLiquidity, deadline);
        _migrationCheckpoint(id, 2);
        emit Compounded(id, amount0, amount1);
    }

function _close(uint256 bucketId, uint256 deadline) private {
        Position storage p = positions[bucketId];
        (address token0, address token1) = _tokens(bucketId);
        uint256 before0 = _tokenBalance(token0);
        uint256 before1 = _tokenBalance(token1);
        uint256 received = nativeReceived;
        IZZZLiquidity(_moduleLiquidity()).close(p.poolId, p.lpTokenId, deadline);
        uint256 closed0 = _tokenBalance(token0) - before0;
        uint256 closed1 = _tokenBalance(token1) - before1;
        if (token0 == address(0) && closed0 != nativeReceived - received) revert InvalidState();
        p.lpTokenId = 0;
        _idle(bucketId, p.idle0 + closed0, p.idle1 + closed1);
    }

function _balanceUsing(uint256 bucketId, uint256 deadline, uint256 amount0, uint256 amount1)
        private returns (uint256 balanced0, uint256 balanced1) {
        Position storage p = positions[bucketId];
        if (amount0 > p.idle0 || amount1 > p.idle1) revert InvalidAmount();
        (address token0, address token1) = _tokens(bucketId);
        address manager = _moduleLiquidity();
        uint256 before0 = _tokenBalance(token0);
        uint256 before1 = _tokenBalance(token1);
        bytes32 context = migrationBudget.balanceContext(bucketId);
        ExactAsset.approve(token0, manager, amount0);
        ExactAsset.approve(token1, manager, amount1);
        (balanced0, balanced1) = IZZZLiquidity(manager).balance{value: token0 == address(0) ? amount0 : 0}(
            p.poolId, p.lpTokenId, amount0, amount1, deadline
        );
        ExactAsset.approve(token0, manager, 0);
        ExactAsset.approve(token1, manager, 0);
        if (migrationBudget.balanceContext(bucketId) != context) revert InvalidState();
        // A typed return must match actual net receipts. Existing raw prefunds
        // or callback donations cannot fill a claimed balancing-output shortfall.
        if (_tokenBalance(token0) + amount0 != before0 + balanced0 ||
            _tokenBalance(token1) + amount1 != before1 + balanced1) revert InvalidState();
        _idle(bucketId, p.idle0 - amount0 + balanced0, p.idle1 - amount1 + balanced1);
    }

function _idleValue(uint256 bucketId) private view returns (uint256) {
        return migrationBudget.idleValue(bucketId);
    }

function _unwind(uint256 bucketId, uint256 deadline) private {
        migrationBudget.validateUnwind(bucketId);
        _harvest(bucketId, deadline);
        _pullCompound(bucketId);
        _migrationCheckpoint(bucketId, 1);
        _close(bucketId, deadline);
    }

function _migrationCheckpoint(uint256 bucketId, uint8 phase) private {
        migrationBudget.checkpoint(bucketId, phase);
    }

function _redeploy(uint256 bucketId, uint128 minimumLiquidity, uint256 deadline) private {
        bool create = positions[bucketId].lpTokenId == 0;
        uint256 beforeValue = _idleValue(bucketId);
        Position storage p = positions[bucketId];
        _balanceUsing(bucketId, deadline, p.idle0, p.idle1);
        // An existing LP can earn fees from its one balancing swap. Settle
        // them separately before INCREASE; they are never treated as principal.
        if (!create) _harvest(bucketId, deadline);
        migrationBudget.assertIdleLoss(bucketId, beforeValue);
        _put(bucketId, create, minimumLiquidity, deadline, p.idle0, p.idle1);
    }

function rebalance(uint256 id, uint128 minimumLiquidity, uint256 deadline)
        external
        onlyKeeper
        live
        operating
        principalOperating
        nonReentrant
    {
        _rebalance(id,minimumLiquidity,deadline,false);
        if (!access.keeperAuthorized(msg.sender) || access.paused()) revert Unauthorized();
    }

function emergencyRebalance(uint256 id,uint128 minimumLiquidity,uint256 deadline)
        external onlyModule(Ids.MIGRATION) operating principalOperating nonReentrant {
        IZZZEmergencyLiquidity(_moduleLiquidity()).beginEmergency();
        _rebalance(id,minimumLiquidity,deadline,true);
        IZZZEmergencyLiquidity(_moduleLiquidity()).endEmergency();
    }

function _rebalance(uint256 id,uint128 minimumLiquidity,uint256 deadline,bool emergency) private {
        _deadline(deadline);
        bool parked = emergency && positions[id].status == PositionStatus.Parked;
        if(!parked) _active(id);
        migrationBudget.validateRebalance(id, minimumLiquidity);
        Position storage p = positions[id];
        uint256 oldId = p.lpTokenId;
        _migrationCheckpoint(id, 0);
        if(parked) { _pullCompound(id); _migrationCheckpoint(id,1); }
        else _unwind(id, deadline);
        _redeploy(id, minimumLiquidity, deadline);
        _migrationCheckpoint(id, 2);
        if(parked) p.status = PositionStatus.Active;
        emit Rebalanced(id, oldId, p.lpTokenId, p.centerX96);
    }

function beginLPExit() external onlyModule(Ids.MIGRATION) operating nonReentrant {
        access.startLPExit();
    }

function exitBucketToHolders(uint256 id, uint256 minimumETH, uint256 minimumZZZ, uint256 deadline)
        external onlyModule(Ids.MIGRATION) operating nonReentrant
        returns (uint256 amountETH, uint256 amountZZZ)
    {
        _deadline(deadline);
        if (!access.paused() || !access.lpExitStarted()) revert InvalidState();
        Position storage p = positions[id];
        if ((p.status != PositionStatus.Active && p.status != PositionStatus.Parked) || bucketTotalShares[id] == 0)
            revert InvalidState();
        (address token0, address token1) = _tokens(id);
        if (token0 != address(0) || token1 != IZZZMigration(msg.sender).currentZZZ()) revert InvalidConfiguration();
        // Final harvest runs while Active, as required by funded fee allocation.
        if (p.status == PositionStatus.Active) _harvestVenue(id, deadline);
        IZZZFees fees = IZZZFees(_moduleFees());
        fees.flushDust(id, token0);
        fees.flushDust(id, token1);
        _pullCompound(id);
        if (p.status == PositionStatus.Active) _close(id, deadline);
        if (p.lpTokenId != 0) revert InvalidState();
        amountETH = p.idle0;
        amountZZZ = p.idle1;
        if (amountETH < minimumETH || amountZZZ < minimumZZZ) revert Slippage();
        _idle(id, 0, 0);
        p.status = PositionStatus.Exited;
        migrationBudget.recordComposition(id);
        ExactAsset.push(token0, msg.sender, amountETH);
        ExactAsset.push(token1, msg.sender, amountZZZ);
        emit PrincipalReturnedToHolders(id, amountETH, amountZZZ);
    }

function park(uint256 id, uint256 deadline) external onlyModule(Ids.MIGRATION) nonReentrant canonicalAccounting principalOperating {
        _deadline(deadline);
        _active(id);
        if (!access.paused() || positions[id].lpTokenId == 0) revert InvalidState();
        uint256 oldLp = positions[id].lpTokenId;
        _harvestVenue(id, deadline);
        _close(id, deadline);
        positions[id].status = PositionStatus.Parked;
        emit PrincipalParked(id, oldLp);
    }

function resume(uint256 id, bytes32 newPool, uint128 minimumLiquidity, uint256 deadline)
        external
        onlyModule(Ids.MIGRATION)
        live
        operating
        principalOperating
        nonReentrant
    {
        _deadline(deadline);
        if (positions[id].status != PositionStatus.Parked) revert InvalidState();
        _movePool(id, newPool, minimumLiquidity, deadline);
        positions[id].status = PositionStatus.Active;
    }

function movePool(uint256 id, bytes32 newPool, uint128 minimumLiquidity, uint256 deadline)
        external
        onlyModule(Ids.MIGRATION)
        live
        operating
        principalOperating
        nonReentrant
    {
        _deadline(deadline);
        _active(id);
        if (positions[id].poolId == newPool) revert InvalidConfiguration();
        _movePool(id, newPool, minimumLiquidity, deadline);
    }

function _movePool(uint256 bucketId, bytes32 newPool, uint128 minimumLiquidity, uint256 deadline) private {
        Position storage p = positions[bucketId];
        migrationBudget.validateMove(bucketId, newPool, minimumLiquidity);
        _reserve(newPool, bucketId);
        uint256 oldId = p.lpTokenId;
        _migrationCheckpoint(bucketId, 0);
        if (p.status == PositionStatus.Parked) {
            _pullCompound(bucketId);
            _migrationCheckpoint(bucketId, 1);
        } else {
            _unwind(bucketId, deadline);
        }
        p.poolId = newPool; // Ordinary local maintenance retains its ordered-pair guard.
        _redeploy(bucketId, minimumLiquidity, deadline);
        _migrationCheckpoint(bucketId, 2);
        emit Rebalanced(bucketId, oldId, p.lpTokenId, p.centerX96);
    }

function onERC721Received(address, address, uint256, bytes calldata) external view override returns (bytes4) {
        migrationBudget.validateLPReceiver(msg.sender);
        return IERC721Receiver.onERC721Received.selector;
    }

function canonicalWrite(uint8 kind, bytes calldata row) external {
        migrationBudget.validateCanonicalWriter(msg.sender);
        if (kind == 0) {
            sequence = abi.decode(row, (uint256));
        } else if (kind == 1) {
            (uint256 id, uint256 bucket, uint256 shares, uint256 contribution) =
                abi.decode(row, (uint256, uint256, uint256, uint256));
            if (minted[id]) revert InvalidState();
            minted[id] = true;
            nftBucket[id] = bucket;
            sharesOf[id] = shares;
            contributionUSD[id] = contribution;
        } else if (kind == 2) {
            (uint256 id, Position memory p, uint256 shares, bytes32 homePool) =
                abi.decode(row, (uint256, Position, uint256, bytes32));
            _registerBucket(id);
            positions[id] = p;
            bucketTotalShares[id] = shares;
            homePoolId[id] = homePool;
            if (p.status == PositionStatus.Parked) {
                (address a, address b) = migrationBudget.poolTokens(p.poolId);
                totalIdle[a] += p.idle0;
                totalIdle[b] += p.idle1;
            }
        } else if (kind == 3) {
            (bytes32 pool, uint256 id) = abi.decode(row, (bytes32, uint256));
            poolBucket[pool] = id;
        } else {
            revert InvalidConfiguration();
        }
    }

function canonicalSend(address token, address destination, uint256 amount) external {
        _canonicalSender();
        ExactAsset.push(token, destination, amount);
    }

function canonicalBarrier() external nonReentrant {
        _canonicalSender();
    }

function _canonicalSender() private view {
        if (msg.sender != access.module(Ids.VAULT_CANONICAL)) revert Unauthorized();
    }

function _modulePools() private view returns (address) {
        return access.module(Ids.POOLS);
    }

function _moduleLiquidity() private view returns (address) {
        return access.module(Ids.LIQUIDITY);
    }

function _moduleFees() private view returns (address) {
        return access.module(Ids.FEES);
    }

constructor(address controller, address vaultController, uint256 chain) {
        access = IZZZAccess(controller);
        if (vaultController.code.length == 0 || IZZZAccess(controller).module(Ids.VAULT) != vaultController ||
            chain == 0 || IZZZVault(vaultController).canonicalChainId() != chain) revert InvalidState();
        vault = ICanonicalVaultState(vaultController);
        originChain = chain;
        originVault = vaultController;
    }

modifier onlyBudget() {
        if (msg.sender != address(vault.migrationBudget())) revert Unauthorized();
        _;
    }

modifier onlyHandoff() {
        if (msg.sender != IZZZCanonicalAccess(address(access)).canonicalHandoff()) revert Unauthorized();
        _;
    }

function validateOwner(uint256 id,address caller,bool minted,bool activation)
        external view onlyBudget returns(address entry) {
        if (block.chainid != vault.canonicalChainId() || !minted) revert Unauthorized();
        if (activation && (vault.nftBucket(id) != 0 || !IZZZNFT(access.module(Ids.NFT)).traitsReady(id))) revert InvalidState();
        if (IZZZNFT(access.module(Ids.NFT)).ownerOf(id) == caller) return address(0);
        entry = IZZZPools(access.module(Ids.POOLS)).activationEntry();
        if (entry == address(0) || caller != entry) revert Unauthorized();
    }

function validateContribution(uint256 id,uint256 bucket,uint256 inputUSD,uint256 inputTotal,
        uint128 minimumLiquidity,bool activation) external view onlyBudget returns(address,address,uint16) {
        Position memory p = vault.group(bucket);
        if (p.status != PositionStatus.Active ||
            IZZZMigration(access.module(Ids.MIGRATION)).activePlan(bucket) != bytes32(0)) revert InvalidState();
        PoolConfig memory c = IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
        if (!c.depositsEnabled || inputTotal == 0 || minimumLiquidity == 0 ||
            (activation && inputUSD < 100e18) || (!activation && inputUSD < 5e18) || inputUSD < c.minDepositUSD ||
            vault.contributionUSD(id) + inputUSD > c.maxPositionUSD) revert InvalidAmount();
        return(c.key.currency0,c.key.currency1,c.maxSlippageBps);
    }

function mintIdentity(uint256 ordinal) external view returns (uint256) {
        return uint256(keccak256(abi.encode(originChain, originVault, ordinal)));
    }

function validateMint(uint256 value,uint256 ordinal) external view onlyVault returns (uint256) {
        if (block.chainid != vault.canonicalChainId()) revert InvalidState();
        if (value != vault.MINT_PRICE()) revert InvalidAmount();
        return uint256(keccak256(abi.encode(originChain,originVault,ordinal)));
    }

function bucketIdentity(bytes32 pool) external view returns (uint256) {
        return uint256(keccak256(abi.encode(originChain, originVault, pool)));
    }

function registerAlias(bytes32 pool, uint256 bucket) external onlyVault {
        uint256 old = aliasBucket[pool];
        if (old != 0 && old != bucket) revert InvalidState();
        if (old == 0) { aliases.push(pool); aliasBucket[pool] = bucket; }
    }

function canonicalCapture() external onlyHandoff {
        if (IZZZCanonicalAccess(address(access)).canonicalState() != 1) revert InvalidState();
        vault.canonicalBarrier();
        // A proved abort may be followed by a fresh freeze. Only snapshot caches
        // reset; ordinary shares, reservations and principal remain untouched.
        bool reset = captured || imported;
        delete backingAssets; delete backingAmounts;
        imported = false;
        nftCount = vault.sequence(); groupCount = vault.bucketCount(); aliasCount = aliases.length;
        for (uint256 i; i < groupCount; ++i) {
            uint256 id = vault.bucketAt(i);
            Position memory p = vault.group(id);
            if (p.status == PositionStatus.None) {
                if (p.lpTokenId != 0 || p.idle0 != 0 || p.idle1 != 0 || vault.bucketTotalShares(id) != 0) revert InvalidState();
            } else if (p.status != PositionStatus.Parked || p.lpTokenId != 0) revert InvalidState();
            if (IZZZMigration(access.module(Ids.MIGRATION)).activePlan(id) != bytes32(0)) revert InvalidState();
        }
        ICanonicalVaultRewards rewards = ICanonicalVaultRewards(access.module(Ids.REWARDS));
        if (rewards.assetCount() > 33) revert InvalidState();
        for (uint256 i; i < rewards.assetCount(); ++i) {
            address asset = rewards.assets(i);
            for (uint256 j; j < i; ++j) if (backingAssets[j] == asset) revert InvalidState();
            uint256 balance = ExactAsset.balance(asset,address(vault));
            if (balance < vault.totalIdle(asset)) revert InvalidState();
            backingAssets.push(asset); backingAmounts.push(balance);
            // A fresh source has zero flags; recapture/successor capture
            // clears old delivery flags without snapshotting unrelated prefunds.
            if (reset) { released[i] = false; accepted[i] = false; }
        }
        captured = true;
    }

function canonicalCount() public view returns (uint256) {
        return 1 + groupCount + aliasCount + nftCount + backingAssets.length;
    }

function canonicalExport(uint256 row) external view returns (bytes memory) {
        if (!captured || row >= canonicalCount()) revert InvalidState();
        if (row == 0) return abi.encode(originChain, originVault, nftCount, groupCount, aliasCount, backingAssets.length);
        --row;
        if (row < groupCount) {
            uint256 id = vault.bucketAt(row);
            return abi.encode(id, vault.group(id), vault.bucketTotalShares(id), vault.homePoolId(id),
                vault.migrationBudget().compositionEpoch(id));
        }
        row -= groupCount;
        if (row < aliasCount) return abi.encode(aliases[row], aliasBucket[aliases[row]]);
        row -= aliasCount;
        if (row < nftCount) {
            uint256 id = ICanonicalVaultNFT(access.module(Ids.NFT)).tokenAtOrdinal(row + 1);
            return abi.encode(id, vault.nftBucket(id), vault.sharesOf(id), vault.contributionUSD(id));
        }
        row -= nftCount;
        address asset = backingAssets[row];
        // Retain the exact principal/quarantine classification even when raw
        // balances subsequently increase through unsolicited transfers.
        return abi.encode(asset, backingAmounts[row], vault.totalIdle(asset));
    }

function canonicalImport(uint256 row, bytes calldata record) external onlyHandoff {
        if (IZZZCanonicalAccess(address(access)).canonicalState() != 2 || row != cursor++) revert InvalidState();
        if (row == 0) {
            if (record.length != 192) revert InvalidState();
            if (vault.sequence() != 0 || vault.bucketCount() != 0 || aliases.length != 0) revert InvalidState();
            uint256 assetCount;
            (originChain, originVault, nftCount, groupCount, aliasCount, assetCount) =
                abi.decode(record, (uint256,address,uint256,uint256,uint256,uint256));
            if (originChain == 0 || originVault == address(0) || nftCount > 1000 || groupCount > 4 || assetCount > 33) revert InvalidState();
            // Fixed length records make the complete domain independent of relay choices.
            backingAssets = new address[](assetCount); backingAmounts = new uint256[](assetCount);
            vault.canonicalWrite(0, abi.encode(nftCount));
            imported = true;
            return;
        }
        --row;
        if (row < groupCount) {
            if (record.length != 384) revert InvalidState();
            (uint256 id, Position memory p, uint256 shares, bytes32 homePool, uint64 epoch) =
                abi.decode(record, (uint256,Position,uint256,bytes32,uint64));
            if (p.status != PositionStatus.None && p.status != PositionStatus.Parked) revert InvalidState();
            if (p.status == PositionStatus.Parked) {
                // The admitted pool key supplies the actual local currencies.
                // Exact backing rows below must fund their attributed idle;
                // there is no remote/home token identity to reinterpret.
                IZZZPools(access.module(Ids.POOLS)).accounting(p.poolId);
                if (p.lpTokenId != 0) revert InvalidState();
            }
            vault.canonicalWrite(2, abi.encode(id, p, shares, homePool));
            vault.migrationBudget().importComposition(id,epoch);
            return;
        }
        row -= groupCount;
        if (row < aliasCount) {
            if (record.length != 64) revert InvalidState();
            (bytes32 pool, uint256 id) = abi.decode(record, (bytes32,uint256));
            if (pool == bytes32(0) || id == 0 || aliasBucket[pool] != 0) revert InvalidState();
            aliases.push(pool); aliasBucket[pool] = id;
            vault.canonicalWrite(3, record);
            return;
        }
        row -= aliasCount;
        if (row < nftCount) {
            if (record.length != 128) revert InvalidState();
            (uint256 id, uint256 bucket, uint256 shares, uint256 contribution) = abi.decode(record, (uint256,uint256,uint256,uint256));
            if (id != uint256(keccak256(abi.encode(originChain, originVault, row + 1))) ||
                (bucket == 0 ? shares != 0 || contribution != 0 : shares == 0)) revert InvalidState();
            importedShares[bucket] += shares;
            vault.canonicalWrite(1, record);
            return;
        }
        row -= nftCount;
        if (row >= backingAssets.length) revert InvalidState();
        if (record.length != 96) revert InvalidState();
        (address asset, uint256 amount, uint256 principal) = abi.decode(record, (address,uint256,uint256));
        if (principal != vault.totalIdle(asset) || amount < principal) revert InvalidState();
        for (uint256 i; i < row; ++i) if (backingAssets[i] == asset) revert InvalidState();
        backingAssets[row] = asset; backingAmounts[row] = amount;
        companionPrefund[row] = ExactAsset.balance(asset,address(this));
    }

function canonicalBacking(uint256 index) external view returns (address asset, uint256 amount) {
        return (backingAssets[index], backingAmounts[index]);
    }

function canonicalRelease(uint256 index, address destination) external onlyHandoff {
        uint8 state = IZZZCanonicalAccess(address(access)).canonicalState();
        if ((state != 1 && state != 4) || released[index] || (state == 4 && !accepted[index])) revert InvalidState();
        released[index] = true;
        vault.canonicalSend(backingAssets[index], destination, backingAmounts[index]);
    }

function canonicalAccept(uint256 index, address) external payable onlyHandoff {
        if (msg.value != 0 || IZZZCanonicalAccess(address(access)).canonicalState() != 2 || accepted[index]) revert InvalidState();
        accepted[index] = true;
        _forward(index,false);
    }

function canonicalRestore(uint256 index, address) external payable onlyHandoff {
        if (msg.value != 0 || IZZZCanonicalAccess(address(access)).canonicalState() != 1 || !released[index]) revert InvalidState();
        _forward(index,true);
        released[index] = false;
    }

function _forward(uint256 index,bool restore) private {
        address asset=backingAssets[index]; uint256 amount=backingAmounts[index];
        // Source restore follows Handoff.returnFunds' exact balance-delta check.
        // Capturing source prefunds would permit 33 dust donations to impose
        // cold storage costs on freeze. Imported successors must not reuse an
        // old importer baseline when they later become a source.
        uint256 prefund=restore?0:companionPrefund[index];
        if (ExactAsset.balance(asset,address(this)) < prefund+amount) revert InvalidState();
        ExactAsset.push(asset,address(vault),amount);
    }

function canonicalValidate() external view {
        if (imported) {
            if (cursor != canonicalCount() || vault.bucketCount() != groupCount || aliases.length != aliasCount) revert InvalidState();
            for (uint256 i; i < groupCount; ++i) {
                uint256 id = vault.bucketAt(i);
                if (importedShares[id] != vault.bucketTotalShares(id)) revert InvalidState();
            }
        } else if (!captured) revert InvalidState();
        for (uint256 i; i < backingAssets.length; ++i) {
            if (ExactAsset.balance(backingAssets[i],address(vault)) < backingAmounts[i]) revert InvalidState();
        }
    }

function canonicalActivate() external onlyHandoff {
        if (IZZZCanonicalAccess(address(access)).canonicalState() != 2) revert InvalidState();
    }

function _state() internal view returns (uint8) {
        address controller = _canonicalAccess();
        return controller == address(0) ? 0 : IZZZCanonicalAccess(controller).canonicalState();
    }

modifier canonicalOnly() {
        if (msg.sender != IZZZCanonicalAccess(_canonicalAccess()).canonicalHandoff()) revert CanonicalState();
        _;
    }

function _canonicalBeginCapture() internal {
        if (_state() != 1) revert CanonicalState();
        for (uint256 i; i < canonicalAssets.length; ++i) { delete canonicalDelivered[i]; delete canonicalAccepted[i]; }
        delete canonicalAssets; delete canonicalAmounts; delete canonicalPrefunds;
        canonicalCaptured = true;
    }

function _canonicalNext(uint256 row) internal {
        if (_state() != 2 || canonicalCursor != row) revert CanonicalState();
        ++canonicalCursor;
    }

function _canonicalBalance(address asset) internal view returns (uint256) {
        return asset == address(0) ? address(this).balance : IERC20(asset).balanceOf(address(this));
    }

function _canonicalAdd(address asset, uint256 amount, uint256 prefund) internal {
        for (uint256 i; i < canonicalAssets.length; ++i) if (canonicalAssets[i] == asset) revert CanonicalState();
        canonicalAssets.push(asset); canonicalAmounts.push(amount); canonicalPrefunds.push(prefund);
    }

function canonicalBacking(uint256 i) external view returns (address, uint256) {
        return (canonicalAssets[i], canonicalAmounts[i]);
    }

function canonicalRelease(uint256 i, address destination) external canonicalOnly {
        uint8 state = _state();
        if ((state != 1 && state != 2 && state != 4) || canonicalDelivered[i] || destination == address(0) ||
            (state != 1 && !canonicalAccepted[i])) revert CanonicalState();
        canonicalDelivered[i] = true;
        uint256 amount = canonicalAmounts[i];
        address asset = canonicalAssets[i];
        ExactAsset.push(asset,destination,amount);
    }

function canonicalAccept(uint256 i, address) external payable canonicalOnly {
        if (_state() != 2 || canonicalAccepted[i] || msg.value != 0 ||
            _canonicalBalance(canonicalAssets[i]) < canonicalPrefunds[i] + canonicalAmounts[i]) revert CanonicalState();
        canonicalAccepted[i] = true;
    }

function canonicalRestore(uint256 i, address) external payable canonicalOnly {
        if (_state() != 1 || !canonicalDelivered[i] || msg.value != 0 ||
            _canonicalBalance(canonicalAssets[i]) < canonicalAmounts[i]) revert CanonicalState();
        canonicalDelivered[i] = false;
    }

function _canonicalValidateBacking() internal view {
        for (uint256 i; i < canonicalAssets.length; ++i) {
            if (_canonicalBalance(canonicalAssets[i]) < canonicalAmounts[i] + canonicalPrefunds[i]) revert CanonicalState();
        }
    }

function canonicalActivate() external virtual canonicalOnly {
        if (_state() != 2) revert CanonicalState();
    }

constructor(address controller) {
        if (controller.code.length == 0) revert InvalidConfiguration();
        access = IZZZAccess(controller);
    }

modifier onlyModule(bytes32 id) {
        _checkModule(id);
        _;
    }

function _checkModule(bytes32 id) private view {
        if (!access.moduleAuthorized(id, msg.sender)) revert Unauthorized();
    }

modifier onlyGovernance() {
        _checkGovernance();
        _;
        _checkGovernance();
    }

function _checkGovernance() private view {
        if (!access.canConfigure(msg.sender)) revert Unauthorized();
    }

modifier onlyDrainGovernance() {
        _checkDrainGovernance();
        _;
    }

function _checkDrainGovernance() private view {
        _checkAccounting();
        if (msg.sender != access.governance() && !access.canConfigure(msg.sender)) revert Unauthorized();
    }

modifier operating() {
        _checkOperating();
        _;
        _checkOperating();
    }

function _checkOperating() internal view {
        if (access.preparationActive()) revert Preparing();
        _checkAccounting();
    }

modifier principalOperating() {
        if (access.lpExitStarted()) revert LPExitLocked();
        _;
        if (access.lpExitStarted()) revert LPExitLocked();
    }

modifier onlyHandoff() {
        if (msg.sender != access.canonicalHandoff()) revert Unauthorized();
        _;
    }

modifier canonicalAccounting() {
        _checkAccounting();
        _;
        _checkAccounting();
    }

function _checkAccounting() internal view {
        if (access.canonicalState() != 0) revert CanonicalLocked();
    }

modifier onlyKeeper() {
        _checkKeeper();
        _;
    }

function _checkKeeper() private view {
        if (!access.keeperAuthorized(msg.sender)) revert Unauthorized();
    }

modifier live() {
        _checkLive();
        _;
    }

function _checkLive() private view {
        _checkAccounting();
        if (!access.isSealed()) revert NotReady();
        if (access.paused()) revert Paused();
    }

function _deadline(uint256 deadline) internal view {
        if (deadline < block.timestamp || deadline > block.timestamp + 10 minutes) revert Expired();
    }

constructor(address controller, address receiver, address wrappedETH) ZZZModule(controller) {
        if (receiver.code.length == 0 || (wrappedETH != address(0) && wrappedETH.code.length == 0)) revert InvalidConfiguration();
        ledger = receiver; wrapper = wrappedETH;
        v4Executor = new ZZZV4RouteExecutor();
    }

receive() external payable {
        if (nativeSender == address(0) || msg.sender != nativeSender) revert Unauthorized();
    }

function configureWrapper(WrapperPolicy calldata policy) external onlyGovernance operating nonReentrant {
        _checkWrapper(policy);
        wrapperPolicy = policy;
        emit WrapperConfigured(keccak256(abi.encode(policy)), policy.reviewHash);
    }

function setEnabled(bool value) external onlyGovernance operating nonReentrant {
        enabled = value; emit Enabled(value);
    }

function setConversionLossBps(uint16 value) external onlyGovernance operating nonReentrant {
        if (value > MAX_LOSS_BPS) revert InvalidConfiguration();
        uint16 previous = conversionLossBps;
        conversionLossBps = value;
        emit ConversionLossLimitChanged(previous, value);
    }

function addRoute(RoutePolicy calldata policy) external onlyGovernance operating nonReentrant returns (bytes32 id) {
        _checkRoute(policy);
        id = keccak256(abi.encode(policy));
        if (routeExists(id)) revert InvalidConfiguration();
        routes[id] = policy; v3RouteExists[id] = true; v3RouteEnabled[id] = true;
        emit RouteRecorded(id, policy.source, policy.reviewHash); emit RouteEnabled(id, true);
    }

function route(bytes32 id) external view returns (RoutePolicy memory) {
        if (!v3RouteExists[id]) revert InvalidConfiguration(); return routes[id];
    }

function addV4Route(ZZZV4RouteExecutor.Policy calldata policy)
        external onlyGovernance operating nonReentrant returns (bytes32 id) {
        if (policy.source == address(0) || policy.output != address(0)) revert InvalidConfiguration();
        id = v4Executor.addRoute(policy);
        if (v3RouteExists[id]) revert InvalidConfiguration();
        emit V4RouteRecorded(id, policy.source, policy.reviewHash);
        emit RouteEnabled(id, true);
    }

function v4Route(bytes32 id) external view returns (ZZZV4RouteExecutor.Policy memory) {
        return v4Executor.route(id);
    }

function routeKind(bytes32 id) public view returns (uint8) {
        return v3RouteExists[id] ? 1 : v4Executor.routeExists(id) ? 2 : 0;
    }

function routeEnabled(bytes32 id) public view returns (bool) {
        return v3RouteExists[id] ? v3RouteEnabled[id] : v4Executor.routeEnabled(id);
    }

function setRouteEnabled(bytes32 id, bool value) external onlyGovernance operating nonReentrant {
        uint8 kind = routeKind(id);
        if (kind == 0) revert InvalidConfiguration();
        if (kind == 1) {
            if (value) _checkRoute(routes[id]);
            v3RouteEnabled[id] = value;
        } else v4Executor.setRouteEnabled(id, value);
        emit RouteEnabled(id, value);
    }

function _pin(address target, bytes32 hash) private view {
        if (hash == bytes32(0) || target.code.length == 0 || target.codehash != hash) revert InvalidConfiguration();
    }

function _checkWrapper(WrapperPolicy memory p) private view {
        _pin(wrapper, p.codeHash);
        if (p.reviewHash == bytes32(0)) revert InvalidConfiguration();
        if (p.admin == address(0)) {
            if (p.implementation != address(0) || p.adminOwner != address(0) ||
                p.adminCodeHash != bytes32(0) || p.implementationCodeHash != bytes32(0)) revert InvalidConfiguration();
        } else {
            _pin(p.admin, p.adminCodeHash); _pin(p.implementation, p.implementationCodeHash);
            IRewardProxyAdmin admin = IRewardProxyAdmin(p.admin);
            if (admin.owner() != p.adminOwner || admin.getProxyAdmin(wrapper) != p.admin ||
                admin.getProxyImplementation(wrapper) != p.implementation) revert InvalidConfiguration();
        }
    }

function _checkRoute(RoutePolicy memory p) private view {
        if (wrapper == address(0) || p.source == wrapper || p.reviewHash == bytes32(0) || p.fee >= 1_000_000) revert InvalidConfiguration();
        _pin(p.source, p.sourceCodeHash); _pin(p.router, p.routerCodeHash);
        _pin(p.factory, p.factoryCodeHash); _pin(p.pool, p.poolCodeHash);
        ZZZV3VenueValidation.validate(p.router, p.factory, p.pool, p.source, wrapper, p.fee);
    }

function convert(address source, uint256 amount, bytes32 routeId, uint256 minimumETH, uint256 deadline)
        external live operating nonReentrant returns (uint256 output) {
        if (msg.sender != ledger || !enabled) revert Unauthorized();
        _deadline(deadline);
        if (source == address(0) || amount == 0 || minimumETH == 0) revert InvalidAmount();
        if (routeKind(routeId) == 2) return _convertV4(source, amount, routeId, minimumETH, deadline);
        if (wrapper == address(0)) revert InvalidConfiguration();
        _checkWrapper(wrapperPolicy);
        RoutePolicy memory p;
        uint256 floor = amount;
        if (source == wrapper) {
            if (routeId != bytes32(0)) revert InvalidConfiguration();
        } else {
            if (!v3RouteEnabled[routeId]) revert InvalidConfiguration();
            p = routes[routeId];
            if (p.source != source) revert InvalidConfiguration();
            _checkRoute(p);
            uint256 expected = IZZZOracle(access.module(Ids.ORACLE)).quote(source, wrapper, amount);
            if (expected == 0) revert InvalidAmount();
            floor = Math.mulDiv(expected, 10_000 - conversionLossBps, 10_000, Math.Rounding.Ceil);
        }
        uint256 minimum = Math.max(floor, minimumETH);
        uint256 sourceBefore = IERC20(source).balanceOf(address(this));
        uint256 wrappedBefore = IERC20(wrapper).balanceOf(address(this));
        uint256 nativeBefore = address(this).balance;
        ExactToken.pull(source, ledger, amount);
        output = amount;
        if (source != wrapper) {
            IERC20(source).forceApprove(p.router, amount);
            output = IV3RouteRouter(p.router).exactInputSingle(IV3RouteRouter.ExactInputSingleParams(
                source, wrapper, p.fee, address(this), amount, minimum, 0));
            IERC20(source).forceApprove(p.router, 0);
            if (IERC20(source).balanceOf(address(this)) != sourceBefore ||
                IERC20(wrapper).balanceOf(address(this)) != wrappedBefore + output) revert InvalidState();
            _checkRoute(p);
        }
        if (output < minimum) revert Slippage();
        nativeSender = wrapper;
        IRewardWrapper(wrapper).withdraw(output);
        nativeSender = address(0);
        _checkWrapper(wrapperPolicy);
        if (IERC20(wrapper).balanceOf(address(this)) != wrappedBefore ||
            address(this).balance != nativeBefore + output) revert InvalidState();
        (bool ok,) = payable(ledger).call{value: output}("");
        if (!ok || address(this).balance != nativeBefore) revert InvalidState();
        emit Converted(source, routeId, amount, output);
    }

function _convertV4(address source, uint256 amount, bytes32 routeId, uint256 minimumETH, uint256 deadline)
        private returns (uint256 output) {
        ZZZV4RouteExecutor.Policy memory p = v4Executor.validate(routeId);
        if (p.source != source || p.output != address(0)) revert InvalidConfiguration();
        uint256 expected = IZZZOracle(access.module(Ids.ORACLE)).quote(source, address(0), amount);
        if (expected == 0) revert InvalidAmount();
        uint256 minimum = Math.max(minimumETH,
            Math.mulDiv(expected, 10_000 - conversionLossBps, 10_000, Math.Rounding.Ceil));
        uint256 sourceBefore = IERC20(source).balanceOf(address(this));
        uint256 nativeBefore = address(this).balance;
        ExactToken.pull(source, ledger, amount);
        IERC20(source).forceApprove(address(v4Executor), amount);
        nativeSender = address(v4Executor);
        output = v4Executor.execute(routeId, amount, minimum, deadline);
        nativeSender = address(0);
        IERC20(source).forceApprove(address(v4Executor), 0);
        if (output < minimum || IERC20(source).balanceOf(address(this)) != sourceBefore ||
            address(this).balance != nativeBefore + output) revert InvalidState();
        (bool ok,) = payable(ledger).call{value: output}("");
        if (!ok || address(this).balance != nativeBefore ||
            IERC20(source).balanceOf(address(this)) != sourceBefore) revert InvalidState();
        emit Converted(source, routeId, amount, output);
    }

function balance(address asset, address owner) internal view returns (uint256) {
        return asset == address(0) ? owner.balance : IERC20(asset).balanceOf(owner);
    }

function approve(address asset, address spender, uint256 amount) internal {
        if (asset != address(0)) IERC20(asset).forceApprove(spender, amount);
    }

function push(address asset, address to, uint256 amount) internal {
        if (asset != address(0)) ExactToken.push(asset, to, amount);
        else if (amount != 0) {
            uint256 beforeBalance = address(this).balance;
            (bool ok,) = payable(to).call{value: amount}("");
            if (!ok || address(this).balance != beforeBalance - amount) revert NativeTransferFailed();
        }
    }

function pull(address token, address from, uint256 amount) internal {
        if (amount == 0) return;
        uint256 beforeBalance = IERC20(token).balanceOf(address(this));
        uint256 beforeSender = IERC20(token).balanceOf(from);
        IERC20(token).safeTransferFrom(from, address(this), amount);
        if (IERC20(token).balanceOf(address(this)) != beforeBalance + amount ||
            IERC20(token).balanceOf(from) + amount != beforeSender) revert UnsupportedToken(token);
    }

function push(address token, address to, uint256 amount) internal {
        if (amount == 0) return;
        uint256 beforeSender = IERC20(token).balanceOf(address(this));
        uint256 beforeRecipient = IERC20(token).balanceOf(to);
        IERC20(token).safeTransfer(to, amount);
        if (IERC20(token).balanceOf(address(this)) + amount != beforeSender ||
            IERC20(token).balanceOf(to) != beforeRecipient + amount) revert UnsupportedToken(token);
    }

function item(uint8 rarity, uint256 index) internal pure returns (uint8 palette, uint8 pattern) {
        bytes memory entries = rarity == 0 ? COMMUN : rarity == 1 ? RARE : LEGENDARY;
        uint256 offset = index * 2;
        uint16 code = (uint16(uint8(entries[offset])) << 8) | uint8(entries[offset + 1]);
        return (uint8(code / PATTERN_COUNT), uint8(code % PATTERN_COUNT));
    }

function primaryColor(uint8 palette) internal pure returns (uint8 color) {
        uint8 colors = mask(palette);
        while ((colors & (uint8(1) << color)) == 0) ++color;
    }

function referenceX96(uint256 lower0, uint256 lower1, uint8 decimals0, uint8 decimals1, address token0)
        internal pure returns (uint160) {
        uint256 ratioX128 = Math.mulDiv(lower0, uint256(1) << 128, lower1);
        if (decimals1 >= decimals0) ratioX128 = Math.mulDiv(ratioX128, 10 ** (decimals1 - decimals0), 1);
        else ratioX128 /= 10 ** (decimals0 - decimals1);
        uint256 root = Math.sqrt(ratioX128);
        if (root == 0 || root > type(uint128).max) revert InvalidPrice(token0);
        return uint160(root << 32);
    }

function validate(address router, address factory, address pool, address source, address output, uint24 fee)
        internal view {
        address a = source < output ? source : output;
        address b = source < output ? output : source;
        // Preserve the original short-circuit call order. A mismatch stops here;
        // it must not read a later untrusted dependency after earlier rejection.
        if (IV3RouteRouter(router).factory() != factory ||
            IV3RouteFactory(factory).getPool(source, output, fee) != pool ||
            IV3RoutePool(pool).factory() != factory || IV3RoutePool(pool).token0() != a ||
            IV3RoutePool(pool).token1() != b || IV3RoutePool(pool).fee() != fee) revert ZZZModule.InvalidConfiguration();
    }
